INSERT INTO `faq` (`id`, `categoria`, `domanda`, `risposta1`, `risposta2`, `risposta3`, `data_aggiornamento`) VALUES
(1, 'generale', 'ciao', 'Ciao! Come posso aiutarti?', 'Salve! In cosa posso esserti utile?', 'Ciao! Hai bisogno di assistenza?', '2025-10-31 11:24:57'),
(3, 'generale', 'chi sei', 'Sono il Copilot Utixo, il tuo assistente digitale. Ti aiuto a trovare risposte rapide su domini, email, hosting e servizi cloud.', 'Sono il Copilot Utixo! Un assistente virtuale pensato per supportarti nelle attività tecniche e nei servizi Utixo.', 'Sono il chatbot di Utixo, progettato per darti supporto veloce su configurazioni, problemi tecnici e informazioni sui servizi.', '2025-12-05 11:45:23'),
(4, 'generale', 'cosa puoi fare', 'Posso aiutarti con domande su hosting, email, DNS, Microsoft 365 e molti altri servizi Utixo.', 'Ti supporto nella risoluzione di problemi tecnici, configurazioni e informazioni sui servizi Utixo.', 'Sono in grado di fornirti assistenza su email, dominio, hosting, pannelli di gestione e soluzioni cloud.', '2025-12-05 11:45:23'),
(5, 'generale', 'come funziona il supporto utixo', 'Il supporto Utixo è attivo tramite ticket, telefono e area clienti. I tecnici rispondono in base alla priorità e alla tipologia del servizio.', 'Puoi aprire un ticket dall’area clienti Utixo: un tecnico prenderà in carico la tua richiesta e ti aggiornerà fino alla risoluzione.', 'Il supporto avviene tramite ticket system: apri una richiesta e un tecnico Utixo ti risponderà il prima possibile.', '2025-12-05 11:45:23'),
(6, 'generale', 'come contatto assistenza', 'Puoi contattare l assistenza Utixo aprendo un ticket dall’area clienti.', 'Per ricevere supporto apri un ticket tramite la tua area riservata Utixo.', 'L assistenza tecnica risponde tramite ticket: accedi alla tua area clienti e apri una richiesta.', '2025-12-05 11:45:23'),
(7, 'generale', 'quali servizi offre utixo', 'Utixo offre hosting, email professionali, PEC, DNS, soluzioni cloud e Microsoft 365.', 'I servizi Utixo includono hosting condiviso, server cloud, email, PEC, backup, sicurezza e prodotti Microsoft.', 'Utixo fornisce servizi di hosting, posta elettronica, PEC, cloud, sicurezza IT e soluzioni Microsoft 365.', '2025-12-05 11:45:23'),
(8, 'generale', 'dove trovo area clienti', 'Puoi accedere all area clienti Utixo su https://shop.serverweb.net inserendo le tue credenziali.', 'L area clienti Utixo è disponibile sul portale ufficiale: https://shop.serverweb.net.', 'Accedi alla tua area riservata Utixo tramite https://shop.serverweb.net con username e password.', '2025-12-05 11:45:23'),
(9, 'generale', 'come recupero password area clienti', 'Clicca su Password Dimenticata nella pagina di login dell area clienti Utixo e inserisci la tua email.', 'Per recuperare la password dell area clienti premi su Recupera Password nella schermata di accesso.', 'Nella pagina di login dell area clienti trovi l’opzione Password Dimenticata per reimpostare la tua password.', '2025-12-05 11:45:23'),
(10, 'generale', 'non riesco ad accedere area clienti', 'Assicurati di usare l email con cui hai registrato il tuo account e prova a reimpostare la password.', 'Se non riesci ad accedere prova Recupero Password o verifica che l email sia quella corretta.', 'Puoi provare a reimpostare la password o aprire un ticket per assistenza all accesso.', '2025-12-05 11:45:23'),
(11, 'generale', 'dove trovo le fatture', 'Le fatture sono disponibili nell area clienti Utixo, sezione Fatture.', 'Puoi scaricare le tue fatture dall area clienti andando su Fatture > Documenti.', 'Le fatture Utixo sono visibili e scaricabili nella sezione dedicata dell area clienti.', '2025-12-05 11:45:23'),
(12, 'generale', 'come pago una fattura utixo', 'Puoi pagare le fatture tramite PayPal, carta, bonifico o direttamente dall area clienti.', 'Per pagare una fattura accedi all area clienti Utixo e clicca su Paga accanto alla fattura.', 'Le fatture Utixo possono essere saldate nell area clienti usando carta, PayPal o bonifico.', '2025-12-05 11:45:23'),
(13, 'certificati SSL', 'Cos\'è un certificato wildcard e come generare un CSR?', 'Un certificato SSL wildcard protegge tutti i sottodomini di un dominio principale. Il Common Name (CN) assume la forma *.dominio.est, dove l\'asterisco rappresenta qualsiasi sottodominio.', 'Un certificato SSL wildcard consente di proteggere tutti i sottodomini di un dominio principale. Il campo Common Name (CN) viene indicato come *.dominio.est, dove l’asterisco indica che qualsiasi sottodominio sarà coperto.', 'Il certificato SSL wildcard tutela tutti i sottodomini di un dominio principale. Nel Common Name (CN) si utilizza la forma *.dominio.est, con l’asterisco che rappresenta qualsiasi sottodominio.', '2026-01-23 10:20:49'),
(14, 'certificati SSL', 'A cosa serve un CSR?', 'un CSR (Certificate Signing Request) contiene:\r\n\r\nLa chiave pubblica associata al certificato e le informazioni identificative dell\'azienda a cui verrà rilasciato.\r\nIl CSR viene solitamente generato direttamente dal sistema che userà il certificato. Tuttavia, se il servizio non consente la creazione automatica del CSR, è possibile generarlo manualmente seguendo questa procedura.', 'Un CSR (Certificate Signing Request) include la chiave pubblica collegata al certificato e i dati identificativi dell’organizzazione destinataria. Di norma, il CSR viene creato direttamente dal sistema che utilizzerà il certificato; se ciò non fosse possibile, può essere generato manualmente seguendo una procedura specifica.', 'Il CSR (Certificate Signing Request) contiene la chiave pubblica del certificato e le informazioni relative all’azienda che ne farà uso. Solitamente viene generato automaticamente dal sistema interessato, ma qualora il servizio non lo supporti, è possibile produrlo manualmente seguendo i passaggi indicati.', '2026-01-23 10:28:45'),
(15, 'certificati SSL', 'cosa posso fare con cPanel?', 'Il pannello di controllo cPanel consente l’attivazione automatica di certificati SSL gratuiti tramite Let’s Encrypt o il sistema AutoSSL integrato. In molti casi, questi certificati possono essere utilizzati senza alcun costo aggiuntivo.', 'Il pannello di gestione cPanel permette di attivare automaticamente certificati SSL gratuiti attraverso Let’s Encrypt o il sistema AutoSSL integrato. Spesso, questi certificati possono essere utilizzati senza costi aggiuntivi.', 'Con cPanel è possibile abilitare automaticamente certificati SSL gratuiti tramite Let’s Encrypt o AutoSSL. In numerosi casi, l’uso di questi certificati non comporta alcuna spesa extra.', '2026-01-23 10:28:08'),
(16, 'certificati SSL', 'Cos\'è una richiesta di firma del certificato?', 'Una CSR è uno dei primi passaggi necessari per ottenere un certificato SSL/TLS.\r\n\r\nViene generata sul server dove il certificato verrà installato e include informazioni che l’Autorità di Certificazione (CA) utilizzerà per emettere il certificato. Contiene inoltre la chiave pubblica che sarà inclusa nel certificato, firmata con la chiave privata corrispondente.', 'La CSR rappresenta uno dei primi step per ottenere un certificato SSL/TLS. Viene creata sul server destinato all’installazione del certificato e racchiude le informazioni che l’Autorità di Certificazione (CA) utilizzerà per emetterlo. Include inoltre la chiave pubblica che sarà parte del certificato, firmata con la chiave privata corrispondente.', 'Generare una CSR è uno dei passaggi iniziali per richiedere un certificato SSL/TLS. La CSR viene prodotta sul server in cui il certificato sarà installato e contiene i dati che la CA userà per rilasciarlo, insieme alla chiave pubblica da includere nel certificato, firmata con la chiave privata associata.', '2026-01-23 10:30:35'),
(17, 'certificati SSL', 'Quali informazioni contiene una CSR?', 'Una CSR include dati essenziali relativi all’organizzazione e al dominio da certificare. Tra le informazioni principali:\r\n\r\nCommon Name (CN): nome di dominio completo (FQDN) del server.\r\nOrganizzazione (O): nome legale completo dell’azienda, senza abbreviazioni né suffissi come Inc., Srl, ecc.\r\nUnità organizzativa (OU): reparto aziendale che gestisce il certificato.\r\nCittà/Località (L): città dove si trova l’azienda (senza abbreviazioni).\r\nStato/Regione (S): stato o provincia dell’organizzazione (senza abbreviazioni).\r\nPaese (C): codice a due lettere del Paese in cui ha sede l’azienda.\r\nEmail: indirizzo e-mail di contatto.\r\nOltre ai dati anagrafici, la CSR include anche:\r\n\r\nChiave pubblica: utilizzata per crittografare le comunicazioni.\r\nTipo e lunghezza della chiave: la più comune è RSA 2048, ma sono supportate anche RSA 4096 o chiavi ECC.', 'Una CSR contiene le informazioni fondamentali relative all’organizzazione e al dominio da certificare. Tra i principali campi troviamo:\r\n\r\nCommon Name (CN): nome di dominio completo (FQDN) del server.\r\n\r\nOrganizzazione (O): nome legale completo dell’azienda, senza abbreviazioni né suffissi come Inc., Srl, ecc.\r\n\r\nUnità organizzativa (OU): reparto aziendale responsabile del certificato.\r\n\r\nCittà/Località (L): città in cui ha sede l’azienda (senza abbreviazioni).\r\n\r\nStato/Regione (S): stato o provincia dell’organizzazione (senza abbreviazioni).\r\n\r\nPaese (C): codice a due lettere del Paese di appartenenza.\r\n\r\nEmail: indirizzo e-mail di contatto.\r\n\r\nOltre ai dati identificativi, la CSR include anche:\r\n\r\nChiave pubblica: usata per crittografare le comunicazioni.\r\n\r\nTipo e lunghezza della chiave: la più comune è RSA 2048, ma possono essere utilizzate anche chiavi RSA 4096 o ECC.', 'La CSR raccoglie i dati essenziali dell’organizzazione e del dominio da certificare. Tra le informazioni principali:\r\n\r\nCN (Common Name): dominio completo del server (FQDN).\r\n\r\nO (Organizzazione): nome legale completo dell’azienda, senza abbreviazioni o suffissi.\r\n\r\nOU (Unità organizzativa): reparto incaricato della gestione del certificato.\r\n\r\nL (Città/Località): città dell’azienda (nessuna abbreviazione).\r\n\r\nS (Stato/Regione): stato o provincia dell’organizzazione.\r\n\r\nC (Paese): codice a due lettere del Paese di residenza.\r\n\r\nEmail: contatto e-mail.\r\n\r\nLa CSR comprende anche:\r\n\r\nChiave pubblica: per crittografare le comunicazioni.\r\n\r\nTipo e dimensione della chiave: tipicamente RSA 2048, ma sono supportate anche RSA 4096 o chiavi ECC.', '2026-01-23 10:32:01'),
(18, 'certificati SSL', 'Qual è il formato di una CSR?', 'La CSR è generalmente generata in formato PEM (Base-64) e può essere aperta con un semplice editor di testo. Deve sempre includere l’intestazione e il piè di pagina:\r\n\r\n-----BEGIN CERTIFICATE REQUEST-----\r\n[contenuto codificato base64]\r\n-----END CERTIFICATE REQUEST-----\r\nEsempio reale:\r\n\r\n-----BEGIN CERTIFICATE REQUEST-----\r\nMIICvDCCAaQCAQAwdzELMAkGA1UEBhMCVVMxDTALBgNVBAgMBFV0YWgxDzANBgNV...\r\n...Uo39lBi1w=\r\n-----END CERTIFICATE REQUEST-----', 'La CSR viene solitamente generata in formato PEM (Base-64) e può essere visualizzata con un normale editor di testo. Deve sempre contenere l’intestazione e il piè di pagina:\r\n\r\n-----BEGIN CERTIFICATE REQUEST-----\r\n[contenuto codificato base64]\r\n-----END CERTIFICATE REQUEST-----\r\n\r\n\r\nEsempio concreto:\r\n\r\n-----BEGIN CERTIFICATE REQUEST-----\r\nMIICvDCCAaQCAQAwdzELMAkGA1UEBhMCVVMxDTALBgNVBAgMBFV0YWgxDzANBgNV...\r\n...Uo39lBi1w=\r\n-----END CERTIFICATE REQUEST-----', 'La CSR è generalmente prodotta in formato PEM (Base-64) e può essere aperta con qualsiasi editor di testo. È essenziale includere sempre l’intestazione e il footer:\r\n\r\n-----BEGIN CERTIFICATE REQUEST-----\r\n[contenuto codificato base64]\r\n-----END CERTIFICATE REQUEST-----\r\n\r\n\r\nEsempio reale di CSR:\r\n\r\n-----BEGIN CERTIFICATE REQUEST-----\r\nMIICvDCCAaQCAQAwdzELMAkGA1UEBhMCVVMxDTALBgNVBAgMBFV0YWgxDzANBgNV...\r\n...Uo39lBi1w=\r\n-----END CERTIFICATE REQUEST-----', '2026-01-23 10:33:42'),
(19, 'certificati SSL', 'Come generare una CSR?\r\n', 'La procedura varia in base al sistema operativo o al pannello di controllo utilizzato. Abbiamo guide dettagliate per le principali piattaforme, tra cui:\r\n\r\ncPanel/WHM\r\nMicrosoft Exchange\r\nIIS (Internet Information Services)\r\nJava Keytool\r\nOpenSSL (Linux/Unix)\r\nConsulta la guida relativa al tuo ambiente per generare correttamente il file CSR.', 'La procedura cambia a seconda del sistema operativo o del pannello di controllo in uso. Disponiamo di guide dettagliate per le principali piattaforme, tra cui:\r\n\r\ncPanel/WHM\r\n\r\nMicrosoft Exchange\r\n\r\nIIS (Internet Information Services)\r\n\r\nJava Keytool\r\n\r\nOpenSSL (Linux/Unix)\r\n\r\nSegui la guida specifica per il tuo ambiente per generare correttamente il file CSR.', 'La modalità di generazione del CSR dipende dal sistema operativo o dal pannello di controllo adottato. Per le piattaforme più comuni sono disponibili guide complete, tra cui:\r\n\r\ncPanel/WHM\r\n\r\nMicrosoft Exchange\r\n\r\nIIS (Internet Information Services)\r\n\r\nJava Keytool\r\n\r\nOpenSSL (Linux/Unix)\r\n\r\nConsulta la guida corrispondente al tuo ambiente per creare correttamente il CSR.', '2026-01-23 10:35:28'),
(20, 'certificati SSL', 'Come generare una richiesta CSR per Apache2?', 'Se stai utilizzando un server Apache2 senza pannello di controllo grafico (es. cPanel), puoi generare una richiesta di firma del certificato (CSR) direttamente da linea di comando tramite SSH.\r\n\r\n \r\n\r\n1. Accedi al server via SSH\r\nUtilizza un client SSH (come PuTTY o il terminale) per connetterti al server dove verrà installato il certificato SSL.\r\n\r\n \r\n\r\n2. Comando per generare CSR e chiave privata\r\nEsegui il seguente comando:\r\n\r\nopenssl req -new -newkey rsa:2048 -nodes -keyout domain.key -out domain.csr\r\nSostituisci domain con il nome del tuo dominio (es. esempio.com). Il comando genererà due file:\r\n\r\ndomain.key → chiave privata\r\ndomain.csr → richiesta CSR\r\n \r\n\r\n3. Inserisci le informazioni richieste\r\nDopo aver eseguito il comando, ti verranno richiesti alcuni dati. Compila come segue:\r\n\r\nCommon Name (CN): il nome di dominio completo (es. www.esempio.com)\r\nWildcard: per certificati jolly, inserisci *.esempio.com\r\nOrganization (O): nome legale dell\'azienda\r\nOrganizational Unit (OU): reparto o nome commerciale (facoltativo)\r\nCity/Locality (L): città (senza abbreviazioni)\r\nState/Province (S): provincia o regione (senza abbreviazioni)\r\nCountry (C): codice ISO a due lettere (es. IT per Italia)\r\n \r\n\r\n4. Copia e incolla la CSR nel modulo di richiesta SSL\r\nApri il file domain.csr con un editor di testo (es. nano, vim o scaricalo via FTP) e copia l’intero contenuto, inclusi intestazione e piè di pagina:\r\n\r\n-----BEGIN CERTIFICATE REQUEST-----\r\n[contenuto codificato]\r\n-----END CERTIFICATE REQUEST-----\r\nIncolla questo contenuto nel modulo di richiesta SSL nel tuo account Utixo o presso il fornitore scelto.', 'Se utilizzi un server Apache2 senza pannello grafico (ad esempio cPanel), puoi generare una CSR direttamente da linea di comando tramite SSH.\r\n\r\n1. Accedi al server via SSH\r\nConnettiti al server usando un client SSH (come PuTTY o il terminale) sul server dove installerai il certificato SSL.\r\n\r\n2. Genera CSR e chiave privata\r\nEsegui il comando:\r\n\r\nopenssl req -new -newkey rsa:2048 -nodes -keyout domain.key -out domain.csr\r\n\r\n\r\nSostituisci domain con il tuo dominio (es. esempio.com). Questo creerà due file:\r\n\r\ndomain.key → chiave privata\r\n\r\ndomain.csr → richiesta CSR\r\n\r\n3. Inserisci le informazioni richieste\r\nQuando il comando ti chiederà dei dati, compila come segue:\r\n\r\nCommon Name (CN): nome di dominio completo (es. www.esempio.com\r\n)\r\n\r\nWildcard: per certificati jolly, inserisci *.esempio.com\r\n\r\nOrganization (O): nome legale dell’azienda\r\n\r\nOrganizational Unit (OU): reparto o nome commerciale (facoltativo)\r\n\r\nCity/Locality (L): città (senza abbreviazioni)\r\n\r\nState/Province (S): provincia o regione (senza abbreviazioni)\r\n\r\nCountry (C): codice ISO a due lettere (es. IT)\r\n\r\n4. Copia la CSR nel modulo di richiesta SSL\r\nApri il file domain.csr con un editor di testo (nano, vim o tramite FTP) e copia tutto il contenuto, inclusi intestazione e piè di pagina:\r\n\r\n-----BEGIN CERTIFICATE REQUEST-----\r\n[contenuto codificato]\r\n-----END CERTIFICATE REQUEST-----\r\n\r\n\r\nIncolla poi questo contenuto nel modulo di richiesta SSL del tuo account Utixo o presso il provider scelto.', 'Per server Apache2 senza pannello di controllo grafico, la CSR può essere generata via SSH direttamente da terminale.\r\n\r\n1. Connessione al server\r\nUsa un client SSH (ad esempio PuTTY o terminale) per accedere al server dove installerai il certificato SSL.\r\n\r\n2. Comando per generare CSR e chiave privata\r\n\r\nopenssl req -new -newkey rsa:2048 -nodes -keyout domain.key -out domain.csr\r\n\r\n\r\nSostituisci domain con il tuo dominio reale. Il comando produrrà:\r\n\r\ndomain.key → chiave privata\r\n\r\ndomain.csr → richiesta di certificato\r\n\r\n3. Compila i dati richiesti\r\nInserisci le informazioni richieste dal comando:\r\n\r\nCN (Common Name): dominio completo (es. www.esempio.com\r\n)\r\n\r\nWildcard: *.esempio.com per certificati jolly\r\n\r\nO (Organization): nome legale dell’azienda\r\n\r\nOU (Organizational Unit): reparto o nome commerciale (facoltativo)\r\n\r\nL (City/Locality): città (senza abbreviazioni)\r\n\r\nS (State/Province): provincia o regione (senza abbreviazioni)\r\n\r\nC (Country): codice ISO a due lettere (es. IT)\r\n\r\n4. Inserisci la CSR nel modulo SSL\r\nApri domain.csr con un editor di testo o scaricalo via FTP e copia l’intero contenuto, intestazione e piè di pagina inclusi:\r\n\r\n-----BEGIN CERTIFICATE REQUEST-----\r\n[contenuto codificato]\r\n-----END CERTIFICATE REQUEST-----\r\n\r\n\r\nIncolla il contenuto nel modulo di richiesta SSL del tuo provider o del tuo account Utixo.', '2026-01-23 10:37:24'),
(21, 'certificati SSL', 'Come posso installareun certificato SSL su GlassFish?', 'Apri la console dei comandi (cmd) e accedi alla cartella config del dominio GlassFish. Esempio:\r\n\r\ncd glassfish4\\glassfish\\domains\\domain1\\config\r\n \r\n\r\n1. Creazione della chiave (solo per prima installazione)\r\nSe non è già presente una chiave nel keystore, esegui il seguente comando per crearla:\r\n\r\nkeytool -genkey -alias nomeAlias -keyalg RSA -keysize 2048 -keystore keystore.jks -noprompt -v -dname \"CN=dominio,O=società,OU=proprietario,L=città,S=nazione,C=siglaNazione\" -storepass changeit\r\nSostituisci nomeAlias con un identificativo del dominio, ad esempio senza punti (esempiocom).\r\n\r\n \r\n\r\n2. Generazione della CSR\r\nPer richiedere un certificato, genera la CSR con il comando:\r\n\r\nkeytool -certreq -alias nomeAlias -file nomeAlias.csr -keystore keystore.jks -storepass changeit\r\nCarica la CSR nel control panel Utixo e scegli un metodo di validazione (email o DNS).\r\n\r\n \r\n\r\n3a. Importazione certificati (formato CRT separato)\r\nSe hai ricevuto i certificati in formato singolo (root, intermediate, dominio):\r\n\r\nPulisci i certificati precedenti\r\nkeytool -delete -alias root -keystore keystore.jks -storepass changeit\r\nkeytool -delete -alias intermed -keystore keystore.jks -storepass changeit\r\nkeytool -delete -alias root -keystore cacerts.jks -storepass changeit\r\nkeytool -delete -alias intermed -keystore cacerts.jks -storepass changeit\r\nImporta root, intermedi e certificato dominio\r\nkeytool -import -trustcacerts -alias root -file AAACertificateServices.crt -keystore keystore.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias intermed -file USERTrustRSAAAACA.crt -keystore keystore.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias SectigoRSADomainValidationSecureServerCA -file SectigoRSADomainValidationSecureServerCA.crt -keystore keystore.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias nomeAlias -file nomeAlias.crt -keystore keystore.jks -storepass changeit\r\n\r\nkeytool -import -trustcacerts -alias root -file AAACertificateServices.crt -keystore cacerts.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias intermed -file USERTrustRSAAAACA.crt -keystore cacerts.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias SectigoRSADomainValidationSecureServerCA -file SectigoRSADomainValidationSecureServerCA.crt -keystore cacerts.jks -storepass changeit\r\n \r\n\r\n3b. Importazione certificati (CA Bundle o P7B)\r\nSe hai ricevuto un file .ca-bundle o .p7b, procedi così:\r\n\r\nPulisci i certificati precedenti\r\nkeytool -delete -alias cabundle -keystore keystore.jks -storepass changeit\r\nkeytool -delete -alias cabundle -keystore cacerts.jks -storepass changeit\r\nImporta bundle e certificato dominio\r\nkeytool -import -trustcacerts -alias cabundle -file nomeAlias.ca-bundle -keystore keystore.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias nomeAlias -file nomeAlias.crt -keystore keystore.jks -storepass changeit\r\noppure:\r\n\r\nkeytool -import -trustcacerts -alias nomeAlias -file nomeAlias.p7b -keystore keystore.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias cabundle -file nomeAlias.ca-bundle -keystore cacerts.jks -storepass changeit\r\n \r\n\r\n4. Verifica dell\'importazione\r\nkeytool -list -alias nomeAlias -keystore keystore.jks -storepass changeit\r\n \r\n\r\n5. Associare il certificato in GlassFish\r\nAccedi alla console GlassFish e vai su:\r\n\r\nConfigurazioni → server-config → Servizio HTTP → Listener HTTP → http-listener-2 → SSL\r\n\r\nInserisci nomeAlias nella casella Alias certificato per attivarlo.\r\n\r\n \r\n\r\n6. Riavviare GlassFish\r\nRiavvia il server GlassFish per applicare le modifiche e rendere attivo il nuovo certificato SSL.', 'Apri il prompt dei comandi (cmd) e posizionati nella cartella config del dominio GlassFish, ad esempio:\r\n\r\ncd glassfish4\\glassfish\\domains\\domain1\\config\r\n\r\n\r\n1. Creazione della chiave (solo al primo setup)\r\nSe non è presente una chiave nel keystore, esegui:\r\n\r\nkeytool -genkey -alias nomeAlias -keyalg RSA -keysize 2048 -keystore keystore.jks -noprompt -v -dname \"CN=dominio,O=società,OU=proprietario,L=città,S=nazione,C=siglaNazione\" -storepass changeit\r\n\r\n\r\nSostituisci nomeAlias con un identificativo del dominio, senza punti (es. esempiocom).\r\n\r\n2. Generazione della CSR\r\nPer richiedere il certificato, crea la CSR:\r\n\r\nkeytool -certreq -alias nomeAlias -file nomeAlias.csr -keystore keystore.jks -storepass changeit\r\n\r\n\r\nCarica il file .csr nel control panel Utixo e scegli il metodo di validazione (email o DNS).\r\n\r\n3a. Importazione certificati separati (CRT)\r\nSe hai ricevuto certificati separati (root, intermedi, dominio):\r\n\r\nElimina certificati precedenti\r\n\r\nkeytool -delete -alias root -keystore keystore.jks -storepass changeit\r\nkeytool -delete -alias intermed -keystore keystore.jks -storepass changeit\r\nkeytool -delete -alias root -keystore cacerts.jks -storepass changeit\r\nkeytool -delete -alias intermed -keystore cacerts.jks -storepass changeit\r\n\r\n\r\nImporta root, intermedi e certificato dominio\r\n\r\nkeytool -import -trustcacerts -alias root -file AAACertificateServices.crt -keystore keystore.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias intermed -file USERTrustRSAAAACA.crt -keystore keystore.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias SectigoRSADomainValidationSecureServerCA -file SectigoRSADomainValidationSecureServerCA.crt -keystore keystore.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias nomeAlias -file nomeAlias.crt -keystore keystore.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias root -file AAACertificateServices.crt -keystore cacerts.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias intermed -file USERTrustRSAAAACA.crt -keystore cacerts.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias SectigoRSADomainValidationSecureServerCA -file SectigoRSADomainValidationSecureServerCA.crt -keystore cacerts.jks -storepass changeit\r\n\r\n\r\n3b. Importazione certificati in bundle (.ca-bundle o .p7b)\r\n\r\nElimina bundle precedenti\r\n\r\nkeytool -delete -alias cabundle -keystore keystore.jks -storepass changeit\r\nkeytool -delete -alias cabundle -keystore cacerts.jks -storepass changeit\r\n\r\n\r\nImporta bundle e certificato dominio\r\n\r\nkeytool -import -trustcacerts -alias cabundle -file nomeAlias.ca-bundle -keystore keystore.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias nomeAlias -file nomeAlias.crt -keystore keystore.jks -storepass changeit\r\n\r\n\r\noppure:\r\n\r\nkeytool -import -trustcacerts -alias nomeAlias -file nomeAlias.p7b -keystore keystore.jks -storepass changeit\r\nkeytool -import -trustcacerts -alias cabundle -file nomeAlias.ca-bundle -keystore cacerts.jks -storepass changeit\r\n\r\n\r\n4. Verifica dell’importazione\r\n\r\nkeytool -list -alias nomeAlias -keystore keystore.jks -storepass changeit\r\n\r\n\r\n5. Associare il certificato in GlassFish\r\nAccedi alla console GlassFish:\r\n\r\nConfigurazioni → server-config → Servizio HTTP → Listener HTTP → http-listener-2 → SSL\r\n\r\n\r\nInserisci nomeAlias nella casella “Alias certificato” per attivarlo.\r\n\r\n6. Riavvia GlassFish\r\nRiavvia il server per applicare le modifiche e rendere operativo il nuovo certificato SSL.', 'Apri cmd e vai nella cartella config\r\n\r\ncd glassfish4\\glassfish\\domains\\domain1\\config\r\n\r\n\r\nCrea chiave (solo al primo setup)\r\n\r\nkeytool -genkey -alias nomeAlias -keyalg RSA -keysize 2048 -keystore keystore.jks -noprompt -v -dname \"CN=dominio,O=società,OU=proprietario,L=città,S=nazione,C=siglaNazione\" -storepass changeit\r\n\r\n\r\nGenera CSR\r\n\r\nkeytool -certreq -alias nomeAlias -file nomeAlias.csr -keystore keystore.jks -storepass changeit\r\n\r\n\r\nCarica il .csr su Utixo e seleziona il metodo di validazione.\r\n\r\nImporta certificati\r\n\r\nSe CRT separati: elimina vecchi certificati e importa root, intermedi e dominio.\r\n\r\nSe CA bundle (.ca-bundle o .p7b): elimina vecchi bundle e importa nuovo bundle e certificato dominio.\r\n\r\nVerifica importazione\r\n\r\nkeytool -list -alias nomeAlias -keystore keystore.jks -storepass changeit\r\n\r\n\r\nAssociare certificato in GlassFish\r\nConsole → Configurazioni → server-config → Servizio HTTP → Listener HTTP → http-listener-2 → SSL → inserisci alias.\r\n\r\nRiavvia GlassFish\r\nPer rendere attivo il certificato SSL.', '2026-01-23 10:40:23'),
(22, 'certificati SSL', 'Che cos\'è il controllo CAA?', 'Il controllo CAA (Certificate Authority Authorization) è un meccanismo di sicurezza basato su DNS che consente ai proprietari di un dominio di specificare quali Autorità di Certificazione (CA) sono autorizzate a emettere certificati SSL/TLS per quel dominio.\r\n\r\nConfigurando un record CAA all’interno del DNS del proprio dominio, è possibile limitare l’emissione dei certificati solo ad alcune CA specifiche. Questo riduce il rischio che una CA non autorizzata rilasci un certificato fraudolento o non conforme.\r\n\r\nAd esempio, se si desidera autorizzare solo sectigo.com come CA, si può configurare un record come il seguente:\r\n\r\nexample.com.  CAA  0 issue \"sectigo.com\"\r\n\r\nUn CAA:\r\nAumenta la sicurezza del dominio contro emissioni non autorizzate\r\nÈ supportato da tutte le CA principali e considerato uno standard di buona pratica\r\nÈ raccomandato per i domini pubblici che richiedono certificati SSL/TLS\r\n\r\nQuando una CA riceve una richiesta per emettere un certificato SSL/TLS, esegue una query DNS sul record CAA del dominio. Se non trova il proprio nome all’interno del record, rifiuterà la richiesta di certificato.', 'Il controllo CAA (Certificate Authority Authorization) è un meccanismo di sicurezza basato su DNS che permette ai proprietari di un dominio di indicare quali Autorità di Certificazione (CA) sono autorizzate a emettere certificati SSL/TLS per quel dominio.\r\n\r\nConfigurando un record CAA nel DNS del proprio dominio, si limita l’emissione dei certificati solo alle CA specificate, riducendo il rischio di certificati emessi da CA non autorizzate o fraudolente.\r\n\r\nAd esempio, per autorizzare solo sectigo.com come CA:\r\n\r\nexample.com.  CAA  0 issue \"sectigo.com\"\r\n\r\n\r\nVantaggi del CAA:\r\n\r\nAumenta la sicurezza del dominio contro emissioni non autorizzate\r\n\r\nSupportato da tutte le principali CA ed è considerato una best practice\r\n\r\nRaccomandato per domini pubblici che richiedono certificati SSL/TLS\r\n\r\nQuando una CA riceve una richiesta di certificato, verifica il record CAA del dominio tramite DNS. Se il proprio nome non è presente, la richiesta viene rifiutata.', 'Il CAA (Certificate Authority Authorization) è un record DNS che consente ai proprietari di dominio di specificare quali CA possono emettere certificati SSL/TLS per il loro dominio.\r\n\r\nConfigurando correttamente il CAA, si impedisce a CA non autorizzate di rilasciare certificati, aumentando la sicurezza.\r\n\r\nEsempio per autorizzare solo sectigo.com:\r\n\r\nexample.com.  CAA  0 issue \"sectigo.com\"\r\n\r\n\r\nPunti chiave:\r\n\r\nProtegge il dominio da emissioni di certificati non autorizzate\r\n\r\nSupportato da tutte le principali CA\r\n\r\nRaccomandato per domini pubblici che richiedono SSL/TLS\r\n\r\nQuando una CA riceve una richiesta di certificato, controlla il record CAA tramite DNS e rifiuta la richiesta se il suo nome non è autorizzato.', '2026-01-23 10:43:19'),
(25, 'CloudFlare', 'come attivo la modalità i\'m under attack su cloudflare?', 'Accedi al portale shop.serverweb.net con le tue credenziali, cerca “Cloud” nei servizi e apri il prodotto Cloudflare Security Services. Scorri e clicca su “Manage Cloudflare”, poi vai in Firewall e nel campo “Security Level” seleziona “I\'m Under Attack”.', 'Per attivare “I\'m Under Attack”: portale Utixo → Services → Cloudflare Security Services → “Manage Cloudflare” → sezione Firewall → “Security Level” → “I\'m Under Attack”.', 'La modalità “I\'m Under Attack” si abilita dal pannello di gestione Cloudflare: entra in “Manage Cloudflare”, apri Firewall e imposta il livello di sicurezza su “I\'m Under Attack”.', '2026-02-20 10:00:00'),
(26, 'CloudFlare', 'come gestisco i dns cloudflare dal pannello utixo ucmp?', 'Dal portale Utixo vai su Home → Services, individua il servizio del dominio e clicca “Manage”. Nella pagina di gestione premi “MANAGE CLOUDFLARE”, poi apri la tile “DNS”: qui puoi aggiungere o modificare record (A, CNAME, MX, TXT, ecc.).', 'Percorso rapido: UCMP/Portale Utixo → Services → Manage sul servizio dominio → “MANAGE CLOUDFLARE” → “DNS”. Da lì aggiungi/modifichi i record DNS.', 'Per gestire i DNS Cloudflare dal pannello Utixo: entra nel servizio, apri “MANAGE CLOUDFLARE” e poi “DNS”. Inserisci i dati del record e conferma con “ADD NEW DNS RECORD/Continue”.', '2026-02-20 10:00:00'),
(27, 'CloudFlare', 'dove trovo manage cloudflare per gestire sicurezza e performance?', 'Dopo aver selezionato il servizio Cloudflare dal portale Utixo, clicca su “Manage Cloudflare” per aprire la console. Da lì gestisci DNS, caching, livello di protezione e firewall.', 'Per accedere alla console centralizzata: seleziona il servizio Cloudflare e premi “Manage Cloudflare”. Troverai le sezioni principali (DNS, Caching, Protection level, Firewall).', 'Il pulsante “Manage Cloudflare” ti porta al pannello di gestione da cui controlli le funzioni principali di Cloudflare (DNS, cache e sicurezza).', '2026-02-20 10:00:00'),
(28, 'CloudFlare', 'come blocco un paese specifico su cloudflare?', 'Nel Cloudflare Dashboard seleziona il dominio, poi vai su Security → WAF → Firewall Rules. Crea una nuova regola, imposta come condizione il paese e scegli l’azione (Allow/Block/Challenge/JS Challenge). Infine clicca “Deploy”.', 'Per bloccare un paese: Cloudflare → dominio → Security > WAF > Firewall Rules → “Create a Firewall Rule” → scegli il paese → azione “Block” (o Challenge) → “Deploy”.', 'Con le Firewall Rules puoi filtrare per nazione: crea una regola sul paese e applica l’azione desiderata (blocca, consenti o verifica con challenge).', '2026-02-20 10:00:00'),
(29, 'CloudFlare', 'quali funzionalità cloudflare sono disponibili dal pannello utixo?', 'Dal pannello Utixo puoi accedere rapidamente alle principali funzioni Cloudflare: DNS (anche DNSSEC), Crypto/SSL (Flexible/Full/Full Strict), e Firewall (regole, WAF, blocchi per IP/paese/ASN e bot management).', 'Le funzioni principali disponibili includono: DNS ad alte prestazioni con propagazione rapida, SSL/TLS (più modalità e HTTPS rewrites) e strumenti di firewall/WAF per protezione da attacchi e traffico malevolo.', 'Cloudflare tramite Utixo offre un set completo per sicurezza e gestione: DNS, cifratura SSL/TLS e firewall avanzato con WAF e regole personalizzabili.', '2026-02-20 10:00:00'),
(30, 'CloudFlare', 'cos\'è il waf di cloudflare e cosa protegge?', 'Il WAF (Web Application Firewall) di Cloudflare protegge il sito da vulnerabilità comuni come SQL injection, XSS e altre minacce note o zero-day. È aggiornato costantemente e lavora in tempo reale.', 'Il WAF di Cloudflare è un firewall applicativo che blocca attacchi web (es. SQL injection e cross-site scripting). Le regole vengono aggiornate per adattarsi a nuove minacce.', 'Con Cloudflare WAF ottieni protezione attiva contro attacchi applicativi: filtra richieste malevole e riduce i rischi legati a vulnerabilità del sito.', '2026-02-20 10:00:00'),
(31, 'CloudFlare', 'cos\'è l\'ssl offloading di cloudflare e quali porte supporta?', 'Con lo SSL offloading Cloudflare gestisce la cifratura HTTPS sul proprio edge e può fare da proxy tra visitatore e server. Le porte HTTPS supportate per il proxy/SSL sono: 443, 2053, 2083, 2087, 2096, 8443.', 'Lo SSL offloading permette a Cloudflare di terminare SSL/TLS e proteggere la navigazione; per usarlo con traffico HTTPS proxato sono supportate solo alcune porte (443, 2053, 2083, 2087, 2096, 8443).', 'Se usi Cloudflare come proxy HTTPS, verifica che il servizio stia ascoltando su una porta supportata: 443 o una tra 2053/2083/2087/2096/8443.', '2026-02-20 10:00:00'),
(32, 'Cloud Backup', 'come accedo alla console acronis per il cloud backup?', 'Per accedere direttamente alla console Acronis, visita cloud.acronis.com e fai login usando il tuo user ID e la tua password.', 'Accesso console Acronis: apri cloud.acronis.com e accedi con user ID e password.', 'La console di gestione Cloud Backup (Acronis) è raggiungibile da cloud.acronis.com: effettua l’accesso con le credenziali (user ID e password).', '2026-02-20 10:00:00'),
(33, 'Cloud Backup', 'qual è il link per entrare nel pannello acronis del cloud backup?', 'Il link diretto per la console Acronis è cloud.acronis.com. Accedi con user ID e password.', 'Per entrare nel pannello Acronis: vai su cloud.acronis.com e fai login con le tue credenziali.', 'La console Acronis per il Cloud Backup si apre da cloud.acronis.com, con accesso tramite user ID e password.', '2026-02-20 10:00:00'),
(34, 'Cloud Backup', 'che credenziali servono per entrare in acronis cloud?', 'Per entrare nella console Acronis (cloud.acronis.com) devi autenticarti con il tuo user ID e la tua password.', 'Login Acronis: user ID + password, direttamente su cloud.acronis.com.', 'L’accesso alla console Acronis richiede user ID e password (da usare su cloud.acronis.com).', '2026-02-20 10:00:00'),
(35, 'Cloud Backup', 'posso accedere ad acronis senza passare dal portale?', 'Sì: la KB indica l’accesso diretto alla console Acronis da cloud.acronis.com, effettuando il login con user ID e password.', 'Accesso diretto disponibile: apri cloud.acronis.com e accedi con user ID e password.', 'Puoi entrare direttamente nella console Acronis dal sito cloud.acronis.com, usando user ID e password.', '2026-02-20 10:00:00'),
(36, 'Email archiving', 'come accedo al sistema di email archiving?', 'Per accedere al sistema di email archiving, utilizza l’indirizzo https://mailarchive.utixo.net:8462 ed effettua il login con le credenziali (nome utente e password) fornite durante l’attivazione del prodotto.', 'Accesso rapido: apri https://mailarchive.utixo.net:8462 e fai login con username e password ricevute in fase di attivazione.', 'Il pannello di email archiving è raggiungibile da https://mailarchive.utixo.net:8462: accedi con le credenziali fornite al momento dell’attivazione.', '2026-02-20 10:00:00'),
(37, 'Email archiving', 'qual è il link per entrare nella piattaforma di archiviazione email?', 'Il link diretto alla piattaforma di email archiving è https://mailarchive.utixo.net:8462.', 'Per entrare nel sistema di archiviazione email: vai su https://mailarchive.utixo.net:8462 e accedi con le tue credenziali.', 'La piattaforma di archiviazione email è disponibile all’indirizzo https://mailarchive.utixo.net:8462 (accesso con username e password).', '2026-02-20 10:00:00'),
(38, 'Email archiving', 'che credenziali servono per il login al sistema di email archiving?', 'Per il login servono nome utente e password forniti durante l’attivazione del prodotto. L’accesso avviene da https://mailarchive.utixo.net:8462.', 'Le credenziali di accesso (username e password) vengono rilasciate in fase di attivazione e si usano su https://mailarchive.utixo.net:8462.', 'Per entrare nel sistema di email archiving devi usare le credenziali ricevute all’attivazione (nome utente e password).', '2026-02-20 10:00:00'),
(39, 'Email archiving', 'quali server di posta sono supportati per l\'archiviazione email?', 'Sono supportati Microsoft Exchange Server (2003/2007/2010/2013/2016/2019), Microsoft 365, Google Workspace (ex G Suite) e, in generale, tutti i server compatibili con IMAP o POP3.', 'Compatibilità: Exchange (2003–2019), Microsoft 365, Google Workspace e qualsiasi server IMAP/POP3.', 'Il sistema di email archiving supporta i principali ambienti (Exchange, Microsoft 365, Google Workspace) e tutti i server che espongono IMAP o POP3.', '2026-02-20 10:00:00'),
(40, 'Email archiving', 'il sistema di email archiving supporta imap o pop3?', 'Sì: il sistema è compatibile con tutti i server di posta che supportano i protocolli IMAP o POP3.', 'Se il tuo server espone IMAP o POP3, puoi archiviarne le email tramite il sistema di email archiving.', 'La compatibilità include qualsiasi server email IMAP/POP3 (oltre a Exchange/M365/Workspace).', '2026-02-20 10:00:00'),
(41, 'Email archiving', 'posso archiviare email da mdaemon icewarp o kerio connect?', 'Sì: tra i sistemi supportati sono inclusi MDaemon, IceWarp e Kerio Connect (oltre a Exchange, Microsoft 365, Google Workspace e server IMAP/POP3).', 'MDaemon, IceWarp e Kerio Connect sono indicati come sistemi compatibili per l’archiviazione email.', 'È possibile archiviare email provenienti anche da MDaemon, IceWarp e Kerio Connect.', '2026-02-20 10:00:00'),
(42, 'Email archiving', 'posso importare file pst o eml nel sistema di email archiving?', 'Sì: è possibile archiviare anche da file email, inclusi i formati .PST, .EML e altri formati standard.', 'Import supportato: file di posta come .PST e .EML (oltre ad altri formati standard).', 'Il sistema supporta l’archiviazione anche tramite file email (es. PST/EML).', '2026-02-20 10:00:00'),
(43, 'Email archiving', 'posso archiviare email partendo da client come outlook o thunderbird?', 'Sì: tra le sorgenti supportate rientrano anche client di posta come Microsoft Outlook e Mozilla Thunderbird.', 'È possibile archiviare email anche tramite client come Outlook e Thunderbird.', 'Outlook e Thunderbird sono indicati tra i client compatibili per l’archiviazione manuale o da file.', '2026-02-20 10:00:00'),
(44, 'email security web - libraesva', 'come accedo alla console libraesva per gestire quarantena whitelist e blacklist?', 'Accedi alla console Libraesva da https://spam.utixo.net. Inserisci il tuo indirizzo email e, se è il primo accesso, usa “Forgot your Password?” per impostare la password.', 'Percorso rapido: https://spam.utixo.net → inserisci email → “Forgot your Password?” → segui la mail di recupero.', 'La gestione di quarantena/whitelist/blacklist avviene dalla console Libraesva raggiungibile su https://spam.utixo.net con accesso tramite email e password (prima impostazione via “Forgot your Password?”).', '2026-02-20 10:00:00'),
(45, 'email security web - libraesva', 'non ho la password libraesva come la recupero?', 'Vai su https://spam.utixo.net, inserisci il tuo indirizzo email e clicca su “Forgot your Password?”. Riceverai un’email di recupero password.', 'Recupero password: https://spam.utixo.net → email → “Forgot your Password?” → apri la mail di reset.', 'Se non ricordi la password, usa la procedura “Forgot your Password?” sulla console https://spam.utixo.net: ti arriva una mail per reimpostarla.', '2026-02-20 10:00:00'),
(46, 'email security web - libraesva', 'nella mail di recupero libraesva cosa devo cliccare per entrare?', 'Nell’email di recupero/attivazione, clicca su “Authenticate this device” per autenticare il dispositivo e completare l’accesso al sistema.', 'Dopo il reset password, apri la mail e premi “Authenticate this device” per accedere alla console.', 'Per completare l’accesso dopo il recupero, va cliccato “Authenticate this device” dentro l’email ricevuta.', '2026-02-20 10:00:00'),
(47, 'email security web - libraesva', 'come sblocco una mail finita in quarantena su libraesva?', 'Dalla console Libraesva apri la quarantena: clicca sull’icona con le due frecce gialle per rilasciare (release) l’email e inoltrarla al destinatario.', 'Quarantena → seleziona il messaggio → icona con due frecce gialle (release) per consegnare la mail.', 'Per sbloccare una mail in quarantena, usa l’azione di rilascio (icone “due frecce gialle”): la mail viene inoltrata al destinatario.', '2026-02-20 10:00:00'),
(48, 'email security web - libraesva', 'come vedo perché una mail è stata bloccata e che spam score ha?', 'Nella lista, clicca sull’icona con la busta a sinistra: puoi vedere la causa del blocco e lo SPAM score assegnato al messaggio.', 'Per dettaglio blocco e punteggio: icona busta (a sinistra) sul messaggio.', 'Il motivo del blocco e lo spam score si consultano aprendo i dettagli del messaggio (icona busta a sinistra).', '2026-02-20 10:00:00'),
(49, 'email security web - libraesva', 'se rilascio una mail dalla quarantena viene ancora considerata spam?', 'No: le email rilasciate dalla quarantena vengono considerate come mail “Clean” (normali) e non classificate come SPAM.', 'Dopo il release, la mail viene trattata come “Clean email”.', 'Una mail rilasciata dalla quarantena viene inoltrata e non viene più classificata come spam, ma come “Clean”.', '2026-02-20 10:00:00'),
(50, 'email security web - libraesva', 'quali record mx devo impostare per usare email security suite libraesva?', 'Dopo l’attivazione del servizio, imposta gli MX nel DNS per instradare il traffico su Utixo: 10 mx1.utixo.net e 10 mx2.utixo.net (in alcune configurazioni è presente anche 20 mx1.acsitalia.net).', 'Configurazione MX (priorità): 10 mx1.utixo.net; 10 mx2.utixo.net; (eventuale) 20 mx1.acsitalia.net.', 'Gli MX vanno puntati ai server Utixo (mx1.utixo.net e mx2.utixo.net) con le priorità indicate, così l’SMTP passa dal filtro di protezione.', '2026-02-20 10:00:00'),
(51, 'email security web - libraesva', 'ricevo spam ma non lo vedo passare dalla console libraesva come mai?', 'Probabile bypass: gli spammer possono inviare direttamente all’IP del mail server saltando il filtro. Per evitare, configura il server per accettare email in ingresso solo dai server Utixo: mx1.utixo.net (46.105.87.130) e mx2.utixo.net (5.9.150.87).', 'Soluzione: blocca le consegne dirette e consenti solo le IP dei relay Utixo (46.105.87.130 e 5.9.150.87) come sorgenti autorizzate.', 'Se il server accetta posta “diretta”, è un rischio: limita l’ingresso alle sole IP dei MX Utixo (mx1/mx2) così tutto passa dalla protezione Libraesva.', '2026-02-20 10:00:00'),
(52, 'email security web - libraesva', 'come genero e attivo la dkim su libraesva esg?', 'Accedi al pannello https://spam.utixo.net e vai in System → Mail Transport → DKIM Signing. Aggiungi il dominio e genera la chiave DKIM; poi pubblica nel DNS il record DKIM indicato dal pannello.', 'Percorso: spam.utixo.net → System → Mail Transport → DKIM Signing → Aggiungi dominio → genera DKIM → copia i record DNS.', 'Per configurare DKIM: entra nella sezione DKIM Signing del pannello Libraesva, aggiungi il dominio e pubblica in DNS la chiave/record fornito.', '2026-02-20 10:00:00'),
(53, 'email security web - libraesva', 'cos è urlsand e perché i link nelle email diventano “protetti”?', 'UrlSand è una protezione avanzata che scansiona i link nelle email e blocca URL malevoli (es. spear-phishing, exploit zero-day, ransomware). La protezione avviene “al click”, non solo alla ricezione.', 'I link “riscritti” servono a farli passare da UrlSand: vengono controllati quando li apri, su qualsiasi dispositivo.', 'UrlSand protegge i collegamenti email: i link vengono verificati e filtrati al momento dell’apertura per impedire URL pericolosi.', '2026-02-20 10:00:00'),
(54, 'email security web - libraesva', 'che cos è quicksand e perché vedo l allegato utixo-attachment-warning.txt?', 'QuickSand Sandbox rimuove contenuti attivi pericolosi da PDF e documenti Office (es. JavaScript nei PDF, macro o script nei documenti). Per questo può comparire un file aggiuntivo tipo “Utixo-Attachment-Warning.txt” che segnala l’operazione.', 'Se vedi “Utixo-Attachment-Warning.txt”, è un avviso: QuickSand ha “disarmato” l’allegato eliminando parti attive potenzialmente dannose.', 'Il file warning compare quando QuickSand sanitizza allegati Office/PDF: segnala che contenuti attivi (macro/script/JS) sono stati rimossi per sicurezza.', '2026-02-20 10:00:00'),
(55, 'email security web - libraesva', 'cos è il whaling e come mi posso difendere?', 'Il whaling è una variante di phishing basata su social engineering che prende di mira dirigenti e top management per indurli a compiere azioni dannose (es. pagamenti, condivisione credenziali).', 'Difesa pratica: verifica sempre richieste “urgenti” (pagamenti/cambi IBAN) con un secondo canale (telefonata), controlla attentamente mittente e dominio.', 'Il whaling colpisce i vertici aziendali: per ridurre il rischio, conferma operazioni sensibili con procedure interne e controlli sul mittente.', '2026-02-20 10:00:00'),
(56, 'email security web - libraesva', 'come modifico una regola già creata in whitelist o blacklist su libraesva?', 'Dopo aver creato una regola in White & Black list, puoi modificarla cliccando sull’icona **matita gialla** nella riga della regola.', 'White & Black list → trova la regola → icona **matita gialla** per editare.', 'Le regole whitelist/blacklist sono modificabili dalla tabella usando l’icona **pencil** (matita gialla).', '2026-02-20 10:00:00'),
(57, 'email security web - libraesva', 'come elimino una singola regola di whitelist o blacklist su libraesva?', 'Nella sezione White & Black list puoi eliminare una regola usando l’icona **cestino rosso** nella riga della regola.', 'White & Black list → regola → **cestino rosso** per cancellare.', 'Per cancellare una whitelist/blacklist già creata, usa l’icona di eliminazione (cestino rosso) dalla tabella.', '2026-02-20 10:00:00'),
(58, 'email security web - libraesva', 'come cancello più regole whitelist blacklist insieme su libraesva?', 'Se devi eliminare più regole, selezionale mettendo la spunta nella casella a sinistra di ogni riga e poi clicca **Delete Selected** (icona cestino rosso in alto).', 'Spunta più righe → **Delete Selected** (cestino rosso) per eliminazione massiva.', 'Per cancellazioni multiple: seleziona le regole dalla colonna checkbox e usa **Delete Selected** in alto nella tabella.', '2026-02-20 10:00:00'),
(59, 'email security web - libraesva', 'nel quarantine report cosa significa release?', 'Nel Quarantine Report l’azione **Release** consegna subito il messaggio selezionato nella tua inbox.', 'Quarantine Report → Release = consegna immediata in posta in arrivo.', '“Release” nel report di quarantena vuol dire: rilascia e recapita subito l’email.', '2026-02-20 10:00:00'),
(60, 'email security web - libraesva', 'a cosa serve il quarantine report e cosa contiene?', 'Il Quarantine Report è una mail automatica di riepilogo che elenca i messaggi bloccati dal filtro antispam e ti permette di gestirli direttamente dal report.', 'È un riepilogo periodico dei messaggi in quarantena con azioni rapide (es. release/whitelist).', 'Serve per avere controllo sui blocchi senza entrare sempre in console: elenca i messaggi in quarantena e le azioni disponibili.', '2026-02-20 10:00:00'),
(61, 'email security web - libraesva', 'perché ricevo spam direttamente in casella ma non lo vedo nella console libraesva?', 'Può succedere se lo spam viene inviato direttamente all’IP del tuo mail server bypassando il filtro. Va evitato configurando il server per accettare posta **solo** dai server Utixo.', 'È un bypass “direct delivery”: gli spammer saltano il filtro colpendo l’IP pubblico del server di posta.', 'Se il server accetta consegne dirette, alcuni messaggi non passeranno da Libraesva. Blocca le consegne dirette e consenti solo i relay Utixo.', '2026-02-20 10:00:00'),
(62, 'email security web - libraesva', 'quali ip devo autorizzare per impedire consegne dirette e far passare tutto da libraesva?', 'Per ridurre il rischio di bypass, configura il mail server per accettare email in ingresso solo da: **mx1.utixo.net (46.105.87.130)** e **mx2.utixo.net (5.9.150.87)**.', 'Consenti solo gli IP dei relay Utixo: 46.105.87.130 e 5.9.150.87.', 'Per impedire “direct deliveries”: limita l’SMTP in ingresso ai soli IP dei server Utixo (mx1/mx2).', '2026-02-20 10:00:00');
INSERT INTO `faq` (`id`, `categoria`, `domanda`, `risposta1`, `risposta2`, `risposta3`, `data_aggiornamento`) VALUES
(63, 'email security web - libraesva', 'come creo un utente domain admin per gestire lo spam di tutte le caselle del dominio?', 'Accedi con un utente amministratore, poi vai su **System → Authentication → User Management**, clicca **New**, compila i campi e imposta **User Type = Domain Admin**. Nel campo username indica il dominio su cui avrà diritti amministrativi.', 'Percorso: System → Authentication → User Management → New → User Type “Domain Admin” → salva.', 'Puoi creare un amministratore di dominio dal menu User Management: crea nuovo utente e assegna il tipo “Domain Admin” indicando il dominio interessato.', '2026-02-20 10:00:00'),
(64, 'email security web - libraesva', 'chi può creare un domain admin su libraesva?', 'La creazione del Domain Admin può essere fatta **solo** dall’amministratore del server antispam.', 'Non tutti gli utenti possono farlo: serve un account con permessi da admin del sistema antispam.', 'Il Domain Admin si crea esclusivamente con privilegi amministrativi sul server antispam (operazione riservata).', '2026-02-20 10:00:00'),
(65, 'email security web - libraesva', 'cos è quicksand e perché parla di disarmed file?', 'QuickSand è un sistema di sicurezza che rimuove contenuti attivi da PDF e documenti Office (es. JavaScript nei PDF, macro o script). “Disarmed” significa che l’allegato è stato reso sicuro disabilitando funzioni potenzialmente pericolose.', 'Se vedi “QuickSand disarmed file”, vuol dire che l’allegato è stato neutralizzato (macro/script/JS rimossi o disattivati).', 'QuickSand “disarma” gli allegati per proteggere gli utenti: in rari casi macro legittime possono non funzionare, ma lo scopo è la sicurezza.', '2026-02-20 10:00:00'),
(66, 'email security web - libraesva', 'come mi difendo dal whaling secondo le best practice indicate?', 'Per difenderti dal whaling: imposta **SPF hard fail**, usa **connessioni sicure** (niente password in chiaro), abilita **2FA**, implementa un **controllo accessi** per rilevare accessi anomali e usa **strumenti specifici** di protezione email.', 'Azioni consigliate: SPF hard fail + secure connections + 2FA + access control + strumenti anti-frode.', 'Il whaling colpisce dirigenti/top management: rafforza autenticazione (SPF hard fail/2FA) e monitora accessi sospetti, oltre a usare strumenti di protezione dedicati.', '2026-02-20 10:00:00'),
(67, 'email security web - libraesva', 'in cpanel quali mx devo inserire per usare email security suite libraesva?', 'In cPanel (Zone Editor) elimina gli MX esistenti e inserisci i due record: **mx1.utixo.net** e **mx2.utixo.net**.', 'cPanel → Zone Editor → Manage → filtro MX → cancella vecchi → aggiungi mx1.utixo.net e mx2.utixo.net.', 'La configurazione MX in cPanel prevede la sostituzione degli MX con: mx1.utixo.net e mx2.utixo.net.', '2026-02-20 10:00:00'),
(68, 'google workspace', 'come accedo al pannello di controllo di Google Workspace?', 'Per accedere alla console di amministrazione Google Workspace visita https://admin.google.com ed effettua il login con l’account amministratore del dominio.', 'Apri https://admin.google.com e inserisci le credenziali admin per gestire utenti, sicurezza e servizi.', 'La gestione di Google Workspace avviene dalla Admin Console su https://admin.google.com con account amministratore.', '2026-02-20 10:00:00'),
(69, 'google workspace', 'come verifico il mio piano Google Workspace attivo?', 'Accedi alla Admin Console, vai su **Billing** e seleziona la sottoscrizione per visualizzare tipo di piano, numero licenze e ciclo di fatturazione.', 'Admin Console → Billing → seleziona abbonamento per vedere dettagli del piano.', 'La verifica del piano Workspace si fa nella sezione Billing della console amministrativa.', '2026-02-20 10:00:00'),
(70, 'google workspace', 'come aggiungo una nuova casella email in Google Workspace?', 'Dalla Admin Console vai su **Users** e clicca **Add user** per creare una nuova casella associando una licenza Workspace.', 'Admin Console → Users → Add new user → assegna licenza.', 'Le nuove email si creano nella sezione Users della console admin assegnando una licenza attiva.', '2026-02-20 10:00:00'),
(71, 'google workspace', 'come elimino un utente da Google Workspace?', 'Entra nella Admin Console, vai su **Users**, seleziona l’utente e scegli **Delete user** per rimuoverlo dal dominio.', 'Admin Console → Users → seleziona utente → Delete.', 'Per eliminare un account Workspace accedi alla sezione Users e utilizza l’opzione di cancellazione.', '2026-02-20 10:00:00'),
(72, 'google workspace', 'quali record MX devo inserire per attivare Gmail sul mio dominio?', 'Nel pannello DNS del dominio elimina gli MX esistenti e inserisci quelli forniti da Google Workspace per abilitare Gmail.', 'Zone Editor → elimina MX attuali → aggiungi MX Google per Workspace.', 'Per usare Gmail con il tuo dominio devi configurare correttamente i record MX indicati da Google Workspace nel DNS.', '2026-02-20 10:00:00'),
(73, 'google workspace', 'che record SPF devo configurare per Google Workspace?', 'Il record SPF deve includere Google: esempio `v=spf1 include:_spf.google.com ~all` pubblicato come record TXT nel DNS.', 'SPF consigliato: v=spf1 include:_spf.google.com ~all.', 'Per autorizzare Google a inviare email per il tuo dominio inserisci include:_spf.google.com nel record SPF.', '2026-02-20 10:00:00'),
(74, 'google workspace', 'cos è il transfer token per Google Workspace?', 'Il transfer token è un codice che consente di trasferire la gestione del tuo account Workspace a un nuovo rivenditore senza interrompere il servizio.', 'Serve per autorizzare il cambio di partner Workspace mantenendo attivo l’account.', 'Il token di trasferimento viene generato nella console Google per consentire la migrazione della gestione del servizio.', '2026-02-20 10:00:00'),
(75, 'google workspace', 'come eseguo l upgrade da G Suite a Google Workspace?', 'Accedi alla Admin Console, vai su **Billing** e seleziona il nuovo piano Workspace seguendo la procedura di aggiornamento.', 'Admin Console → Billing → scegli nuovo piano → conferma upgrade.', 'L’upgrade a Workspace si effettua dalla sezione Billing della console amministrativa.', '2026-02-20 10:00:00'),
(76, 'google workspace', 'cos è il piano flexible di Google Workspace?', 'Il Flexible Plan è un abbonamento mensile che consente di aumentare o diminuire le licenze senza vincoli annuali.', 'Con il piano flessibile paghi solo gli utenti attivi nel mese.', 'Il Flexible Plan offre fatturazione mensile variabile in base al numero di licenze utilizzate.', '2026-02-20 10:00:00'),
(77, 'google workspace', 'perché acquistare Google Workspace tramite un partner come Utixo?', 'Un partner autorizzato offre gestione commerciale e supporto diretto mantenendo invariati i servizi ufficiali Google Workspace.', 'Il servizio tecnico resta identico a Google, ma il partner fornisce assistenza e gestione amministrativa.', 'Acquistare tramite partner può semplificare fatturazione e supporto senza modificare le funzionalità Workspace.', '2026-02-20 10:00:00'),
(78, 'cPanel & WHM', 'come configuro un client di posta e accedo alla webmail su hosting cpanel?', 'Dopo aver creato la casella in cPanel, puoi accedere via browser su https://mail.dominio.ext/webmail inserendo email completa e password.', 'Parametri consigliati (SSL): IMAP 993 / POP3 995 / SMTP 465 su mail.dominio.ext, autenticazione obbligatoria.', 'Configurazione base (non SSL, sconsigliata): IMAP 143 / POP3 110 / SMTP 587 su mail.dominio.ext, con autenticazione.', '2026-02-20 10:00:00'),
(79, 'cPanel & WHM', 'come posso esportare la lista di tutti gli indirizzi email in cpanel usando ai?', 'In cPanel puoi visualizzare gli account email e, se ti serve un export, puoi generare un elenco e formattarlo (es. CSV) usando una procedura guidata con ChatGPT come supporto.', 'Obiettivo: ottenere una lista completa degli account email presenti nel dominio e salvarla in un formato esportabile (es. CSV).', 'Se ti serve un output “pulito”, prepara i dati di partenza da cPanel e usa un prompt per trasformarli in elenco/CSV ordinato.', '2026-02-20 10:00:00'),
(80, 'cPanel & WHM', 'come ripristino un backup cpanel da riga di comando via ssh?', 'Puoi eseguire backup/ripristino di un account cPanel via SSH utilizzando gli strumenti di sistema previsti da cPanel (operazione per admin/root).', 'Prima verifica spazio disco e percorso del backup, poi lancia la procedura di restore sull’account interessato.', 'È una procedura avanzata: consigliata solo con accesso root e dopo aver verificato che il backup sia integro.', '2026-02-20 10:00:00'),
(81, 'cPanel & WHM', 'come posso vedere un sito in costruzione non ancora configurato su dns pubblici?', 'Per lavorare su un sito prima della propagazione DNS puoi usare un metodo di “preview” (URL temporaneo o puntamento locale).', 'Soluzione tipica: visualizzare il sito senza DNS pubblici completati, utile per agenzie e ambienti di staging.', 'Verifica che il server risponda correttamente e che il virtual host sia configurato per il dominio/sito.', '2026-02-20 10:00:00'),
(82, 'cPanel & WHM', 'come cerco una stringa dentro i file da terminale su hosting linux?', 'Da terminale puoi usare strumenti come grep per cercare una stringa dentro file e directory (utile per trovare codice, errori o configurazioni).', 'Esempio: ricerca ricorsiva dentro una cartella e stampa i file dove compare la stringa.', 'Per risultati puliti filtra per estensione (es. .php, .log) o usa opzioni per ignorare maiuscole/minuscole.', '2026-02-20 10:00:00'),
(83, 'cPanel & WHM', 'come ripristino file email o tutto l account con jetbackup da cpanel?', 'Accedi a cPanel, apri la sezione JetBackup, scegli cosa ripristinare (file, database, email) oppure “Full Account Backup”.', 'Seleziona il punto di ripristino (data), accetta le condizioni e avvia con Add: l’operazione viene messa in coda.', 'Attenzione: un restore può eliminare e ricreare i dati al punto scelto; tutto ciò creato dopo quel punto può andare perso.', '2026-02-20 10:00:00'),
(84, 'cPanel & WHM', 'come carico e modifico file dal file manager di cpanel?', 'In cPanel apri File Manager, entra nella directory corretta (es. public_html) e usa Upload per caricare file.', 'Puoi selezionare un file e usare Edit/Code Editor per modifiche rapide direttamente dal browser.', 'Per evitare problemi di permessi, verifica ownership e permessi dei file/cartelle dopo upload.', '2026-02-20 10:00:00'),
(85, 'cPanel & WHM', 'come visualizzo i file del sito con il file manager di cpanel?', 'Accedi a cPanel e apri File Manager: naviga nelle cartelle (es. public_html) per vedere struttura e contenuti del sito.', 'Usa View per leggere un file o Download per scaricarlo sul PC.', 'Se non vedi alcuni file, abilita la visualizzazione dei file nascosti (dotfiles) nelle impostazioni del File Manager.', '2026-02-20 10:00:00'),
(86, 'cPanel & WHM', 'come accedo a cpanel dal sito utixo?', 'Accedi all’area clienti Utixo, seleziona il servizio di hosting Linux e usa la voce cPanel dal menu.', 'Clicca su “Control Panel Access” e poi su “Click here” per aprire il pannello.', 'Se hai più servizi, assicurati di selezionare l’hosting corretto prima di aprire cPanel.', '2026-02-20 10:00:00'),
(87, 'cPanel & WHM', 'come permetto agli utenti di disabilitare apache spamassassin in cpanel?', 'Da WHM puoi gestire i permessi/feature per consentire o meno agli utenti di attivare/disattivare SpamAssassin.', 'La gestione passa tipicamente da feature list o impostazioni del servizio email nel pannello WHM.', 'Applica la modifica al pacchetto/feature list usato dagli account interessati e verifica in cPanel.', '2026-02-20 10:00:00'),
(88, 'cPanel & WHM', 'come navigo un sito tramite file hosts prima della propagazione del dominio?', 'Puoi modificare il file hosts del tuo PC per forzare il dominio a puntare a un IP specifico prima che il DNS si propaghi.', 'Così il browser risolve il dominio verso l’IP scelto solo sul tuo computer (utile per test e staging).', 'Ricordati di rimuovere la riga dal file hosts quando hai finito i test, per tornare alla risoluzione DNS normale.', '2026-02-20 10:00:00'),
(89, 'cPanel & WHM', 'come cambio la password di una casella email da cpanel?', 'In cPanel vai su Email Accounts, trova la casella e usa Manage/Password per impostare una nuova password.', 'Scegli una password robusta e salva; poi aggiorna i client di posta (Outlook/telefono) con la nuova password.', 'Se usi webmail, dopo il cambio fai logout/login per verificare che la nuova password funzioni.', '2026-02-20 10:00:00'),
(90, 'cPanel & WHM', 'come cambio default_charset in php.ini da cpanel?', 'Da cPanel puoi gestire alcune impostazioni PHP (a seconda del piano) e aggiornare parametri come default_charset.', 'Dopo la modifica, salva e verifica con un phpinfo o controllando il comportamento del sito.', 'Se l’opzione non è disponibile in cPanel, potrebbe essere necessaria una modifica lato server (WHM/root).', '2026-02-20 10:00:00'),
(91, 'cPanel & WHM', 'backup su hosting condiviso come si collega a gdpr e buone pratiche?', 'Le procedure di backup devono rispettare principi di sicurezza e minimizzazione: proteggi accessi, cifratura e conservazione.', 'Assicurati che i dati personali inclusi nei backup siano trattati in modo conforme (accessi limitati, retention coerente).', 'Mantieni procedure di restore testate e documentate per ridurre downtime e rischi di perdita dati.', '2026-02-20 10:00:00'),
(92, 'cPanel & WHM', 'ho cancellato file ma la quota disco in cpanel non cambia come aggiorno?', 'La quota mostrata da cPanel può non aggiornarsi in tempo reale; puoi forzare un ricalcolo/aggiornamento della quota.', 'Dopo pulizia di file/cestino, esegui l’azione di aggiornamento quota o attendi il refresh del sistema.', 'Se la quota resta errata, controlla file nascosti o cartelle .trash che continuano a occupare spazio.', '2026-02-20 10:00:00'),
(93, 'cPanel & WHM', 'errore dominio ha superato max defers and failures per hour cosa significa?', 'Significa che il dominio ha superato il numero massimo di messaggi differiti (defers) e falliti in un’ora.', 'Riduci errori di consegna: verifica code SMTP, credenziali, reputazione, errori di routing e indirizzi destinatari.', 'Se necessario, attendi il reset della finestra oraria e risolvi la causa per evitare che si ripresenti.', '2026-02-20 10:00:00'),
(94, 'cPanel & WHM', 'quali sono i limiti del servizio email su hosting condiviso?', 'Su shared hosting esistono limiti per prevenire abusi (es. invii orari/giornalieri, connessioni, rate).', 'Se superi i limiti potresti vedere blocchi temporanei o errori in invio/ricezione.', 'Per esigenze più alte valuta un relay SMTP dedicato o un servizio email professionale.', '2026-02-20 10:00:00'),
(95, 'cPanel & WHM', 'che differenza c è tra antispam standard cpanel e protezione avanzata libraesva?', 'Su piani standard l’antispam base è spesso Apache SpamAssassin; per protezione più avanzata è disponibile Libraesva (SaaS).', 'SpamAssassin assegna punteggi e filtra; Libraesva aggiunge funzioni evolute per phishing, malware e controllo link/allegati.', 'Se ricevi molto spam o phishing, la soluzione avanzata è consigliata rispetto al filtro base.', '2026-02-20 10:00:00'),
(96, 'cPanel & WHM', 'errore max_user_connections su mysql cosa vuol dire?', 'L’errore indica che l’utente MySQL ha superato il massimo numero di connessioni contemporanee consentite.', 'Risolvi ottimizzando l’applicazione (chiusura connessioni, pooling), riducendo query lente e controllando picchi di traffico.', 'Se serve, valuta aumento del limite lato server (WHM) o revisione della configurazione DB.', '2026-02-20 10:00:00'),
(97, 'cPanel & WHM', 'come esporto un database mysql da cpanel?', 'Puoi esportare un database da cPanel tramite phpMyAdmin o strumenti di backup/export previsti dal pannello.', 'In phpMyAdmin selezioni il DB e usi Export per scaricare un file .sql.', 'Per DB grandi, usa metodi compressi o export via SSH per evitare timeout.', '2026-02-20 10:00:00'),
(98, 'cPanel & WHM', 'quali file nascosti occupano spazio e come elimino .trash su cpanel?', 'Alcune cartelle nascoste (es. .trash) possono occupare molto spazio anche dopo aver cancellato file.', 'Controlla nel File Manager (mostra file nascosti) ed elimina contenuti non necessari, poi svuota eventuali cestini.', 'Dopo la pulizia, aggiorna quota disco o attendi l’aggiornamento per vedere lo spazio liberato.', '2026-02-20 10:00:00'),
(99, 'cPanel & WHM', 'come libero spazio disco con accesso root al server?', 'Con accesso root puoi individuare le directory che consumano più spazio e intervenire su log, cache, backup e file temporanei.', 'Esegui analisi uso disco (du/df) e pulisci in modo sicuro evitando percorsi critici di sistema.', 'Prima di cancellare, verifica cosa è generato automaticamente (logrotate, cache applicative) e imposta retention corretta.', '2026-02-20 10:00:00'),
(100, 'cPanel & WHM', 'come controllo l utilizzo disco del mio account cpanel?', 'In cPanel usa gli strumenti di “Disk Usage” per vedere quanto spazio occupano cartelle e file principali.', 'Individua le directory più pesanti (backup, log, media, cache) e valuta pulizia o ottimizzazione.', 'Se sei vicino al limite quota, riduci file inutili e usa backup esterni invece di conservarli sullo stesso hosting.', '2026-02-20 10:00:00'),
(101, 'cPanel & WHM', 'come configuro web disk webdav in cpanel per gestire file da pc o smartphone?', 'In cPanel vai su Web Disk (Files), crea un account indicando username, dominio, password, directory e permessi (RO/RW).', 'Per Windows abilita digest authentication e usa “Configure Client Access” per scaricare lo script di configurazione.', 'Su mobile usa app WebDAV (es. iOS Documents / Android WebDAV Navigator) con credenziali Web Disk.', '2026-02-20 10:00:00'),
(102, 'cPanel & WHM', 'come creo un indirizzo email da cpanel?', 'In cPanel crea una nuova casella scegliendo nome (es. info), dominio, quota (Unlimited o custom) e password forte.', 'Se hai più domini nello stesso hosting, seleziona dal menu a tendina quello corretto.', 'Dopo creazione, configura webmail o client (IMAP consigliato se usi più dispositivi).', '2026-02-20 10:00:00'),
(103, 'cPanel & WHM', 'come creo e gestisco un filtro email in cpanel?', 'In cPanel puoi creare filtri email per applicare regole su messaggi in ingresso (es. sposta, elimina, inoltra).', 'Definisci condizioni (mittente, oggetto, parole) e azioni, poi salva la regola.', 'Testa la regola con una mail di prova per assicurarti che non blocchi messaggi legittimi.', '2026-02-20 10:00:00'),
(104, 'cPanel & WHM', 'come disabilito le email di notifica autossl in cpanel?', 'Se ricevi troppe notifiche AutoSSL, puoi disattivare le email di notifica dalle impostazioni relative ad AutoSSL.', 'La modifica riguarda la notifica, non l’emissione del certificato: verifica comunque stato SSL del dominio.', 'Dopo la disattivazione, controlla che le scadenze siano monitorate tramite pannello o alert alternativi.', '2026-02-20 10:00:00'),
(105, 'cPanel & WHM', 'come disabilito il directory indexing di apache via whm?', 'Da WHM puoi disabilitare il directory listing per aumentare la sicurezza ed evitare l’elenco file nelle cartelle senza index.', 'Applica l’impostazione a livello di server o template di configurazione web, poi verifica su una directory test.', 'Dopo il cambio, controlla che non ci siano cartelle che dipendono dal listing (di solito è sconsigliato lasciarlo attivo).', '2026-02-20 10:00:00'),
(106, 'cPanel & WHM', 'come libero spazio disco da cpanel senza accesso root?', 'Da cPanel puoi liberare spazio eliminando backup vecchi, file inutili, log scaricati, cache e directory pesanti.', 'Usa Disk Usage per capire cosa occupa di più e File Manager per cancellare in sicurezza.', 'Se usi JetBackup, evita di conservare copie locali troppo grandi: scaricale e rimuovile dal server.', '2026-02-20 10:00:00'),
(107, 'cPanel & WHM', 'come proteggo una cartella con password usando .htaccess in cpanel?', 'In cPanel puoi password-proteggere una directory creando autenticazione (htpasswd) e regole .htaccess.', 'Imposta utente/password e applica la protezione alla cartella desiderata; poi verifica accesso da browser.', 'Se il sito usa cache o CMS, controlla che non blocchi risorse pubbliche necessarie (css/js).', '2026-02-20 10:00:00'),
(108, 'cPanel & WHM', 'come riduco lo spam e miglioro la deliverability delle email?', 'Riduci spam e migliora consegna configurando correttamente DNS (SPF/DKIM/DMARC), usando password forti e limitando invii anomali.', 'Evita invii massivi da shared hosting, controlla blacklist e monitora errori/defers in uscita.', 'Se serve, usa un servizio antispam/antiphishing avanzato e/o un relay SMTP professionale.', '2026-02-20 10:00:00'),
(109, 'cPanel & WHM', 'come resetto la scelta dell applicazione webmail predefinita in cpanel?', 'Se hai impostato un webmail predefinito (Roundcube/Horde ecc.) e vuoi reimpostarlo, usa l’opzione di reset della selezione webmail.', 'Dopo il reset, al prossimo accesso webmail ti verrà richiesto di scegliere di nuovo l’applicazione.', 'Utile quando l’app selezionata non funziona come previsto o vuoi cambiare client webmail.', '2026-02-20 10:00:00'),
(110, 'cPanel & WHM', 'come cerco dati dentro un database con phpmyadmin?', 'In phpMyAdmin puoi usare la funzione Search per cercare testo/valori dentro tabelle e campi del database.', 'Seleziona il database, apri Search, inserisci il valore e scegli le tabelle/campi da includere.', 'Per risultati migliori, limita la ricerca alle tabelle rilevanti e verifica encoding/collation se ci sono caratteri speciali.', '2026-02-20 10:00:00'),
(111, 'cPanel & WHM', 'come cambio il logo webmail in whm cp nel webmail di cpanel?', 'Serve accesso root: collegati via SSH/WinSCP e vai in /usr/local/cpanel/base/unprotected/cpanel/images/.', 'Sostituisci il file webmail-logo.svg con il tuo logo personalizzato (formato SVG).', 'Dopo la sostituzione, il nuovo logo comparirà nell’interfaccia Webmail di cPanel.', '2026-02-20 10:00:00'),
(112, 'cPanel & WHM', 'come creo un inoltro email forwarder con cpanel?', 'In cPanel vai su Forwarders, crea un nuovo inoltro scegliendo l’indirizzo sorgente e la destinazione.', 'Puoi inoltrare verso un’altra casella interna o un indirizzo esterno.', 'Dopo la creazione, testa con una mail di prova e verifica eventuali loop di inoltro.', '2026-02-20 10:00:00'),
(113, 'cPanel & WHM', 'come creo e scarico un backup completo sito ed email da cpanel?', 'In cPanel apri JetBackup, vai su Full Backups, seleziona il backup da esportare e clicca Generate Download.', 'Quando la generazione è completata compare Download: scarichi sito completo e dati email in locale.', 'È consigliato conservare il backup anche fuori dal server (PC o storage esterno) per sicurezza.', '2026-02-20 10:00:00'),
(114, 'cPanel & WHM', 'come abilito la protezione antispam base in cpanel con spamassassin?', 'Accedi a cPanel (da area clienti Utixo), vai in Email e apri Apache SpamAssassin.', 'Attiva “Process New Emails and Mark them as Spam” per abilitare il filtro.', 'Puoi impostare Auto-delete sopra una soglia di punteggio (es. 6) per eliminare automaticamente lo spam alto.', '2026-02-20 10:00:00'),
(115, 'cPanel & WHM', 'come gestisco i cron jobs in cpanel?', 'In cPanel apri Cron Jobs e imposta la pianificazione (minuto/ora/giorno/mese) e il comando da eseguire.', 'Usa comandi con percorsi assoluti e redireziona output (log) per debugging.', 'Prima prova il comando manualmente e poi programma l’esecuzione con frequenza adeguata.', '2026-02-20 10:00:00'),
(116, 'cPanel & WHM', 'come gestisco i file del server con filezilla?', 'Installa FileZilla, crea una connessione (FTP/SFTP) con host, username e password del tuo hosting.', 'Carica/scarica file trascinandoli; mantieni la struttura corretta (es. public_html).', 'Preferisci SFTP quando disponibile e conserva le credenziali in modo sicuro.', '2026-02-20 10:00:00'),
(117, 'cPanel & WHM', 'come modifico il livello di php error reporting?', 'Puoi regolare l’error reporting PHP per mostrare/nascondere avvisi e errori (utile in sviluppo, da limitare in produzione).', 'Dopo la modifica, verifica che non vengano esposti dettagli sensibili agli utenti finali.', 'In produzione è consigliato loggare gli errori invece di mostrarli a schermo.', '2026-02-20 10:00:00'),
(118, 'cPanel & WHM', 'dove si trovano i file fisici dei database mysql sul server?', 'I file di MySQL (datadir) risiedono in una directory specifica del server configurata da MySQL.', 'È un’informazione utile per admin/root per backup, diagnostica e gestione storage.', 'Su shared hosting normalmente non è necessario accedere direttamente ai file: usa cPanel/phpMyAdmin/backup.', '2026-02-20 10:00:00'),
(119, 'cPanel & WHM', 'come accedo a phpmyadmin da cpanel?', 'phpMyAdmin è disponibile in cPanel: apri la sezione Database e clicca phpMyAdmin per entrare.', 'Da lì puoi gestire database, tabelle, query, import/export.', 'Se hai più database, seleziona quello corretto dalla colonna sinistra prima di operare.', '2026-02-20 10:00:00'),
(120, 'cPanel & WHM', 'la dimensione di una casella email in cpanel è sbagliata come la ricalcolo?', 'A volte cPanel mostra dimensioni errate della casella: puoi forzare il ricalcolo della size dell’account email.', 'Dopo il ricalcolo, la quota usata dovrebbe aggiornarsi correttamente.', 'Se resta sballata, verifica cartelle grandi (Sent/Trash/Junk) e pulisci contenuti inutili.', '2026-02-20 10:00:00'),
(121, 'cPanel & WHM', 'come abilito l accesso remoto a un database mysql?', 'Per accesso remoto devi autorizzare host/IP esterni (Remote MySQL) e usare un utente con permessi adeguati.', 'Aggiungi l’IP autorizzato e verifica che firewall/porta MySQL permettano la connessione.', 'Per sicurezza limita agli IP necessari e usa password robuste; se possibile usa tunnel SSH.', '2026-02-20 10:00:00'),
(122, 'cPanel & WHM', 'backup hosting cpanel quanto dura la retention e cosa significa?', 'La retention indica per quanto tempo vengono conservati i backup (numero di giorni/restore point disponibili).', 'Più retention = più punti di ripristino, ma anche maggiore uso di storage e policy di conservazione.', 'Per esigenze particolari valuta backup esterno o soluzioni dedicate oltre al backup standard.', '2026-02-20 10:00:00'),
(123, 'cPanel & WHM', 'come scarico e visualizzo i log del sito in cpanel?', 'In cPanel puoi scaricare e consultare access log e error log del sito per diagnosticare problemi.', 'Scarica i raw access logs o visualizza gli errori direttamente dagli strumenti di log.', 'Usa i log per individuare 404, errori 500, bot aggressivi e problemi di permessi/configurazione.', '2026-02-20 10:00:00'),
(124, 'cPanel & WHM', 'come passo un sito da http a https e risolvo mixed content?', 'Per migrare a HTTPS abilita SSL, forza redirect da HTTP a HTTPS e correggi risorse in chiaro (mixed content).', 'Aggiorna URL assoluti (immagini/css/js) e verifica configurazione CMS (WordPress: siteurl/home).', 'Dopo la migrazione, testa pagine chiave e controlla console del browser per eventuali risorse ancora in HTTP.', '2026-02-20 10:00:00'),
(125, 'cPanel & WHM', 'cos è whm e a cosa serve rispetto a cpanel?', 'WHM (Web Host Manager) è il pannello per amministrare più account cPanel da un’unica dashboard, tipico di reseller/admin.', 'Con WHM gestisci creazione account, risorse, pacchetti, sicurezza e configurazioni server.', 'cPanel è il pannello del singolo account; WHM è per la gestione “server/hosting multi-account”.', '2026-02-20 10:00:00'),
(126, 'cPanel & WHM', 'come cambio l ip di uscita usato per inviare email su cpanel whm?', 'Accedi a WHM → Exim Configuration Manager e abilita “Reference /etc/mailips for outgoing SMTP connections”.', 'Via SSH modifica /etc/mailips e aggiungi una riga tipo: *: 203.0.113.33 sostituendo l’IP desiderato.', 'Se sei in NAT, inserisci l’IP privato invece dell’IP pubblico.', '2026-02-20 10:00:00'),
(127, 'hosting linux', 'posso rivendere hosting linux ai miei clienti?', 'Sì. Con un piano Rivenditore Hosting Linux puoi creare account hosting separati per ogni cliente e gestirli da un unico pannello. È una soluzione pensata per web agency, sviluppatori e professionisti che vogliono offrire servizi hosting.', 'Sì, i piani reseller Linux permettono di rivendere hosting ai tuoi clienti. Puoi creare più account indipendenti e gestire domini, email e siti web da un pannello centrale.', 'Con l’hosting rivenditore Linux puoi offrire servizi hosting ai tuoi clienti creando account separati per ogni sito e gestendoli facilmente da un unico pannello.', '2026-03-06 10:31:29'),
(128, 'wordpress', 'cos è wordpress?', 'WordPress è un CMS (Content Management System) che permette di creare e gestire siti web e blog senza dover programmare.', 'WordPress è una piattaforma open source usata per creare siti web, blog e negozi online in modo semplice.', 'Con WordPress puoi costruire e gestire un sito web tramite un pannello di controllo senza conoscere linguaggi di programmazione.', '2026-03-06 10:33:33'),
(129, 'wordpress', 'wordpress è gratuito?', 'WordPress è un software open source gratuito, ma per usarlo serve un hosting e un dominio.', 'La piattaforma WordPress è gratuita, ma per pubblicare il sito online è necessario avere un servizio hosting.', 'Il CMS WordPress non ha costi di licenza, ma servono dominio e hosting per far funzionare il sito.', '2026-03-06 10:33:33'),
(130, 'wordpress', 'come installo wordpress sul mio hosting?', 'Puoi installare WordPress dal pannello di controllo del tuo hosting usando gli strumenti di installazione automatica.', 'Molti hosting permettono l’installazione automatica di WordPress con pochi clic dal pannello di gestione.', 'WordPress può essere installato facilmente tramite installer automatici disponibili nel pannello hosting.', '2026-03-06 10:33:33'),
(131, 'wordpress', 'come accedo al pannello di amministrazione wordpress?', 'Puoi accedere al pannello WordPress visitando il tuo dominio seguito da /wp-admin e inserendo username e password.', 'Per entrare nell’area di amministrazione WordPress usa l’indirizzo tuodominio/wp-admin.', 'L’accesso alla dashboard WordPress avviene tramite tuodominio/wp-admin con le credenziali amministratore.', '2026-03-06 10:33:33'),
(132, 'wordpress', 'come aggiorno wordpress?', 'Puoi aggiornare WordPress direttamente dalla dashboard nella sezione aggiornamenti.', 'Gli aggiornamenti di WordPress si eseguono dal pannello amministratore cliccando su Aggiorna.', 'WordPress segnala gli aggiornamenti disponibili nella dashboard e puoi installarli con un clic.', '2026-03-06 10:33:33'),
(133, 'wordpress', 'come aggiorno plugin e temi wordpress?', 'Plugin e temi possono essere aggiornati dalla sezione aggiornamenti della dashboard WordPress.', 'Accedi alla dashboard WordPress e aggiorna plugin e temi dalla sezione dedicata.', 'WordPress mostra gli aggiornamenti disponibili per plugin e temi nel pannello amministratore.', '2026-03-06 10:33:33'),
(134, 'wordpress', 'come cambio il tema wordpress?', 'Puoi cambiare il tema dalla dashboard andando su Aspetto → Temi.', 'Per cambiare grafica al sito vai in Aspetto → Temi e attiva quello desiderato.', 'I temi WordPress si gestiscono dal menu Aspetto nel pannello di amministrazione.', '2026-03-06 10:33:33'),
(135, 'wordpress', 'come installo un plugin wordpress?', 'Vai nella dashboard WordPress su Plugin → Aggiungi nuovo e cerca il plugin da installare.', 'I plugin si installano dal menu Plugin → Aggiungi nuovo nella dashboard WordPress.', 'Per installare un plugin WordPress accedi alla sezione Plugin e clicca su Aggiungi.', '2026-03-06 10:33:33'),
(136, 'wordpress', 'wordpress è sicuro?', 'WordPress è sicuro se mantenuto aggiornato e se si utilizzano plugin e password affidabili.', 'La sicurezza di WordPress dipende da aggiornamenti regolari, plugin affidabili e buone pratiche di sicurezza.', 'Per aumentare la sicurezza di WordPress è importante aggiornare core, plugin e temi.', '2026-03-06 10:33:33'),
(137, 'wordpress', 'come faccio il backup del sito wordpress?', 'Puoi eseguire il backup del sito tramite il pannello hosting o usando plugin di backup WordPress.', 'Il backup WordPress può essere fatto con plugin dedicati oppure tramite il sistema di backup dell’hosting.', 'È consigliato effettuare backup regolari di file e database del sito WordPress.', '2026-03-06 10:33:33'),
(138, 'wordpress', 'wordpress supporta ecommerce?', 'Sì, WordPress può diventare un negozio online usando plugin come WooCommerce.', 'Per creare un ecommerce su WordPress puoi installare il plugin WooCommerce.', 'WordPress supporta siti ecommerce tramite plugin dedicati come WooCommerce.', '2026-03-06 10:33:33'),
(139, 'wordpress', 'posso usare wordpress per un blog?', 'Sì, WordPress nasce proprio come piattaforma per creare blog.', 'WordPress è uno degli strumenti più usati al mondo per gestire blog.', 'La gestione di articoli e categorie rende WordPress ideale per i blog.', '2026-03-06 10:33:33'),
(140, 'wordpress', 'wordpress è open source?', 'Sì, WordPress è un software open source sviluppato da una community globale.', 'Essendo open source, WordPress può essere modificato e personalizzato liberamente.', 'WordPress è un progetto open source disponibile gratuitamente.', '2026-03-06 10:33:33'),
(141, 'wordpress', 'quali requisiti server servono per wordpress?', 'WordPress richiede PHP e un database MySQL o MariaDB per funzionare.', 'Per installare WordPress serve un hosting con PHP e database MySQL o MariaDB.', 'La piattaforma WordPress funziona su server che supportano PHP e database MySQL.', '2026-03-06 10:33:33'),
(142, 'wordpress', 'posso usare wordpress con hosting linux?', 'Sì, WordPress funziona perfettamente su hosting Linux con PHP e MySQL.', 'Gli hosting Linux sono tra le soluzioni più utilizzate per ospitare siti WordPress.', 'WordPress è pienamente compatibile con hosting Linux.', '2026-03-06 10:33:33'),
(143, 'wordpress', 'come cambio la password amministratore wordpress?', 'Puoi cambiare la password dalla dashboard WordPress nella sezione utenti.', 'Accedi al tuo profilo utente WordPress e modifica la password.', 'La password amministratore WordPress si modifica dal profilo utente nella dashboard.', '2026-03-06 10:33:33'),
(144, 'wordpress', 'perché wordpress è così diffuso?', 'WordPress è diffuso perché è facile da usare, flessibile e supportato da migliaia di plugin e temi.', 'La popolarità di WordPress deriva dalla sua semplicità e dalla grande comunità di sviluppatori.', 'WordPress è uno dei CMS più usati al mondo grazie alla sua facilità di utilizzo e personalizzazione.', '2026-03-06 10:33:33'),
(145, 'microsoft 365', 'cos è microsoft 365?', 'Microsoft 365 è una piattaforma cloud che include email professionale, applicazioni Office e servizi di collaborazione.', 'Microsoft 365 è un servizio in abbonamento che offre Outlook, Word, Excel, Teams e altri strumenti cloud.', 'È una suite di produttività online che include email aziendale, Office e strumenti di collaborazione.', '2026-03-06 10:41:00'),
(146, 'microsoft 365', 'quali servizi include microsoft 365?', 'Microsoft 365 include Outlook, Word, Excel, PowerPoint, Teams, OneDrive e altri servizi cloud.', 'Tra i servizi Microsoft 365 trovi email professionale, archiviazione cloud e applicazioni Office.', 'La piattaforma include strumenti di produttività, collaborazione e posta elettronica.', '2026-03-06 10:41:00'),
(147, 'microsoft 365', 'cos è outlook in microsoft 365?', 'Outlook è il servizio di posta elettronica professionale incluso in Microsoft 365.', 'Outlook permette di gestire email, calendario e contatti.', 'È la piattaforma Microsoft per la gestione della posta aziendale.', '2026-03-06 10:41:00'),
(148, 'microsoft 365', 'come accedo alla webmail microsoft 365?', 'Puoi accedere alla webmail Microsoft 365 da https://outlook.office.com usando il tuo account.', 'La posta Microsoft 365 è disponibile via browser su outlook.office.com.', 'Accedi alla webmail inserendo email e password del tuo account Microsoft 365.', '2026-03-06 10:41:00'),
(149, 'microsoft 365', 'come accedo al pannello di amministrazione microsoft 365?', 'Il pannello admin è disponibile su https://admin.microsoft.com con l’account amministratore.', 'Puoi gestire utenti e servizi accedendo alla Microsoft 365 Admin Center.', 'La console amministrativa consente di controllare utenti, licenze e sicurezza.', '2026-03-06 10:41:00'),
(150, 'microsoft 365', 'come creo un nuovo utente microsoft 365?', 'Accedi al pannello admin e vai su Users → Add user.', 'Gli utenti si aggiungono dal portale amministratore Microsoft 365.', 'Puoi creare una nuova casella assegnando una licenza all’utente.', '2026-03-06 10:41:00'),
(151, 'microsoft 365', 'come elimino un utente microsoft 365?', 'Vai nella sezione Users del pannello admin e seleziona Delete user.', 'Gli utenti possono essere rimossi dalla console amministrativa.', 'La cancellazione dell’utente libera anche la licenza assegnata.', '2026-03-06 10:41:00'),
(152, 'microsoft 365', 'come resetto la password microsoft 365?', 'Puoi reimpostare la password dalla sezione Users del pannello admin.', 'Seleziona l’utente e scegli Reset Password.', 'Il reset password può essere fatto dall’amministratore.', '2026-03-06 10:41:00'),
(153, 'microsoft 365', 'posso usare microsoft 365 su più dispositivi?', 'Sì, Microsoft 365 può essere utilizzato su computer, smartphone e tablet.', 'Gli utenti possono accedere ai servizi Microsoft 365 da diversi dispositivi.', 'L’account Microsoft 365 consente accesso multipiattaforma.', '2026-03-06 10:41:00'),
(154, 'microsoft 365', 'cos è microsoft teams?', 'Microsoft Teams è una piattaforma di comunicazione e collaborazione.', 'Teams permette chat, videoconferenze e condivisione file.', 'È lo strumento Microsoft per lavoro di squadra e riunioni online.', '2026-03-06 10:41:00'),
(155, 'microsoft 365', 'cos è onedrive?', 'OneDrive è il servizio di archiviazione cloud incluso in Microsoft 365.', 'Permette di salvare e condividere file online.', 'È lo spazio cloud personale per documenti e dati.', '2026-03-06 10:41:00'),
(156, 'microsoft 365', 'quanta memoria offre onedrive?', 'Lo spazio OneDrive dipende dal piano Microsoft 365 attivo.', 'Molti piani includono almeno 1 TB di spazio cloud.', 'Lo storage varia in base alla licenza assegnata.', '2026-03-06 10:41:00'),
(157, 'microsoft 365', 'posso usare word online?', 'Sì, Word è disponibile anche nella versione web.', 'Le applicazioni Office possono essere usate direttamente dal browser.', 'Word online consente di modificare documenti senza installazioni.', '2026-03-06 10:41:00'),
(158, 'microsoft 365', 'posso usare excel online?', 'Sì, Excel è disponibile nella versione web di Microsoft 365.', 'Puoi modificare fogli di calcolo direttamente dal browser.', 'Excel online permette collaborazione in tempo reale.', '2026-03-06 10:41:00'),
(159, 'microsoft 365', 'cos è sharepoint?', 'SharePoint è una piattaforma per la gestione e condivisione documenti aziendali.', 'Permette di creare siti aziendali e archivi documentali.', 'È uno strumento per la collaborazione e gestione contenuti.', '2026-03-06 10:41:00'),
(160, 'microsoft 365', 'cos è exchange online?', 'Exchange Online è il servizio di posta elettronica cloud di Microsoft.', 'Gestisce email, calendari e contatti.', 'È il sistema di posta professionale di Microsoft 365.', '2026-03-06 10:41:00'),
(161, 'microsoft 365', 'posso usare microsoft 365 con outlook desktop?', 'Sì, Outlook desktop può essere configurato con account Microsoft 365.', 'Puoi sincronizzare email tramite protocollo Exchange.', 'Outlook desktop è pienamente compatibile con Microsoft 365.', '2026-03-06 10:41:00'),
(162, 'microsoft 365', 'come configuro outlook con microsoft 365?', 'Inserisci email e password e Outlook configurerà automaticamente l’account.', 'Outlook usa configurazione automatica con Exchange.', 'Basta aggiungere l’account Microsoft 365 nel client Outlook.', '2026-03-06 10:41:00'),
(163, 'microsoft 365', 'microsoft 365 funziona su mac?', 'Sì, Microsoft 365 è compatibile con macOS.', 'Le applicazioni Office sono disponibili anche per Mac.', 'Gli utenti Mac possono usare Word, Excel e Outlook.', '2026-03-06 10:41:00'),
(164, 'microsoft 365', 'microsoft 365 funziona su smartphone?', 'Sì, esistono app ufficiali Microsoft 365 per Android e iOS.', 'Puoi accedere a email e documenti dal telefono.', 'Microsoft offre app mobili per tutti i servizi principali.', '2026-03-06 10:41:00'),
(165, 'microsoft 365', 'cos è la licenza microsoft 365?', 'La licenza permette di usare i servizi e le applicazioni Microsoft 365.', 'Ogni utente deve avere una licenza assegnata.', 'La licenza determina i servizi disponibili.', '2026-03-06 10:41:00'),
(166, 'microsoft 365', 'come assegno una licenza microsoft 365?', 'Dal pannello admin seleziona l’utente e assegna la licenza.', 'La gestione delle licenze avviene nella console amministrativa.', 'Puoi modificare o assegnare licenze agli utenti.', '2026-03-06 10:41:00'),
(167, 'microsoft 365', 'posso cambiare piano microsoft 365?', 'Sì, i piani Microsoft 365 possono essere aggiornati o modificati.', 'Il cambio piano si gestisce dalla sezione billing.', 'È possibile fare upgrade della licenza.', '2026-03-06 10:41:00'),
(168, 'microsoft 365', 'microsoft 365 ha backup?', 'Microsoft 365 mantiene copie ridondanti dei dati.', 'Tuttavia molte aziende usano anche backup esterni.', 'Il servizio include protezioni ma non è un backup completo.', '2026-03-06 10:41:00'),
(169, 'microsoft 365', 'come recupero email cancellate?', 'Le email cancellate possono essere recuperate dal cestino.', 'Exchange mantiene gli elementi eliminati per un periodo limitato.', 'Il recupero è possibile tramite Outlook o admin.', '2026-03-06 10:41:00'),
(170, 'microsoft 365', 'cos è la autenticazione a due fattori?', 'È un sistema di sicurezza che richiede un secondo codice di accesso.', 'La 2FA aumenta la sicurezza degli account.', 'Richiede password più un codice temporaneo.', '2026-03-06 10:41:00'),
(171, 'microsoft 365', 'come attivo la verifica in due passaggi?', 'Puoi attivarla dalla sezione sicurezza dell’account.', 'La configurazione si trova nel pannello utente Microsoft.', 'L’admin può forzare l’attivazione della 2FA.', '2026-03-06 10:41:00'),
(172, 'microsoft 365', 'microsoft 365 supporta domini personalizzati?', 'Sì, puoi usare il tuo dominio per le email aziendali.', 'Il dominio si configura nella admin console.', 'Le email possono essere del tipo nome@tuodominio.', '2026-03-06 10:41:00'),
(173, 'microsoft 365', 'come aggiungo un dominio a microsoft 365?', 'Vai nella sezione Domains del pannello admin.', 'Microsoft fornirà i record DNS da configurare.', 'Dopo la verifica il dominio sarà attivo.', '2026-03-06 10:41:00'),
(174, 'microsoft 365', 'quali record dns servono per microsoft 365?', 'Sono necessari record MX, TXT, CNAME e SRV.', 'Microsoft fornisce automaticamente i record da configurare.', 'I DNS servono per email e servizi cloud.', '2026-03-06 10:41:00'),
(175, 'microsoft 365', 'cos è microsoft 365 business?', 'È una versione di Microsoft 365 pensata per aziende.', 'Include email aziendale e applicazioni Office.', 'È progettato per piccole e medie imprese.', '2026-03-06 10:41:00'),
(176, 'microsoft 365', 'microsoft 365 è sicuro?', 'Sì, Microsoft 365 include sistemi di sicurezza avanzati.', 'La piattaforma utilizza crittografia e protezione dati.', 'Microsoft implementa controlli di sicurezza enterprise.', '2026-03-06 10:41:00'),
(177, 'microsoft 365', 'come condivido file con microsoft 365?', 'Puoi condividere file tramite OneDrive o SharePoint.', 'La condivisione avviene tramite link.', 'I file possono essere condivisi con permessi.', '2026-03-06 10:41:00'),
(178, 'microsoft 365', 'posso collaborare sui documenti?', 'Sì, più utenti possono modificare lo stesso documento.', 'Office online supporta collaborazione in tempo reale.', 'Word ed Excel permettono editing condiviso.', '2026-03-06 10:41:00'),
(179, 'microsoft 365', 'posso fare videoconferenze?', 'Sì, tramite Microsoft Teams.', 'Teams permette riunioni online e webinar.', 'È possibile fare chiamate e meeting.', '2026-03-06 10:41:00'),
(180, 'microsoft 365', 'teams permette chat aziendale?', 'Sì, Teams include chat private e di gruppo.', 'Gli utenti possono comunicare in tempo reale.', 'È una piattaforma di collaborazione.', '2026-03-06 10:41:00'),
(181, 'microsoft 365', 'microsoft 365 funziona offline?', 'Sì, le applicazioni desktop funzionano offline.', 'I file vengono sincronizzati quando torni online.', 'Le app Office desktop non richiedono connessione continua.', '2026-03-06 10:41:00'),
(182, 'microsoft 365', 'posso installare office sul computer?', 'Sì, con alcune licenze puoi installare Office.', 'Word, Excel e PowerPoint possono essere installati localmente.', 'L’installazione dipende dal piano.', '2026-03-06 10:41:00'),
(183, 'microsoft 365', 'quali app include office?', 'Le principali app sono Word, Excel, PowerPoint e Outlook.', 'Alcuni piani includono anche Access e Publisher.', 'Le applicazioni variano in base alla licenza.', '2026-03-06 10:41:00'),
(184, 'microsoft 365', 'come aggiorno office?', 'Office si aggiorna automaticamente tramite Microsoft.', 'Gli aggiornamenti vengono installati via internet.', 'La suite Office riceve aggiornamenti regolari.', '2026-03-06 10:41:00'),
(185, 'microsoft 365', 'cos è microsoft defender?', 'Microsoft Defender è un sistema di sicurezza.', 'Protegge account e dati da minacce.', 'Fa parte delle soluzioni di sicurezza Microsoft.', '2026-03-06 10:41:00'),
(186, 'microsoft 365', 'posso recuperare file cancellati su onedrive?', 'Sì, i file eliminati vanno nel cestino.', 'Puoi recuperarli entro il periodo di conservazione.', 'Il cestino OneDrive mantiene i file per diversi giorni.', '2026-03-06 10:41:00'),
(187, 'microsoft 365', 'cos è la sincronizzazione onedrive?', 'Permette di sincronizzare file tra computer e cloud.', 'I file salvati nel cloud sono disponibili su più dispositivi.', 'La sincronizzazione avviene tramite app OneDrive.', '2026-03-06 10:41:00'),
(188, 'microsoft 365', 'microsoft 365 funziona senza server locale?', 'Sì, è un servizio completamente cloud.', 'Non serve installare server aziendali.', 'Tutti i servizi funzionano online.', '2026-03-06 10:41:00'),
(189, 'microsoft 365', 'posso migrare email su microsoft 365?', 'Sì, è possibile migrare caselle da altri provider.', 'Microsoft supporta migrazione email.', 'Le email possono essere trasferite da altri server.', '2026-03-06 10:41:00'),
(190, 'microsoft 365', 'quanto costa microsoft 365?', 'Il prezzo dipende dal piano scelto.', 'Esistono diversi abbonamenti mensili.', 'Il costo varia in base ai servizi inclusi.', '2026-03-06 10:41:00'),
(191, 'microsoft 365', 'perché usare microsoft 365?', 'Offre strumenti di produttività cloud integrati.', 'Permette collaborazione e lavoro remoto.', 'È una piattaforma completa per aziende.', '2026-03-06 10:41:00'),
(192, 'microsoft 365', 'microsoft 365 è adatto alle aziende?', 'Sì, è progettato per ambienti aziendali.', 'Include strumenti per sicurezza e gestione utenti.', 'È una soluzione professionale cloud.', '2026-03-06 10:41:00'),
(193, 'microsoft 365', 'serve installare software per usare microsoft 365?', 'No, puoi usare i servizi anche dal browser.', 'Le app web funzionano senza installazione.', 'Le applicazioni desktop sono opzionali.', '2026-03-06 10:41:00'),
(243, 'whmcs', 'cosa sono i moduli whmcs?', 'I moduli WHMCS sono estensioni che permettono di integrare servizi e funzionalità aggiuntive nel sistema di gestione hosting WHMCS.', 'I moduli per WHMCS servono per collegare il sistema di fatturazione e gestione clienti con servizi esterni come hosting, domini o gateway di pagamento.', 'Con i moduli WHMCS puoi automatizzare operazioni come la creazione di account hosting, la gestione dei domini o i pagamenti.', '2026-03-06 10:59:28'),
(244, 'whmcs', 'a cosa servono i moduli whmcs?', 'I moduli WHMCS permettono di automatizzare la gestione di servizi hosting, domini e fatturazione direttamente dal pannello WHMCS.', 'Grazie ai moduli WHMCS puoi collegare il sistema di billing con server, registrar di domini e altri servizi.', 'I moduli rendono WHMCS più potente permettendo integrazioni con piattaforme esterne e automazioni.', '2026-03-06 10:59:28'),
(245, 'whmcs', 'come installo un modulo whmcs?', 'Per installare un modulo WHMCS devi caricare i file nella cartella modules del tuo server e poi attivarlo dal pannello amministratore.', 'I moduli WHMCS si installano caricando i file nel sistema e attivandoli dalla sezione Addon Modules o Server Modules.', 'Dopo aver caricato i file del modulo nel server, puoi abilitarlo dal pannello amministratore di WHMCS.', '2026-03-06 10:59:28'),
(246, 'whmcs', 'i moduli whmcs sono compatibili con tutte le versioni?', 'La compatibilità dipende dal modulo: è sempre consigliato verificare quale versione di WHMCS è supportata.', 'Non tutti i moduli funzionano con ogni versione di WHMCS, quindi è importante controllare i requisiti prima dell’installazione.', 'Prima di installare un modulo WHMCS verifica sempre la compatibilità con la versione del tuo sistema.', '2026-03-06 10:59:28'),
(247, 'whmcs', 'posso automatizzare la gestione hosting con whmcs?', 'Sì, WHMCS permette di automatizzare molte operazioni come creazione account hosting, sospensione servizi e fatturazione.', 'Con WHMCS puoi automatizzare la gestione dei clienti, dei servizi hosting e dei pagamenti.', 'L’integrazione tra WHMCS e i moduli server consente di gestire automaticamente provisioning e gestione servizi.', '2026-03-06 10:59:28'),
(248, 'whmcs', 'whmcs può essere integrato con altri servizi?', 'Sì, WHMCS può essere integrato con molti servizi esterni tramite moduli e API.', 'Grazie ai moduli WHMCS puoi collegare il sistema con gateway di pagamento, registrar di domini e piattaforme cloud.', 'WHMCS supporta numerose integrazioni tramite moduli che permettono di estendere le funzionalità del sistema.', '2026-03-06 10:59:28');
INSERT INTO `faq` (`id`, `categoria`, `domanda`, `risposta1`, `risposta2`, `risposta3`, `data_aggiornamento`) VALUES
(249, 'domini dns', 'cos è un nome di dominio?', 'Un nome di dominio è l’indirizzo web che permette di raggiungere un sito internet, ad esempio esempio.com.', 'Il dominio è il nome utilizzato per identificare un sito web su Internet.', 'Un nome di dominio è l’indirizzo che gli utenti digitano nel browser per visitare un sito.', '2026-03-06 11:14:34'),
(250, 'domini dns', 'cos è il dns?', 'Il DNS è il sistema che traduce i nomi di dominio negli indirizzi IP dei server.', 'Il DNS collega un dominio all’indirizzo IP del server che ospita il sito.', 'Il Domain Name System permette ai browser di trovare il server corretto quando si inserisce un dominio.', '2026-03-06 11:14:34'),
(251, 'domini dns', 'a cosa servono i dns?', 'I DNS servono a collegare il nome di dominio al server che ospita il sito o la posta.', 'I record DNS permettono di gestire come un dominio indirizza traffico web o email.', 'Attraverso i DNS si configurano sito web, email e altri servizi collegati al dominio.', '2026-03-06 11:14:34'),
(252, 'domini dns', 'cos è un record a?', 'Il record A collega un dominio a un indirizzo IP.', 'Un record A serve per far puntare un dominio all’IP del server.', 'Il record A è usato per collegare un nome di dominio a un server specifico.', '2026-03-06 11:14:34'),
(253, 'domini dns', 'cos è un record cname?', 'Il record CNAME collega un dominio o sottodominio a un altro dominio.', 'Un CNAME crea un alias che punta a un altro nome di dominio.', 'Il record CNAME permette di indirizzare un dominio verso un altro hostname.', '2026-03-06 11:14:34'),
(254, 'domini dns', 'cos è un record mx?', 'I record MX indicano quali server gestiscono la posta elettronica del dominio.', 'Il record MX definisce il server che riceve le email per un dominio.', 'Gli MX servono per configurare la ricezione delle email.', '2026-03-06 11:14:34'),
(255, 'domini dns', 'cos è un record txt?', 'Il record TXT serve per inserire informazioni testuali nel DNS.', 'I record TXT vengono usati spesso per verifiche di dominio o configurazioni email.', 'Molti servizi utilizzano record TXT per autenticazioni e verifiche.', '2026-03-06 11:14:34'),
(256, 'domini dns', 'cos è il record spf?', 'SPF è un record DNS che indica quali server possono inviare email per il dominio.', 'Il record SPF aiuta a prevenire lo spam e lo spoofing delle email.', 'Con SPF si autorizzano i server che possono inviare posta per il dominio.', '2026-03-06 11:14:34'),
(257, 'domini dns', 'cos è il record dkim?', 'DKIM è un sistema che firma digitalmente le email per verificarne l’autenticità.', 'Il record DKIM viene pubblicato nel DNS per autenticare le email inviate dal dominio.', 'DKIM aiuta a prevenire falsificazioni nelle email.', '2026-03-06 11:14:34'),
(258, 'domini dns', 'cos è il record dmarc?', 'DMARC è un sistema di sicurezza email che usa SPF e DKIM per proteggere il dominio.', 'Il record DMARC definisce come gestire le email non autentiche.', 'DMARC aiuta a prevenire phishing e spoofing delle email.', '2026-03-06 11:14:34'),
(259, 'domini dns', 'quanto tempo impiegano i dns ad aggiornarsi?', 'La propagazione DNS può richiedere da pochi minuti fino a 24-48 ore.', 'I cambi DNS possono richiedere tempo per propagarsi su tutti i server Internet.', 'Normalmente le modifiche DNS diventano attive entro alcune ore.', '2026-03-06 11:14:34'),
(260, 'domini dns', 'cos è la propagazione dns?', 'La propagazione DNS è il tempo necessario affinché le modifiche DNS si diffondano su Internet.', 'Quando si modifica un record DNS, i cambiamenti devono propagarsi nei server DNS globali.', 'La propagazione DNS può richiedere diverse ore prima di essere visibile ovunque.', '2026-03-06 11:14:34'),
(261, 'domini dns', 'cos è un nameserver?', 'I nameserver sono i server che gestiscono i DNS di un dominio.', 'Un nameserver contiene le informazioni DNS che indicano dove si trova il sito o la posta.', 'I nameserver sono responsabili della risoluzione DNS del dominio.', '2026-03-06 11:14:34'),
(262, 'domini dns', 'come cambio i nameserver di un dominio?', 'I nameserver si modificano dal pannello di gestione del dominio presso il registrar.', 'Per cambiare nameserver accedi al pannello dominio e inserisci i nuovi server DNS.', 'La modifica dei nameserver si fa dall’area clienti del provider.', '2026-03-06 11:14:34'),
(263, 'domini dns', 'cos è un sottodominio?', 'Un sottodominio è una parte aggiuntiva del dominio principale, come blog.esempio.com.', 'I sottodomini permettono di organizzare servizi diversi sotto lo stesso dominio.', 'Un sottodominio è un dominio secondario collegato al dominio principale.', '2026-03-06 11:14:34'),
(264, 'domini dns', 'come creo un sottodominio?', 'Puoi creare un sottodominio dal pannello DNS o dal pannello hosting.', 'I sottodomini si configurano aggiungendo un record DNS o dal pannello hosting.', 'Dal pannello di gestione del dominio puoi aggiungere nuovi sottodomini.', '2026-03-06 11:14:34'),
(265, 'domini dns', 'cos è il ttl dns?', 'Il TTL indica quanto tempo i record DNS vengono memorizzati nella cache.', 'Il Time To Live stabilisce per quanto tempo i server DNS mantengono una risposta.', 'Un TTL più basso permette aggiornamenti DNS più rapidi.', '2026-03-06 11:14:34'),
(266, 'domini dns', 'perché il mio dominio non punta al server?', 'Potrebbe essere necessario controllare i record DNS o attendere la propagazione.', 'Se il dominio non funziona verifica record A, nameserver e propagazione DNS.', 'Problemi DNS possono dipendere da configurazioni errate o propagazione non completata.', '2026-03-06 11:14:34'),
(267, 'domini dns', 'come verifico i dns di un dominio?', 'Puoi controllare i record DNS tramite strumenti online di DNS lookup.', 'Esistono vari tool DNS che permettono di verificare la configurazione del dominio.', 'Con strumenti di controllo DNS puoi vedere i record attivi per il dominio.', '2026-03-06 11:14:34'),
(268, 'domini dns', 'posso modificare i dns del mio dominio?', 'Sì, i record DNS possono essere modificati dal pannello di gestione del dominio.', 'Dal pannello DNS puoi aggiungere o modificare record come A, MX o TXT.', 'La gestione DNS permette di configurare servizi collegati al dominio.', '2026-03-06 11:14:34'),
(269, 'domini dns', 'cos è un redirect di dominio?', 'Un redirect reindirizza i visitatori da un dominio a un altro sito.', 'Il redirect di dominio serve per inoltrare il traffico verso un altro indirizzo web.', 'Attraverso un redirect puoi far aprire automaticamente un altro sito.', '2026-03-06 11:14:34'),
(270, 'domini dns', 'posso usare dns diversi dal provider?', 'Sì, puoi utilizzare nameserver esterni come quelli di altri servizi DNS.', 'Molti domini permettono di configurare DNS esterni.', 'Puoi scegliere qualsiasi provider DNS compatibile.', '2026-03-06 11:14:34'),
(271, 'domini dns', 'cos è il reverse dns?', 'Il reverse DNS associa un indirizzo IP a un nome di dominio.', 'Il reverse DNS è usato spesso per server email.', 'Questa configurazione permette di verificare il dominio collegato a un IP.', '2026-03-06 11:14:34'),
(272, 'domini dns', 'come collego un dominio al mio hosting?', 'Devi configurare i record DNS o i nameserver forniti dall’hosting.', 'Per collegare il dominio all’hosting imposta i DNS indicati dal provider.', 'Il collegamento avviene modificando i nameserver o i record A.', '2026-03-06 11:14:34'),
(273, 'domini dns', 'posso avere più record dns per lo stesso dominio?', 'Sì, alcuni record DNS possono essere multipli per lo stesso dominio.', 'È possibile configurare più record MX o TXT per un dominio.', 'La presenza di più record dipende dal tipo di configurazione DNS.', '2026-03-06 11:14:34'),
(274, 'domini dns', 'cos è un record ns?', 'Il record NS indica quali nameserver gestiscono il dominio.', 'I record NS definiscono i server DNS autoritativi per il dominio.', 'Il record NS è usato per delegare la gestione DNS.', '2026-03-06 11:14:34'),
(275, 'domini dns', 'cos è il record srv?', 'Il record SRV definisce il server che gestisce un servizio specifico.', 'Questo record DNS è usato per servizi come VoIP o Microsoft.', 'Il record SRV indica host e porta di un servizio.', '2026-03-06 11:14:34'),
(276, 'domini dns', 'come funziona la risoluzione dns?', 'Quando digiti un dominio, il DNS trova l’indirizzo IP del server corrispondente.', 'La risoluzione DNS traduce un nome di dominio in un indirizzo IP.', 'Il sistema DNS permette ai browser di trovare il server del sito.', '2026-03-06 11:14:34'),
(277, 'domini dns', 'posso gestire dns per email e sito separatamente?', 'Sì, i record DNS permettono di configurare separatamente sito web ed email.', 'Puoi usare record diversi per indirizzare sito e posta su server differenti.', 'La configurazione DNS consente di gestire servizi separati per lo stesso dominio.', '2026-03-06 11:14:34'),
(278, 'pec', 'cos è la pec?', 'La PEC (Posta Elettronica Certificata) è un sistema di email che garantisce valore legale alle comunicazioni, equivalente a una raccomandata con ricevuta di ritorno.', 'La PEC è una email certificata che attesta l’invio e la consegna di un messaggio con valore legale.', 'La posta elettronica certificata permette di inviare comunicazioni ufficiali con prova di invio e consegna.', '2026-03-06 11:34:34'),
(279, 'pec', 'a cosa serve la pec?', 'La PEC serve per inviare comunicazioni ufficiali con valore legale a pubbliche amministrazioni, aziende e professionisti.', 'La posta certificata viene usata per inviare documenti, contratti o comunicazioni formali.', 'Con la PEC è possibile comunicare in modo ufficiale senza usare la raccomandata cartacea.', '2026-03-06 11:34:34'),
(280, 'pec', 'la pec ha valore legale?', 'Sì, i messaggi PEC hanno valore legale equivalente a una raccomandata con ricevuta di ritorno.', 'La PEC certifica l’invio e la consegna del messaggio e può essere usata come prova legale.', 'Le ricevute generate dalla PEC costituiscono prova della trasmissione e della consegna del messaggio.', '2026-03-06 11:34:34'),
(281, 'pec', 'come funziona la pec?', 'La PEC funziona come una normale email ma il sistema genera ricevute che certificano invio e consegna del messaggio.', 'Quando invii una PEC, il gestore invia una ricevuta che conferma l’avvenuto invio e la consegna.', 'Il sistema PEC garantisce tracciabilità e integrità dei messaggi grazie ai protocolli di sicurezza.', '2026-03-06 11:34:34'),
(282, 'pec', 'posso inviare una pec a una email normale?', 'Sì, una PEC può essere inviata anche a un indirizzo email normale, ma la certificazione della consegna potrebbe non essere garantita.', 'È possibile inviare PEC a caselle email tradizionali, ma il valore legale è garantito solo tra caselle PEC.', 'Se il destinatario non ha una PEC, il messaggio viene comunque inviato ma perde parte della certificazione.', '2026-03-06 11:34:34'),
(283, 'pec', 'la pec è obbligatoria?', 'In Italia la PEC è obbligatoria per molte aziende e professionisti per comunicare con la pubblica amministrazione.', 'Le imprese devono avere una PEC registrata come domicilio digitale.', 'Molte comunicazioni ufficiali con la pubblica amministrazione devono avvenire tramite PEC.', '2026-03-06 11:34:34'),
(284, 'pec', 'posso usare la pec come una email normale?', 'Sì, la PEC funziona come una normale casella email ma con funzionalità di certificazione.', 'Puoi inviare messaggi, allegati e documenti proprio come con una email tradizionale.', 'La differenza è che la PEC genera ricevute con valore legale.', '2026-03-06 11:34:34'),
(285, 'pec', 'come accedo alla mia casella pec?', 'Puoi accedere alla PEC tramite webmail oppure configurandola in un client di posta.', 'La casella PEC è accessibile da browser o da programmi di posta come Outlook.', 'Basta inserire username e password nel pannello webmail o nel client email.', '2026-03-06 11:34:34'),
(286, 'pec', 'quanto spazio ha una casella pec?', 'Lo spazio disponibile dipende dal piano PEC scelto presso il provider.', 'Le caselle PEC hanno una quota di spazio per conservare email e allegati.', 'La dimensione della casella PEC varia in base al servizio acquistato.', '2026-03-06 11:34:34'),
(287, 'pec', 'perché usare la pec invece della posta normale?', 'La PEC garantisce prova legale di invio e consegna dei messaggi.', 'Usare la PEC permette di inviare documenti ufficiali in modo rapido e sicuro.', 'Rispetto alla posta tradizionale, la PEC è più veloce e ha valore legale digitale.', '2026-03-06 11:34:34'),
(288, 'Windows Web Hosting', 'Come cambiare la  password FTP?', 'Per aggiornare la password dell’account hosting associato al vostro dominio, accedete al pannello di gestione e dalla Home Page cliccate sul nome del dominio per cui desiderate modificare la password. Nel gruppo Hosting selezionate l’opzione Configurazione, inserite la nuova password nel campo dedicato e cliccate su OK per confermare le modifiche. La nuova password sarà attiva immediatamente; ricordate di aggiornarla anche nei vostri client FTP o nei gestionali che si connettono al servizio.', 'Accedete al pannello di gestione e selezionate il dominio per cui volete cambiare la password. All’interno del gruppo Hosting aprite la sezione Configurazione, digitate la nuova password e confermate cliccando su OK. La modifica avrà effetto immediato, quindi assicuratevi di aggiornare la password anche nei client FTP e nei software gestionali che utilizzano l’account hosting.', 'Per modificare la password dell’account hosting legato al vostro dominio, accedete al pannello di gestione e cliccate sul dominio interessato nella Home Page. All’interno del gruppo Hosting scegliete Configurazione, inserite la nuova password nel campo dedicato e confermate premendo OK. La modifica viene applicata immediatamente, quindi ricordate di aggiornare anche tutti i client FTP e i gestionali collegati.', '2026-03-06 11:51:32' ),
(289, 'Windows Web Hosting', 'Come creare account FTP addizionali?','Per creare un account FTP aggiuntivo tramite Plesk, accedete alla Home del pannello e cliccate sul nome del dominio che desiderate gestire. Selezionate la voce Account FTP e nella scheda degli account addizionali cliccate su Aggiungi. Inserite il nome dell’account FTP, specificate se necessario la directory a cui sarà associato, digitate una password sicura e assegnate una quota di spazio web per limitarne l’utilizzo. Definite i permessi di accesso scegliendo tra Lettura, per consentire solo il download, o Scrittura, per abilitare download, upload e modifica, quindi cliccate su OK per completare la creazione dell’account.', 'Per aggiungere un nuovo account FTP in Plesk, dalla Home del pannello selezionate il dominio desiderato e aprite Account FTP. Nella sezione dedicata agli account addizionali cliccate su Aggiungi, inserite il nome dell’account, eventualmente la directory associata, impostate una password sicura e definite la quota di spazio web. Impostate i permessi di accesso scegliendo Lettura o Scrittura secondo le necessità e confermate il tutto cliccando su OK per completare la procedura.', 'Creare un account FTP aggiuntivo su Plesk richiede di accedere alla Home del pannello e cliccare sul dominio di interesse. Aprite Account FTP, nella scheda degli account addizionali cliccate su Aggiungi, inserite il nome dell’account, eventualmente la directory assegnata, impostate una password sicura e una quota di spazio web. Scegliete i permessi di accesso tra Lettura, per il solo download, o Scrittura, per download, upload e modifica, e infine confermate premendo OK per completare la creazione.', '2026-03-06 11:53:14' ),
(290, 'Windows Web Hosting', 'Come entrare nel pannello Plesk', 'Per accedere al pannello di gestione Plesk del vostro dominio, utilizzate il link https://NOME_DOMINIO:8443/, sostituendo NOME_DOMINIO con il nome reale del vostro dominio, ad esempio miodominio.it. Le credenziali di accesso, composte da nome utente e password, sono state inviate all’indirizzo email indicato durante l’attivazione del servizio. Se non le avete ancora ricevute, verificate la vostra casella di posta, inclusa la cartella dello spam.', 'Per entrare nel pannello Plesk associato al vostro dominio, visitate https://NOME_DOMINIO:8443/ sostituendo NOME_DOMINIO con il nome del vostro dominio effettivo, come miodominio.it. Le credenziali necessarie per l’accesso sono state inviate via email all’indirizzo fornito al momento dell’attivazione; se non le trovate, controllate anche la cartella dello spam.', 'Accedete al pannello di gestione Plesk del vostro dominio tramite l’URL https://NOME_DOMINIO:8443/, sostituendo NOME_DOMINIO con il dominio corretto, ad esempio miodominio.it. Il nome utente e la password per l’accesso sono stati inviati all’indirizzo email indicato al momento dell’attivazione del servizio; in caso non le abbiate ricevute, verificate anche la cartella spam della vostra posta.', '2026-03-06 11:54:27'),
(291, 'Windows Web Hosting', 'FAQ complete dal sito PARALLELS', 'Parallels, oggi parte di WebPros, ha realizzato una guida completa e strutturata per supportare gli utenti nell’utilizzo del pannello di controllo Plesk per Windows. La guida, pensata per i clienti finali, contiene spiegazioni dettagliate, immagini e istruzioni pratiche su tutte le funzionalità principali del pannello ed è utile sia per chi utilizza Plesk per la prima volta sia per chi desidera approfondire alcune funzionalità specifiche.', 'WebPros, che ha acquisito Parallels, ha creato una guida esaustiva per aiutare gli utenti a comprendere e sfruttare al meglio il pannello Plesk per Windows. Destinata ai clienti finali, la guida offre spiegazioni chiare, immagini illustrative e istruzioni pratiche sulle principali funzionalità del pannello, risultando preziosa sia per i nuovi utenti sia per chi vuole approfondire aspetti specifici.', 'Parallels, oggi parte di WebPros, mette a disposizione una guida completa e ben organizzata per il pannello di controllo Plesk per Windows. La guida è rivolta ai clienti finali e include spiegazioni dettagliate, esempi pratici e immagini, rendendola uno strumento utile sia per chi si avvicina per la prima volta a Plesk sia per chi desidera approfondire particolari funzionalità del pannello.', '2026-03-06 11:56:42'),
(292, 'Windows Web Hosting', 'Come pubblicare il sito tramite FTP?', 'Per caricare i contenuti del sito web sul server, connettetevi tramite un client FTP, come FileZilla o WinSCP, utilizzando le credenziali dell’account FTP specificate durante la configurazione dell’hosting oppure fornite dal provider. Una volta stabilita la connessione, trasferite i file nelle cartelle appropriate: httpdocs per i contenuti accessibili via protocollo HTTP e httpsdocs per quelli accessibili in modo sicuro tramite HTTPS/SSL. Assicuratevi che la struttura del sito sia organizzata correttamente all’interno delle directory per garantire la pubblicazione online funzionante.', 'Per pubblicare il sito web, collegatevi al server tramite un client FTP come FileZilla o WinSCP usando le credenziali dell’account FTP fornite durante la configurazione dell’hosting o direttamente dal provider. Caricate quindi i file nella cartella httpdocs se devono essere accessibili tramite HTTP, oppure in httpsdocs se devono essere serviti in modalità sicura HTTPS/SSL, facendo attenzione a mantenere la struttura del sito ordinata per assicurare il corretto funzionamento online.', 'Collegatevi al server tramite un client FTP (ad esempio FileZilla o WinSCP) usando le credenziali fornite durante la configurazione dell’account hosting o dal provider. A questo punto caricate i file del sito nelle cartelle httpdocs per accesso tramite HTTP e httpsdocs per accesso sicuro HTTPS/SSL, assicurandovi che la struttura delle directory sia corretta in modo da garantire la pubblicazione e il funzionamento ottimale del sito online.', '2026-03-06 11:57:58'),
(293, 'Windows Web Hosting', 'Come pubblicare siti locali con FrontPage?', 'Microsoft FrontPage consente di gestire due tipologie di siti web: quelli basati sul disco, creati sul proprio computer e pubblicati successivamente su un server, e quelli basati direttamente sul server, senza necessità di pubblicazione. Questa guida si concentra esclusivamente sulla pubblicazione dei siti locali. Un sito locale può essere pubblicato tramite FTP, se il server supporta il protocollo, oppure tramite HTTP, se il server utilizza le Estensioni Server FrontPage, con URL di esempio come http://your-domain.com/MyWebSite per HTTP e ftp://ftp.your-domain.com/myFolder per FTP. Dopo la pubblicazione, la gestione del sito può avvenire attraverso le Estensioni Server FrontPage. Per accedere all’interfaccia di gestione, aprite il pannello Plesk, selezionate il dominio desiderato e cliccate su Gestione di FrontPage nella sezione Hosting. In base alla configurazione, potrete utilizzare FrontPage WebAdmin per siti non protetti da SSL oppure FrontPage-SSL WebAdmin per siti protetti. Inserite le credenziali di amministratore FrontPage e cliccate su OK. Maggiori dettagli sull’uso delle Estensioni Server FrontPage sono disponibili direttamente dal pannello tramite FP Webadmin > Help o sul sito ufficiale di Microsoft.', 'Con Microsoft FrontPage è possibile lavorare sia con siti locali, creati sul proprio computer e pubblicati in un secondo momento, sia con siti direttamente basati sul server. Questa guida si riferisce ai siti locali, che possono essere pubblicati tramite FTP, se supportato dal server, o tramite HTTP se il server utilizza le Estensioni Server FrontPage, ad esempio http://your-domain.com/MyWebSite per HTTP e ftp://ftp.your-domain.com/myFolder per FTP. Dopo la pubblicazione, il sito può essere gestito tramite le Estensioni Server FrontPage. Per accedere all’interfaccia di gestione, entrate nel pannello Plesk, selezionate il dominio, cliccate su Gestione di FrontPage nella sezione Hosting e scegliete tra FrontPage WebAdmin per siti non SSL o FrontPage-SSL WebAdmin per siti protetti da SSL. Inserite le credenziali di amministratore FrontPage e confermate con OK. Ulteriori informazioni sono reperibili tramite il menu Help di FP Webadmin o sul sito Microsoft.', 'Microsoft FrontPage permette di creare siti web locali, da pubblicare successivamente su un server, e siti basati direttamente sul server senza pubblicazione. La presente guida riguarda esclusivamente i siti locali, che possono essere pubblicati tramite FTP se il server lo supporta, o tramite HTTP se sono attive le Estensioni Server FrontPage, con URL di esempio http://your-domain.com/MyWebSite per HTTP e ftp://ftp.your-domain.com/myFolder per FTP. Una volta pubblicato, il sito può essere gestito con le Estensioni Server FrontPage. Per accedere alla gestione, entrate nel pannello Plesk, selezionate il dominio, cliccate su Gestione di FrontPage nella sezione Hosting e scegliete FrontPage WebAdmin per siti non SSL o FrontPage-SSL WebAdmin per siti SSL. Inserite le credenziali di amministratore e premete OK. Per approfondimenti, consultate il menu Help di FP Webadmin o il sito ufficiale Microsoft.', '2026-03-06 12:00:18'),
(294, 'VPN - Utixo Cloud Gateway', 'Come configurare Utixo Hybrid Cloud su Android?', 'L’app ufficiale OpenVPN Connect è disponibile gratuitamente sul Google Play Store e permette di configurare e gestire connessioni VPN al tuo ambiente Utixo Hybrid Cloud. Il client supporta un solo tunnel VPN attivo alla volta, quindi non è possibile connettersi contemporaneamente a più server, anche se l’app può memorizzare più configurazioni e attivarne una alla volta. Per installarla, apri il Google Play Store sul tuo dispositivo Android, cerca “OpenVPN Connect” oppure utilizza il link diretto per il download e completa l’installazione; troverai l’icona dell’app sulla schermata principale. Per configurare la connessione, apri OpenVPN Connect e seleziona l’opzione Server di accesso per avviare l’importazione. Puoi scegliere tra due modalità: importazione dall’interfaccia web inserendo indirizzo del server, username e password (specificando eventualmente la porta diversa dalla 443 HTTPS) oppure importazione da file caricando il file di configurazione fornito dal tuo amministratore. Una volta completata l’importazione, la connessione VPN è pronta all’uso.', 'L’app OpenVPN Connect, disponibile gratuitamente sul Google Play Store, consente di gestire connessioni VPN verso l’ambiente Utixo Hybrid Cloud. Supporta un solo tunnel attivo alla volta, anche se è possibile salvare più configurazioni di server per attivarne una alla volta. Per installarla, apri il Google Play Store, cerca “OpenVPN Connect” o usa il link diretto per scaricarla, quindi completa l’installazione; l’icona comparirà sulla schermata principale del dispositivo. Per configurare la VPN, apri l’app e seleziona Server di accesso per importare la configurazione. È possibile scegliere tra importazione dall’interfaccia web, inserendo indirizzo del server, username e password (con eventuale porta diversa dalla 443 HTTPS), oppure importazione da file fornito dall’amministratore. Terminata l’importazione, la connessione è subito pronta per essere utilizzata.', 'OpenVPN Connect è l’app ufficiale disponibile sul Google Play Store e permette di configurare connessioni VPN verso Utixo Hybrid Cloud. Il client permette un solo tunnel VPN attivo alla volta, ma può memorizzare più configurazioni di server. Per installarla, apri il Google Play Store sul tuo dispositivo Android, cerca “OpenVPN Connect” o utilizza il link diretto per il download e completa l’installazione; l’icona dell’app apparirà sulla schermata principale. Per configurare la connessione, apri l’app, seleziona Server di accesso e scegli tra importazione dall’interfaccia web inserendo indirizzo del server, username e password (specificando eventuale porta diversa da 443 HTTPS) oppure importazione da file fornito dall’amministratore. Una volta completata l’importazione, la VPN è pronta all’uso.', '2026-03-06 12:15:39'),
(295, 'VPN - Utixo Cloud Gateway', 'Come Configurare il client OpenVPN Connect per il server Utixo Cloud Gateway', 'Per utilizzare OpenVPN Connect su Windows, scaricate e installate il client dal link https://openvpn.net/downloads/openvpn-connect-v3-windows.msi. Successivamente, scaricate il file di configurazione fornito da Utixo e trascinatelo nella sezione File del client OpenVPN Connect. Durante l’importazione del file, inserite il nome utente e la password associati alla configurazione, ricevuti da Utixo. Per avviare la connessione, cliccate su Connect. Una volta connessi al server OpenVPN, potrete accedere ai dispositivi presenti nella rete remota.', 'Scaricate e installate il client OpenVPN Connect per Windows utilizzando il link https://openvpn.net/downloads/openvpn-connect-v3-windows.msi. Procuratevi il file di configurazione fornito da Utixo e trascinatelo all’interno della sezione File del client. Durante l’importazione, inserite le credenziali fornite da Utixo, quindi cliccate su Connect per stabilire la connessione al server OpenVPN. Una volta connessi, avrete accesso ai dispositivi della rete remota.', 'Per connettersi alla rete remota tramite OpenVPN, iniziate scaricando e installando OpenVPN Connect su Windows dal link https://openvpn.net/downloads/openvpn-connect-v3-windows.msi. Scaricate il file di configurazione fornito da Utixo e trascinatelo nella sezione File del client. Inserite il nome utente e la password associati alla configurazione durante l’importazione e cliccate su Connect per stabilire la connessione al server OpenVPN. Una volta connessi, sarà possibile accedere ai dispositivi presenti nella rete remota.', '2026-03-06 12:17:41'),
(296, 'VPN - Utixo Cloud Gateway', 'Come installare il client VPN Utixo (OpenVPN) su Windows', 'Utixo permette di collegare i server virtuali cloud alla rete aziendale creando una rete privata e protetta. Per accedervi da un PC Windows, scaricate il file di installazione indicato nell’email di attivazione del servizio e avviatelo confermando ogni passaggio. Quando compare il messaggio di sicurezza, cliccate su “Ulteriori informazioni” e confermate l’esecuzione. All’avvio dell’installer, confermate con “Install” e seguite i passaggi fino alla schermata finale. Una volta completata l’installazione, eseguite il client VPN e utilizzate le credenziali fornite da Utixo per attivare la connessione. Se la VPN si apre correttamente, l’icona in basso a destra diventa verde e potrete operare come se foste direttamente in azienda.', 'Con Utixo è possibile collegare i server cloud alla rete aziendale creando una rete privata sicura. Per accedervi da un PC Windows, scaricate il file di installazione dall’email di attivazione e avviatelo, confermando ogni passaggio. Al messaggio di sicurezza selezionate “Ulteriori informazioni” e confermate l’esecuzione, quindi premete “Install” all’avvio dell’installer e completate l’installazione seguendo le schermate fino alla fine. Avviando il client VPN, inserite utente e password forniti da Utixo: quando la VPN è attiva, comparirà un’icona verde in basso a destra, consentendovi di lavorare come se foste in azienda.', 'Utixo consente di creare una rete privata unendo i server cloud alla rete aziendale. Per accedervi su Windows, scaricate il file di installazione indicato nell’email di attivazione e avviatelo confermando ogni passo. Al messaggio di sicurezza cliccate su “Ulteriori informazioni” e confermate l’esecuzione, quindi premete “Install” all’apertura dell’installer e seguite tutti i passaggi fino alla schermata finale. Una volta installato il client VPN, inserite le credenziali fornite da Utixo per attivare la connessione: se la VPN è correttamente aperta, l’icona diventa verde e potrete utilizzare la rete come se foste fisicamente in azienda.', '2026-03-06 12:20:13'),
(297, 'VPN - Utixo Cloud Gateway', 'Come accedere automaticamente alla VPN da Windows?', 'Molti utenti desiderano che la connessione OpenVPN si avvii automaticamente all’accensione del computer. Anche se l’app OpenVPN per Windows non offre un’opzione diretta, è possibile configurarla utilizzando una stringa di avvio che richiama il file di configurazione .ovpn. Su Windows a 32 bit la stringa sarà "C:\Programmi\OpenVPN\bin\openvpn-gui.exe" --connect xxxxx.ovpn, mentre su Windows a 64 bit sarà "C:\Programmi (x86)\OpenVPN\bin\openvpn-gui.exe" --connect xxxxx.ovpn, sostituendo xxxxx.ovpn con il nome del file di configurazione presente nella cartella OpenVPN/config. Per automatizzare l’avvio, aprite il Registro di Windows (regedit), navigate in HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Run e aggiungete una nuova stringa con un nome a scelta (ad esempio openvpn) inserendo la stringa di avvio. Se OpenVPN si trova in un percorso diverso da quello indicato o Windows non è installato sull’unità C:, aggiornate di conseguenza il percorso. Su Windows Vista, 7 e 8, OpenVPN-GUI deve essere eseguito come amministratore, impostabile nelle Proprietà → Compatibilità. All’avvio, OpenVPN richiederà nome utente e password; nelle versioni più recenti è possibile salvarle direttamente nell’app, mentre nelle versioni precedenti è necessario creare un file password.txt nella cartella OpenVPN/config con due righe contenenti rispettivamente username e password e modificare la riga auth-user-pass nel file .ovpn in auth-user-pass password.txt.', 'Per avviare automaticamente OpenVPN all’accensione di un PC Windows, è necessario utilizzare una stringa di avvio che punti al file di configurazione .ovpn: su sistemi a 32 bit "C:\Programmi\OpenVPN\bin\openvpn-gui.exe" --connect xxxxx.ovpn, su sistemi a 64 bit "C:\Programmi (x86)\OpenVPN\bin\openvpn-gui.exe" --connect xxxxx.ovpn, sostituendo xxxxx.ovpn con il nome corretto del file presente in OpenVPN/config. Per aggiungere l’avvio automatico, aprite il Registro di Windows (regedit), andate in HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Run e create una nuova stringa con la stringa di avvio. È importante aggiornare il percorso se Windows o OpenVPN si trovano altrove e assicurarsi che OpenVPN-GUI sia eseguito come amministratore su Windows Vista, 7 e 8. Per automatizzare anche l’inserimento delle credenziali, nelle versioni precedenti si può creare un file password.txt con username e password e modificare la riga auth-user-pass nel file .ovpn per richiamarlo, mentre le versioni più recenti consentono il salvataggio sicuro delle credenziali direttamente nell’app.', 'Se desiderate che OpenVPN si avvii automaticamente con Windows, create una stringa di avvio che richiami il file .ovpn: per sistemi a 32 bit "C:\Programmi\OpenVPN\bin\openvpn-gui.exe" --connect xxxxx.ovpn, per sistemi a 64 bit "C:\Programmi (x86)\OpenVPN\bin\openvpn-gui.exe" --connect xxxxx.ovpn, sostituendo xxxxx.ovpn con il file corretto. Per abilitare l’avvio automatico, aprite regedit, navigate in HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Run e aggiungete una stringa contenente la command line. Aggiornate il percorso se necessario e assicuratevi che OpenVPN-GUI sia eseguito come amministratore su Windows Vista, 7 e 8. Per il login automatico con utente e password, le versioni recenti permettono di salvare le credenziali nell’app, mentre nelle versioni precedenti si crea un file password.txt nella cartella OpenVPN/config con username e password e si modifica la riga auth-user-pass del file .ovpn in auth-user-pass password.txt.', '2026-03-06 12:21:47'),
(298, 'Virtual Private Server VPS', 'Come fare il backup delle VPS Utixo e GDPR', 'Dal 25 maggio 2018 è entrato in vigore il Regolamento Generale sulla Protezione dei Dati (GDPR), la normativa europea che tutela i dati personali e impone alle aziende nuovi obblighi, come il diritto all’oblio, la portabilità dei dati, la trasparenza nel trattamento e la notifica tempestiva in caso di violazioni. Un elemento fondamentale è garantire la protezione dei dati tramite sistemi di backup sicuri e conformi. Utixo propone una soluzione VPS avanzata che risponde a questi requisiti. Il sistema di backup VPS Utixo esegue backup completi della macchina virtuale a livello di hypervisor senza agent software, garantendo massima affidabilità, e protegge i dati con crittografia AES a 256 bit end-to-end, conforme agli articoli 32 e 44 del GDPR. I backup sono archiviati in uno storage dedicato nel datacenter principale certificato ISO/IEC 27001, con opzioni su richiesta per backup remoti e soluzioni di disaster recovery ad alte prestazioni. Il piano predefinito conserva i backup degli ultimi cinque giorni, eseguiti tra le 19:00 e le 08:00, con possibilità di pianificazione personalizzata e monitoraggio continuo. Su richiesta è possibile configurare fasce orarie specifiche, destinazioni in datacenter remoti e ulteriori misure di sicurezza. Una corretta configurazione dei sistemi di backup e cifratura è fondamentale per garantire la conformità al GDPR e ridurre il rischio di perdita o compromissione dei dati sensibili.', 'Il GDPR, entrato in vigore il 25 maggio 2018, stabilisce regole precise per la protezione dei dati personali dei cittadini europei, imponendo alle aziende obblighi come il diritto all’oblio, la portabilità dei dati, la trasparenza nel trattamento e la notifica rapida di eventuali violazioni. Per rispettare tali requisiti, è essenziale utilizzare sistemi di backup sicuri. Utixo offre una soluzione VPS avanzata che consente backup completi della macchina virtuale a livello di hypervisor senza agent software, assicurando massima affidabilità. I dati sono protetti con crittografia AES a 256 bit end-to-end e archiviati in uno storage dedicato presso un datacenter certificato ISO/IEC 27001, con possibilità di backup remoti e disaster recovery ad alte prestazioni. Il sistema prevede una pianificazione flessibile, con backup eseguiti tra le 19:00 e le 08:00 e conservazione degli ultimi cinque giorni, monitorando tutte le operazioni in tempo reale. Configurazioni personalizzate su richiesta permettono di definire fasce orarie specifiche, destinazioni remote e ulteriori misure di sicurezza. Una corretta implementazione del backup e della cifratura è essenziale per garantire conformità al GDPR e protezione dei dati sensibili.', 'Il Regolamento Generale sulla Protezione dei Dati (GDPR), in vigore dal 25 maggio 2018, tutela i dati personali dei cittadini europei e impone alle aziende obblighi come il diritto all’oblio, la portabilità dei dati, la trasparenza e la notifica tempestiva di violazioni. Per garantire la sicurezza dei dati, Utixo propone un sistema di backup VPS avanzato, che effettua backup completi della macchina virtuale a livello di hypervisor senza agent software e utilizza crittografia AES a 256 bit end-to-end, conforme agli articoli 32 e 44 del GDPR. I backup sono conservati in uno storage dedicato nel datacenter principale certificato ISO/IEC 27001, con opzioni di backup remoti e disaster recovery su richiesta. Il sistema offre pianificazione flessibile e monitoraggio continuo, con backup conservati per cinque giorni e possibilità di configurazioni personalizzate come fasce orarie specifiche, destinazioni remote e ulteriori misure di sicurezza. Una corretta configurazione dei backup e della cifratura è essenziale per assicurare la conformità al GDPR e ridurre il rischio di perdita o compromissione dei dati sensibili.', '2026-03-06 12:24:30'),
(299, 'Virtual Private Server VPS', 'Come cambiare la porta RDP del desktop remoto', 'La porta 3389 è quella standard utilizzata dal protocollo RDP (Remote Desktop Protocol) per consentire connessioni remote su tutte le versioni moderne di Windows. Quando il desktop remoto è attivo, il servizio ascolta le connessioni su questa porta, che essendo ben conosciuta rappresenta un bersaglio facile per bot e script automatici che tentano accessi forzati. I rischi includono attacchi brute-force, possibili blocchi degli account anche senza successo e impatti sulle prestazioni del sistema. Durante un attacco, si possono notare numerosi eventi con ID 4625 nel Visualizzatore Eventi di Windows. Una delle contromisure più efficaci consiste nel cambiare la porta RDP predefinita. Per farlo, aprite l’Editor del Registro di sistema (regedit) come amministratore e navigate fino a HKEY_LOCAL_MACHINE\System\CurrentControlSet\Control\Terminal Server\WinStation\RDP-Tcp\PortNumber. Modificate il valore PortNumber con un numero di porta a vostra scelta che non sia già in uso (ad esempio 34989) e riavviate il server. Dopo il riavvio, potrete connettervi usando la nuova porta, aggiungendola all’indirizzo IP o hostname, ad esempio xx.xx.xx.xx:34989. È importante ricordare che il cambio della porta non sostituisce altre protezioni: si consiglia di abilitare l’autenticazione a due fattori, limitare l’accesso RDP a indirizzi IP specifici tramite firewall e implementare una politica di blocco per tentativi falliti.', 'La porta 3389 è quella predefinita dal protocollo RDP per le connessioni remote su Windows. Se il desktop remoto è attivo, il servizio ascolta su questa porta, che rappresenta un obiettivo noto per bot e script automatici. Gli attacchi più comuni includono brute-force e possibili blocchi degli account, con effetti anche sulle prestazioni del server. Durante tali eventi, il Visualizzatore Eventi di Windows registra numerosi eventi con ID 4625. Una misura efficace per aumentare la sicurezza consiste nel modificare la porta RDP. Per farlo, aprite regedit come amministratore e navigate fino alla chiave HKEY_LOCAL_MACHINE\System\CurrentControlSet\Control\Terminal Server\WinStation\RDP-Tcp\PortNumber, modificate PortNumber con un nuovo numero di porta libero e riavviate il sistema. Dopo il riavvio, sarà possibile connettersi al server usando l’indirizzo IP seguito dai due punti e dal nuovo numero di porta, ad esempio xx.xx.xx.xx:34989. Oltre al cambio di porta, si raccomanda di attivare l’autenticazione a due fattori, limitare l’accesso RDP a IP specifici e implementare un blocco automatico per tentativi falliti.', 'La porta standard RDP 3389 permette connessioni remote su Windows, ma essendo nota rappresenta un facile bersaglio per attacchi automatizzati. I rischi principali comprendono tentativi brute-force, blocchi accidentali degli account e rallentamenti o denial of service, con numerosi eventi ID 4625 registrati nel Visualizzatore Eventi di Windows. Per aumentare la sicurezza, è consigliato modificare la porta RDP predefinita. Aprite regedit come amministratore e raggiungete HKEY_LOCAL_MACHINE\System\CurrentControlSet\Control\Terminal Server\WinStation\RDP-Tcp\PortNumber; cambiate il valore PortNumber con una porta libera a vostra scelta e riavviate il server. Dopo il riavvio, la connessione al server remoto può avvenire usando il nuovo numero di porta, ad esempio xx.xx.xx.xx:34989. Il cambio della porta migliora la sicurezza ma non sostituisce altre protezioni, quindi è consigliabile abilitare l’autenticazione a due fattori, limitare l’accesso a IP specifici tramite firewall e applicare una politica di blocco dei tentativi falliti.', '2026-03-06 12:26:54'),
(300, 'Virtual Private Server VPS', 'Come cambiare la porta SSH su CentOS 7?', 'Una delle operazioni più comuni nella configurazione iniziale di un server Linux è modificare la porta predefinita di SSH, la 22, come misura di sicurezza di base per ridurre la visibilità del servizio agli attacchi automatici. Sebbene non rappresenti una protezione contro attacchi mirati, cambiare la porta può evitare scansioni da bot e script automatici, riducendo il carico sul server e i tentativi di brute force più banali. Per modificare la porta, apri il file di configurazione sshd_config con un editor di testo, ad esempio nano /etc/ssh/sshd_config, individua la riga #Port 22 e decommenta/modifica con una porta a tua scelta, come Port 7333, assicurandoti di scegliere una porta libera e superiore a 1023. Successivamente, se utilizzi CSF (ConfigServer Security & Firewall), apri la nuova porta nel firewall modificando il file /etc/csf/csf.conf e aggiungendo la porta scelta nella direttiva TCP_IN, poi riavvia CSF con csf -r. Infine, riavvia il servizio SSH con systemctl restart sshd o service sshd restart. Prima di chiudere la sessione SSH attuale, apri una nuova connessione con la nuova porta per verificare che tutto funzioni correttamente, così da poter correggere eventuali errori senza perdere l’accesso al server.', 'Modificare la porta predefinita di SSH su un server Linux è un intervento comune per aumentare la sicurezza di base, riducendo la visibilità del servizio agli attacchi automatizzati. Anche se non protegge contro attacchi mirati, questo accorgimento limita le scansioni di bot e i tentativi di brute force più elementari. Per effettuare la modifica, apri il file sshd_config con un editor come nano /etc/ssh/sshd_config e sostituisci la riga #Port 22 con una porta libera a tua scelta, ad esempio Port 7333. Se utilizzi CSF come firewall, aggiungi la nuova porta alla direttiva TCP_IN nel file /etc/csf/csf.conf e riavvia CSF con csf -r. Poi riavvia il servizio SSH usando systemctl restart sshd o service sshd restart. Prima di chiudere la sessione corrente, apri una nuova connessione SSH con la nuova porta per assicurarti che tutto funzioni correttamente e per poter correggere eventuali problemi senza perdere l’accesso al server.', 'Cambiare la porta SSH predefinita 22 su un server Linux è una pratica comune per migliorare la sicurezza di base, diminuendo la probabilità di scansioni automatiche e brute force banali. La procedura consiste nell’aprire il file di configurazione sshd_config (nano /etc/ssh/sshd_config), individuare la riga #Port 22 e modificarla o decommentarla con una porta libera a scelta, come Port 7333. Se il server utilizza CSF come firewall, occorre aggiungere la nuova porta alla direttiva TCP_IN nel file /etc/csf/csf.conf e riavviare CSF con csf -r. Successivamente, riavvia il servizio SSH con systemctl restart sshd o service sshd restart. È fondamentale aprire una nuova sessione SSH con la nuova porta prima di chiudere quella corrente, così da verificare il corretto funzionamento e poter correggere eventuali errori senza perdere l’accesso al server.', '2026-03-06 12:28:25'),
(301, 'Virtual Private Server VPS', 'Come configurare l’indirizzo IP', 'Su CentOS 7, il nome dell’interfaccia di rete può variare in base al tipo di installazione, sia bare-metal, cloud o virtualizzata, quindi prima di procedere è necessario identificarla con il comando ip addr. Una volta individuata, è possibile configurare manualmente l’interfaccia modificando o creando il file /etc/sysconfig/network-scripts/ifcfg-[nome_interfaccia], sostituendo [nome_interfaccia] con quello rilevato, ad esempio ifcfg-eth0. Il file deve contenere i parametri del dispositivo, inclusi DEVICE, BOOTPROTO=none, ONBOOT=yes, USERCTL=no, IPV6INIT=no, PEERDNS=yes, TYPE=Ethernet, NETMASK=255.255.255.255, l’IPADDR e il GATEWAY assegnati, oltre a ARP=yes e HWADDR con il MAC address corretto. Se necessario, bisogna creare anche il file di routing /etc/sysconfig/network-scripts/route-[nome_interfaccia], con contenuto che specifichi le rotte verso il gateway assegnato, la rete del server principale (con l’ultimo ottetto impostato a 0) e la rotta di default. Infine, per la configurazione DNS, modificare il file /etc/resolv.conf impostando nameserver 213.186.33.99.', 'Per configurare manualmente la rete su CentOS 7, è prima necessario identificare il nome dell’interfaccia attiva tramite ip addr, dato che può variare a seconda dell’installazione. Dopo aver rilevato il nome, modificare o creare il file /etc/sysconfig/network-scripts/ifcfg-[nome_interfaccia], sostituendo i valori tra parentesi quadre con i dati forniti dal provider o dalla configurazione di rete. Il file deve includere informazioni come DEVICE, BOOTPROTO=none, ONBOOT=yes, USERCTL=no, IPV6INIT=no, PEERDNS=yes, TYPE=Ethernet, NETMASK, IPADDR, GATEWAY, ARP e HWADDR. Se necessario, creare il file di routing /etc/sysconfig/network-scripts/route-[nome_interfaccia] con le rotte verso il gateway assegnato, la rete principale del server e la rotta di default. Per completare la configurazione, modificare /etc/resolv.conf impostando il nameserver a 213.186.33.99.', 'Su CentOS 7, il nome dell’interfaccia di rete varia a seconda del tipo di installazione, quindi è fondamentale individuarlo con ip addr prima di procedere. La configurazione manuale richiede la creazione o modifica del file /etc/sysconfig/network-scripts/ifcfg-[nome_interfaccia] con parametri quali DEVICE, BOOTPROTO=none, ONBOOT=yes, USERCTL=no, IPV6INIT=no, PEERDNS=yes, TYPE=Ethernet, NETMASK, IPADDR, GATEWAY, ARP e HWADDR. Successivamente, se necessario, occorre creare il file di routing /etc/sysconfig/network-scripts/route-[nome_interfaccia] per definire le rotte verso il gateway assegnato, la rete del server principale e la rotta di default. Infine, la configurazione DNS viene completata modificando /etc/resolv.conf e impostando nameserver 213.186.33.99. Tutti i valori tra parentesi quadre devono essere sostituiti con quelli forniti dal provider o dalla propria configurazione di rete.', '2026-03-06 12:30:11'),
(302, 'Virtual Private Server VPS', 'Come estendere il volume /home su un VPS Utixo con CentOS 7?', 'Questa procedura permette di estendere il volume /home su un VPS Utixo con CentOS 7 e filesystem XFS, valida esclusivamente per ambienti WHM configurati secondo gli standard Utixo. Prima di tutto, accedi alla console VMware e aumenta la dimensione del disco virtuale associato al VPS. Successivamente, monta l’immagine ISO di GParted dal pannello VMware, riavvia la macchina e avvia il sistema dall’ISO per estendere la partizione esistente seguendo le istruzioni a schermo; al termine, scollega l’ISO e riavvia nuovamente il sistema. Accedi quindi al server tramite console come root, verifica lo stato del disco e il nome del volume con df -h e utilizza lvextend -l +100%FREE /dev/cl/home per estendere il volume logico, sostituendo eventualmente il percorso con quello corretto visualizzato. Infine, poiché il filesystem è XFS, aggiorna lo spazio disponibile con xfs_growfs /dev/cl/home, adattando il percorso se necessario. Questa procedura è valida solo per VPS Utixo con CentOS 7 e WHM; in caso di configurazioni differenti o dubbi, contatta il supporto tecnico Utixo.', 'Per estendere il volume /home di un VPS Utixo basato su CentOS 7 con filesystem XFS e WHM, occorre innanzitutto aumentare la dimensione del disco virtuale tramite la console VMware. Poi, monta l’ISO di GParted dal pannello VMware, riavvia il VPS dall’ISO e segui le istruzioni a schermo per espandere la partizione esistente; al termine scollega l’ISO e riavvia il sistema. Accedi come root tramite console, verifica il nome e lo stato del volume con df -h e utilizza lvextend -l +100%FREE /dev/cl/home per estendere il volume logico, sostituendo eventualmente il percorso corretto. Infine, aggiorna lo spazio disponibile sul filesystem XFS con xfs_growfs /dev/cl/home. Questa procedura è applicabile esclusivamente ai server VPS Utixo con CentOS 7 e WHM; per ambienti differenti o dubbi, è consigliato contattare il supporto tecnico.', 'Estendere il volume /home su un VPS Utixo CentOS 7 con filesystem XFS richiede alcune operazioni specifiche. Prima di tutto, utilizza la console VMware per aumentare la dimensione del disco virtuale associato al VPS. Successivamente, monta l’ISO di GParted dal pannello VMware, riavvia la macchina dall’ISO e segui le istruzioni per estendere la partizione esistente, quindi scollega l’ISO e riavvia il sistema. Collegati come root, verifica lo stato del disco e il nome del volume con df -h e utilizza lvextend -l +100%FREE /dev/cl/home per espandere il volume logico, adattando il percorso se necessario. Infine, aggiorna il filesystem XFS con xfs_growfs /dev/cl/home. La procedura è valida solo per VPS Utixo con CentOS 7 e WHM; per altre configurazioni o in caso di dubbi, contatta il supporto tecnico Utixo.', '2026-03-06 12:32:46'),
(303, 'Virtual Private Server VPS', 'Come estendere un disco su CentOS 7?', 'Quando è necessario aumentare lo spazio disco su un VPS CentOS 7, Utixo si occupa dell’allocazione del disco fisico aggiuntivo tramite VMware, ma l’utente root deve completare la procedura con specifici comandi per rendere lo spazio disponibile al sistema operativo. La procedura è valida esclusivamente per server Utixo con CentOS 7 e richiede accesso root. In primo luogo, verifica lo stato del disco con df -h e prendi nota della partizione da estendere, ad esempio /dev/cl/home. Dopo che Utixo ha esteso il disco fisico dalla console VMware, monta l’ISO di GParted, riavvia il VPS dall’ISO e segui le istruzioni a schermo per estendere la partizione, quindi scollega l’ISO e riavvia nuovamente il sistema. Accedi come root tramite console o SSH e utilizza lvextend -l +100%FREE /dev/cl/home per estendere il volume logico, sostituendo il percorso se necessario. Infine, aggiorna il filesystem XFS con xfs_growfs /dev/cl/home. Per motivi di sicurezza e integrità dei dati, questa operazione può essere eseguita solo dal personale Utixo su richiesta del cliente con accesso root autorizzato.', 'Per estendere lo spazio disco di un VPS CentOS 7, Utixo provvede ad allocare il nuovo spazio fisico tramite VMware, ma l’utente root deve completare l’operazione affinché lo spazio sia effettivamente utilizzabile. La procedura è applicabile solo ai server Utixo con CentOS 7 e richiede privilegi root. È necessario verificare prima lo stato del disco con df -h e annotare la partizione da estendere, come /dev/cl/home. Una volta che il disco fisico è stato esteso tramite VMware, occorre montare l’ISO di GParted, riavviare il server dall’ISO, estendere la partizione seguendo le istruzioni a schermo, scollegare l’ISO e riavviare il sistema. Accedendo come root, si esegue lvextend -l +100%FREE /dev/cl/home per aumentare il volume logico e successivamente xfs_growfs /dev/cl/home per aggiornare il filesystem XFS. Questa procedura deve essere effettuata esclusivamente da personale Utixo con accesso root autorizzato per garantire sicurezza e integrità dei dati.', 'Quando un VPS CentOS 7 necessita di più spazio disco, Utixo alloca lo spazio aggiuntivo tramite VMware, ma l’utente root deve completare la configurazione affinché il sistema operativo possa utilizzarlo. La procedura è riservata ai server Utixo CentOS 7 con accesso root. Inizia controllando lo stato del disco con df -h e annota la partizione da estendere, ad esempio /dev/cl/home. Dopo l’operazione di estensione del disco fisico tramite VMware, monta l’ISO di GParted, riavvia il VPS dall’ISO e segui le istruzioni per espandere la partizione; al termine, scollega l’ISO e riavvia nuovamente. Collegandoti come root, estendi il volume logico con lvextend -l +100%FREE /dev/cl/home e aggiorna il filesystem XFS con xfs_growfs /dev/cl/home. Per motivi di sicurezza e protezione dei dati, tale procedura può essere eseguita solo da personale Utixo autorizzato su richiesta del cliente.', '2026-03-06 12:34:57'),
(304, 'Virtual Private Server VPS', 'Come gestire server VPS standard Utixo?', 'Il control panel UCMP di Utixo offre una piattaforma intuitiva per gestire le VPS in modo semplice, veloce e automatizzato, consentendo di effettuare tutte le operazioni critiche direttamente dal pannello senza interventi manuali. Tra le funzionalità principali vi sono il provisioning automatico di nuovi server al momento dell’ordine, la reinstallazione del sistema operativo in modalità automatizzata secondo i parametri scelti, la modifica delle risorse come CPU, RAM e spazio disco con un solo click, l’attivazione di servizi aggiuntivi come backup e funzionalità di rete avanzate, e una dashboard interattiva che mostra lo stato del provisioning e delle risorse in tempo reale. Il pannello permette inoltre la gestione rapida dei server tramite operazioni come reboot, shutdown, reset e accesso alla console VNC, oltre alla gestione di snapshot e backup programmati, configurazione avanzata del firewall, amministrazione delle reti IPv4 e IPv6 con reverse DNS, monitoraggio delle risorse in tempo reale con cronologia su CPU, traffico, IOPS e RAM, e consultazione dello storico completo delle attività effettuate sul server. È possibile accedere alla console VNC direttamente dal pannello oppure tramite un client remoto utilizzando il comando indicato nell’interfaccia, ottenendo una panoramica completa dello stato del server e delle risorse disponibili.', 'UCMP, il control panel di Utixo, permette di gestire le VPS in modo rapido e automatizzato, eseguendo tutte le operazioni critiche senza necessità di interventi manuali. Il pannello consente la creazione automatica dei server al momento dell’ordine, la reinstallazione del sistema operativo in modalità guidata, l’upgrade o downgrade delle risorse come CPU, RAM e spazio disco con un click, e l’attivazione di servizi aggiuntivi come backup o funzionalità di rete avanzate. La dashboard interattiva mostra lo stato del provisioning e delle risorse in tempo reale, mentre le operazioni di gestione includono reboot, shutdown, reset e accesso alla console VNC. UCMP gestisce anche snapshot istantanei e backup programmati, permette di configurare il firewall, amministrare le reti IPv4 e IPv6 con reverse DNS, monitorare CPU, traffico, IOPS e RAM e consultare lo storico delle attività. La console VNC è accessibile direttamente dal pannello o tramite client remoto utilizzando il comando fornito dall’interfaccia, offrendo una visione completa dello stato operativo della VPS.', 'Il control panel UCMP di Utixo offre una gestione centralizzata delle VPS, rendendo semplici e automatizzate tutte le operazioni critiche senza interventi manuali. Consente il provisioning immediato di nuovi server, la reinstallazione guidata del sistema operativo, l’upgrade e downgrade delle risorse hardware, e l’attivazione di servizi opzionali come backup e funzionalità di rete avanzate. La dashboard interattiva fornisce informazioni in tempo reale sullo stato dei server e delle risorse, mentre la gestione operativa permette reboot, shutdown, reset e accesso alla console VNC. Sono disponibili funzionalità avanzate per snapshot e backup programmati, configurazione firewall, amministrazione di IPv4 e IPv6 con reverse DNS, monitoraggio dettagliato delle risorse e consultazione dello storico delle operazioni. L’accesso alla console VNC può avvenire direttamente dal pannello o tramite un client remoto seguendo il comando indicato, garantendo una panoramica completa delle risorse e dello stato della VPS.', '2026-03-06 12:36:48'),
(305, 'Virtual Private Server VPS', 'Come monitorare Basic VPS', 'Utixo offre un servizio di monitoraggio automatico dei server che controlla periodicamente lo stato dei servizi attivi, segnalando tempestivamente eventuali problemi. Questo servizio è incluso in alcuni piani o può essere acquistato separatamente dal portale Utixo come "Monitoraggio Basic Cloud Services". Il sistema consente di personalizzare la frequenza di monitoraggio a intervalli di 2, 5, 10, 15, 20, 30, 45 o 60 minuti, invia notifiche automatiche via email e SMS in caso di problemi, permette di configurare più contatti destinatari e monitorare simultaneamente diversi protocolli o server. Inoltre, genera report dettagliati che includono tempi di risposta e durata dei downtime. Tra i protocolli supportati vi sono HTTP e HTTPS per web server, FTP per trasferimento file, SMTP, POP3 e IMAP per la posta, MYSQL per database, SSL per certificati, DNS per il Domain Name System, TCP per porte personalizzate, PING per la verifica della raggiungibilità degli host, blacklist SPAM per il controllo IP e Header Status per la verifica degli header HTTP. L’interfaccia del control panel Utixo permette di visualizzare in tempo reale lo stato dei servizi, gli eventi di downtime e i tempi di risposta.', 'Il servizio di monitoraggio server di Utixo verifica automaticamente lo stato dei servizi attivi e segnala eventuali problemi in modo rapido. Disponibile in alcuni piani o acquistabile separatamente come "Monitoraggio Basic Cloud Services", consente di impostare intervalli di controllo da 2 a 60 minuti, inviare notifiche via email e SMS, configurare più destinatari e monitorare diversi servizi simultaneamente. Il sistema genera report dettagliati con tempi di risposta e durata dei downtime. Sono supportati protocolli come HTTP, HTTPS, FTP, SMTP, POP3, IMAP, MYSQL, SSL, DNS, TCP, PING, Blacklist SPAM e Header Status per controlli avanzati. Tramite il control panel Utixo è possibile avere una panoramica completa dello stato dei servizi, con informazioni sui tempi di risposta e gli eventi di downtime.', 'Utixo mette a disposizione un servizio di monitoraggio automatico dei server che controlla regolarmente i servizi attivi e notifica immediatamente eventuali malfunzionamenti. Incluso in alcuni piani o disponibile come servizio aggiuntivo denominato "Monitoraggio Basic Cloud Services", consente di scegliere intervalli di monitoraggio da 2 a 60 minuti, inviare notifiche email e SMS, aggiungere più destinatari e controllare più servizi contemporaneamente. I report forniti riportano tempi di risposta e durata dei downtime, mentre i protocolli supportati includono HTTP, HTTPS, FTP, SMTP, POP3, IMAP, MYSQL, SSL, DNS, TCP, PING, Blacklist SPAM e Header Status. Il pannello di controllo Utixo mostra in tempo reale lo stato dei servizi, gli eventuali downtime e le performance dei server monitorati.', '2026-03-06 12:39:35'),
(306, 'Virtual Private Server VPS', 'Come usare il pannello di controllo Utixo VPS Management', 'Utixo offre ai propri clienti un pannello di controllo VPS avanzato che permette la gestione completa del server virtuale. Per accedere al pannello, vai su https://controlpanel.utixo.co.uk e inserisci le tue credenziali, quindi seleziona il menu “I miei servizi”, individua il servizio Cloud Virtual Server e clicca su “Attivo” per entrare nella gestione VPS. Il pannello consente di visualizzare le risorse disponibili come CPU, RAM e spazio disco, monitorare lo stato e le caratteristiche hardware del VPS, eseguire accensione, spegnimento, riavvio e reinstallazione del sistema operativo, creare snapshot istantanei, accedere direttamente alla console VNC e gestire indirizzi IP con reverse DNS e regole firewall. È possibile visualizzare in tempo reale lo stato del server, con grafici sulle ultime 24 ore relativi a larghezza di banda, utilizzo CPU e memoria. La funzione Snapshot permette di creare backup immediati prima di aggiornamenti critici, modifiche di sistema o installazione di software, tenendo presente che la configurazione standard consente un solo snapshot, quindi è consigliabile eliminare quelli non più necessari. L’accesso diretto alla console VPS garantisce la gestione della macchina anche in caso di problemi di rete, equivalente a un accesso fisico, mentre la gestione IP e firewall permette di configurare reverse DNS e applicare regole di sicurezza, ricordando che modifiche errate possono compromettere il funzionamento del VPS.', 'Il pannello di controllo VPS di Utixo permette una gestione completa e avanzata dei server virtuali, con accesso tramite https://controlpanel.utixo.co.uk usando le proprie credenziali. Una volta entrati in “I miei servizi” e selezionato il Cloud Virtual Server cliccando su “Attivo”, è possibile monitorare le risorse come CPU, RAM e disco, controllare lo stato hardware, eseguire operazioni come accensione, spegnimento, riavvio e reinstallazione dell’OS, creare snapshot, accedere alla console VNC e gestire IP e firewall, inclusi reverse DNS e regole di accesso. Il pannello mostra grafici in tempo reale su rete, CPU e memoria per le ultime 24 ore, e la funzione Snapshot consente di salvare backup immediati prima di aggiornamenti o modifiche critiche, con la possibilità di eliminare snapshot non necessari per evitare rallentamenti. L’accesso diretto alla console VPS permette di operare sulla macchina anche in caso di problemi di rete, mentre la gestione IP e firewall offre strumenti per proteggere e configurare la macchina con attenzione, poiché errori possono influire sul corretto funzionamento del server.','Utixo mette a disposizione un pannello di controllo VPS completo e intuitivo, accessibile su https://controlpanel.utixo.co.uk inserendo le credenziali e navigando in “I miei servizi” fino al Cloud Virtual Server cliccando su “Attivo”. Dal pannello è possibile monitorare le risorse disponibili come CPU, RAM e spazio disco, controllare lo stato hardware del VPS, eseguire operazioni di accensione, spegnimento, riavvio e reinstallazione del sistema operativo, creare snapshot istantanei e accedere direttamente alla console VNC. La gestione degli indirizzi IP e delle regole firewall, compreso il reverse DNS, è integrata nella piattaforma, mentre i grafici in tempo reale permettono di controllare l’utilizzo di rete, CPU e memoria sulle ultime 24 ore. La funzione Snapshot consente di effettuare backup immediati prima di aggiornamenti, modifiche di sistema o installazioni software, con la raccomandazione di eliminare snapshot non più necessari. L’accesso diretto alla console VPS garantisce il controllo della macchina anche in caso di problemi di rete, ma è importante operare con attenzione nella configurazione di IP e firewall per evitare malfunzionamenti del server.' ,'2026-03-06 12:42:28'),
(307, 'Virtual Private Server VPS', 'Perdita apparente di pacchetti ping su VPS con cPanel e CSF', 'Se avete un server VPS con cPanel e firewall CSF, potreste notare una presunta perdita di pacchetti quando eseguite comandi come ping -t. Questo fenomeno non è dovuto a problemi di rete, ma alla configurazione di sicurezza predefinita di CSF, che limita la frequenza di risposta del protocollo ICMP per prevenire attacchi di tipo DoS. Il parametro responsabile è ICMP_IN_RATE, impostato di default a 1/s, cioè una risposta al secondo. Per rimuovere la perdita di pacchetti, è possibile aumentare questo valore modificando la configurazione di CSF. È necessario accedere al server come root, aprire il file /etc/csf/csf.conf, cercare la direttiva ICMP_IN_RATE e impostarla, ad esempio, a 20/s. Dopo aver salvato il file, riavviare CSF con il comando csf -r. Bisogna ricordare che questa modifica aumenta la reattività ai ping, ma incrementa anche l’esposizione a potenziali attacchi, quindi va effettuata solo se necessario e valutando le implicazioni di sicurezza.', 'Quando si utilizza un VPS con cPanel e firewall CSF, può apparire una perdita di pacchetti durante l’esecuzione di comandi come ping -t. Questo comportamento è causato dal firewall CSF che, per motivi di sicurezza, limita il numero di risposte ICMP al secondo, impedendo possibili attacchi DoS. Il parametro di configurazione coinvolto è ICMP_IN_RATE, che di default vale 1/s. Per ridurre o eliminare questa apparente perdita di pacchetti, bisogna accedere al server con privilegi root, aprire /etc/csf/csf.conf, modificare ICMP_IN_RATE impostandolo su un valore maggiore, ad esempio 20/s, e infine riavviare CSF con csf -r. Questa operazione rende il server più reattivo ai ping, ma può aumentare il rischio di esposizione ad attacchi, quindi è consigliabile intervenire solo se strettamente necessario.', 'Su un VPS con cPanel e CSF, un test ping può mostrare una perdita di pacchetti che non indica problemi di rete, ma è dovuta alla limitazione del protocollo ICMP impostata dal firewall CSF per prevenire attacchi DoS. La direttiva ICMP_IN_RATE definisce quante risposte ICMP il server può inviare al secondo, con valore predefinito 1/s. Per aumentare la reattività ai ping, è necessario accedere come root, modificare il file /etc/csf/csf.conf, aumentare ICMP_IN_RATE a un valore più alto come 20/s e riavviare CSF con csf -r. È importante tenere presente che aumentare questo limite può rendere il server più esposto a tentativi di attacco, quindi la modifica va eseguita solo quando strettamente necessaria e valutando le implicazioni di sicurezza.', '2026-03-06 12:44:18'),
(308, 'Virtual Private Server VPS', 'Attivazione della versione definitiva di Windows Server da licenza Evaluation', 'La versione Evaluation di Windows Server permette di testare il sistema operativo senza acquistare subito una licenza, ma alla scadenza del periodo di prova il server inizierà a spegnersi automaticamente a intervalli regolari, rendendo impossibile il normale utilizzo. Per convertire una licenza TRIAL in una licenza definitiva di tipo Standard, è necessario aprire il Prompt dei comandi come amministratore, quindi eseguire il comando DISM /online /Set-Edition:ServerStandard /ProductKey:XXXXX-XXXXX-XXXXX-XXXXX-XXXXX /AcceptEula, sostituendo XXXXX-XXXXX-XXXXX-XXXXX-XXXXX con la chiave prodotto acquistata. L’opzione Set-Edition indica l’edizione di destinazione, ProductKey specifica la chiave di licenza definitiva e AcceptEula accetta automaticamente i termini della licenza. Al termine della procedura, potrebbe essere richiesto un riavvio del sistema per applicare correttamente la nuova licenza.', 'Windows Server in versione Evaluation consente di provare il sistema senza licenza immediata, ma al termine del periodo di prova il sistema esegue spegnimenti automatici, rendendo il server inutilizzabile. Per passare a una licenza Standard definitiva, aprire il Prompt dei comandi con privilegi di amministratore e digitare DISM /online /Set-Edition:ServerStandard /ProductKey:XXXXX-XXXXX-XXXXX-XXXXX-XXXXX /AcceptEula, sostituendo la chiave con quella acquistata. Questo comando indica a Windows di cambiare l’edizione del sistema a ServerStandard, accettando automaticamente la licenza e applicando la chiave definitiva. Dopo l’esecuzione, è consigliato riavviare il server affinché la nuova licenza sia attiva.', 'La versione Evaluation di Windows Server permette di testare il sistema operativo senza licenza definitiva, ma al termine del periodo di prova il server sarà soggetto a spegnimenti automatici che ne impediscono l’uso regolare. Per convertire la licenza TRIAL in una licenza Standard, occorre aprire il Prompt dei comandi come amministratore e inserire il comando DISM /online /Set-Edition:ServerStandard /ProductKey:XXXXX-XXXXX-XXXXX-XXXXX-XXXXX /AcceptEula, sostituendo la chiave prodotto con quella definitiva. Questo comando modifica l’edizione del sistema a ServerStandard, accetta la licenza e applica la chiave, dopodiché potrebbe essere necessario riavviare il server per rendere effettiva la nuova licenza.', '2026-03-06 12:46:40'),
(309, 'Veeam Cloud Connect (VCC)', 'Come configurare Utixo Veeam Cloud Connect con Veeam agent for Windows?', 'Per configurare un job di backup con Veeam Agent for Windows utilizzando Veeam Cloud Connect come destinazione, avvia innanzitutto Veeam Agent e seleziona l’opzione per aggiungere un nuovo job. Prosegui con la configurazione guidata fino ad arrivare alla sezione “Destination”, dove dovrai scegliere come tipo di storage il repository Veeam Cloud Connect. Inserisci come destinazione l’indirizzo vcc.utixo.cloud, mantenendo la porta di default, quindi autentica il job utilizzando le credenziali (username e password) fornite da Utixo al momento della registrazione del servizio. Infine, definisci gli orari e la frequenza con cui desideri eseguire i backup automatici, completando così la configurazione del job.', 'Per creare un job di backup tramite Veeam Agent for Windows verso Veeam Cloud Connect, apri il software e seleziona l’opzione per aggiungere un nuovo job. Avanza nella configurazione fino alla sezione “Destination” e scegli come tipo di storage il repository Veeam Cloud Connect. Inserisci l’indirizzo vcc.utixo.cloud lasciando la porta predefinita, quindi autentica il collegamento con le credenziali fornite da Utixo. Completa la configurazione impostando gli orari e la frequenza dei backup automatici secondo le tue esigenze, assicurandoti che il job sia correttamente programmato e pronto a eseguire le operazioni di backup.', 'La configurazione di un job di backup con Veeam Agent for Windows verso Veeam Cloud Connect inizia aprendo il software e aggiungendo un nuovo job. Procedi con la configurazione guidata fino alla sezione “Destination”, selezionando come tipo di storage il repository Veeam Cloud Connect. Imposta l’indirizzo di destinazione su vcc.utixo.cloud e inserisci le credenziali fornite da Utixo per l’autenticazione. Concludi definendo la pianificazione dei backup, impostando gli orari e la frequenza desiderata, così che il job possa eseguire automaticamente i backup verso la destinazione cloud.', '2026-03-06 12:51:17'),
(310, 'Posta Elettronica', 'Email deliverability', 'Una delle domande più frequenti nella gestione delle campagne email riguarda la certezza del recapito dei messaggi. In realtà non esiste una garanzia assoluta, ma è possibile migliorare significativamente la deliverability adottando alcune buone pratiche tecniche e operative. Il successo dipende principalmente dalla corretta configurazione dei protocolli di autenticazione e dalla reputazione dell’indirizzo IP utilizzato per l’invio. Monitorare regolarmente la reputazione IP è fondamentale, poiché la presenza in blacklist pubbliche può compromettere gravemente la consegna delle email. In caso di inserimento in blacklist, è necessario avviare una procedura di delisting dopo aver risolto le cause che hanno generato lo spam. Un altro aspetto cruciale è l’autenticazione delle email tramite SPF, DKIM e DMARC, che permettono di verificare l’identità del mittente e migliorare la fiducia dei server destinatari. Inoltre, quando si utilizza un nuovo indirizzo IP, è importante effettuare un processo di IP warm-up, aumentando gradualmente il volume di invio per costruire una reputazione positiva. Infine, è essenziale evitare gli hard bounce rimuovendo gli indirizzi non validi, poiché invii ripetuti a caselle inesistenti possono penalizzare ulteriormente la reputazione del mittente.', 'Garantire che tutte le email raggiungano i destinatari non è possibile, ma è possibile aumentare la deliverability adottando strategie mirate. Tra i fattori più importanti vi sono la configurazione corretta dei sistemi di autenticazione e la reputazione dell’indirizzo IP di invio. È fondamentale controllare periodicamente che l’IP non sia presente in blacklist, poiché ciò può ridurre drasticamente il tasso di consegna. Se l’IP risulta bloccato, è necessario richiedere il delisting dopo aver eliminato le cause dello spam. L’implementazione di SPF, DKIM e DMARC consente di autenticare le email e migliorare la fiducia dei server destinatari. Inoltre, quando si utilizza un nuovo IP, è consigliabile eseguire un IP warm-up, aumentando gradualmente il volume di invio per evitare comportamenti sospetti agli occhi degli ISP. Anche la gestione delle liste è fondamentale: eliminare indirizzi non validi e ridurre gli hard bounce aiuta a mantenere una buona reputazione e a migliorare la deliverability complessiva.', 'Non esiste un metodo che garantisca al 100% il recapito delle email, ma è possibile ottimizzare la deliverability intervenendo su diversi aspetti tecnici e operativi. La reputazione dell’indirizzo IP e la configurazione dei protocolli di autenticazione sono elementi chiave: essere presenti in blacklist può compromettere la consegna dei messaggi, mentre una corretta configurazione di SPF, DKIM e DMARC migliora l’affidabilità del mittente. In caso di inserimento in blacklist, è necessario procedere con il delisting solo dopo aver risolto le cause che hanno generato il problema. Quando si utilizza un nuovo IP, è importante eseguire un IP warm-up per costruire gradualmente una reputazione positiva ed evitare blocchi da parte degli ISP. Infine, una gestione accurata delle liste email, con la rimozione degli indirizzi non validi, è essenziale per evitare hard bounce e mantenere elevate le probabilità di consegna dei messaggi.', '2026-03-20 12:21:38'),
(311, 'Posta Elettronica', 'Blocco invio delle mail', 'L’errore “Domain has exceeded the max defers and failures per hour” indica che il dominio ha superato il numero massimo consentito di email non consegnate o temporaneamente rifiutate nell’arco di un’ora. Questo accade generalmente quando vengono inviati molti messaggi verso indirizzi non validi, inesistenti o momentaneamente irraggiungibili. Per tutelare la reputazione del dominio ed evitare possibili blacklist, il sistema applica automaticamente un blocco temporaneo dell’invio. Tale limitazione ha una durata di circa un’ora, al termine della quale il sistema tenterà nuovamente l’invio delle email in coda, a condizione che il tasso di errore sia rientrato nei limiti accettabili. Questo meccanismo di protezione è fondamentale perché un elevato numero di invii falliti è tipico dei comportamenti spam e potrebbe portare i principali provider di posta, come Gmail, Outlook o Yahoo, a considerare il dominio come non affidabile, con conseguente rischio di finire in blacklist, recapito in spam o rifiuto dei messaggi.','Il messaggio “Domain has exceeded the max defers and failures per hour” segnala che il dominio ha superato il limite orario di email fallite o differite. Questa situazione si verifica quando vengono inviati troppi messaggi verso caselle non valide o temporaneamente non disponibili. Per evitare danni alla reputazione del dominio, il sistema attiva automaticamente un blocco temporaneo dell’invio delle email. Il blocco dura generalmente un’ora e, una volta trascorso questo intervallo, il sistema riprende l’invio delle email rimaste in coda, purché il livello di errori sia tornato nella norma. Questa misura serve a prevenire comportamenti assimilabili allo spam, che potrebbero portare i provider di posta a penalizzare il dominio con inserimento in blacklist, consegna nella cartella spam o rifiuto dei messaggi.', 'Quando compare l’errore “Domain has exceeded the max defers and failures per hour”, significa che il dominio ha raggiunto e superato il limite massimo di email non consegnate o ritardate consentite in un’ora. Questo accade tipicamente a causa dell’invio verso indirizzi email errati, inesistenti o non raggiungibili. Per proteggere la reputazione del dominio e prevenire possibili abusi, il sistema blocca temporaneamente l’invio delle email. Il blocco ha una durata di circa un’ora, dopodiché il sistema tenterà nuovamente l’invio dei messaggi in sospeso, se le condizioni lo permettono. Questo meccanismo è importante per evitare che il dominio venga identificato come fonte di spam dai provider di posta, con conseguenze come l’inserimento in blacklist, la consegna dei messaggi nella cartella spam o il rifiuto completo delle email.', '2026-03-20 12:23:29'),
(312, 'Posta Elettronica', 'Come migrare il contenuto della posta', 'Quando si effettua una migrazione della posta elettronica da un provider a un altro, come ad esempio da Aruba a Microsoft 365, è importante utilizzare uno strumento affidabile che garantisca il trasferimento dei dati senza perdite. OVH Mail Migrator rappresenta una soluzione gratuita e semplice da utilizzare, che consente di migrare le email tra diversi servizi senza richiedere configurazioni tecniche avanzate. Questo strumento è compatibile con numerosi provider, tra cui OVH Mail, Microsoft Exchange, Gmail, Yahoo Mail e server IMAP generici, e permette di copiare le email senza interrompere l’accesso alle caselle di posta. La migrazione avviene inserendo i dati dell’account di origine e di destinazione direttamente nell’interfaccia web, avviando poi il processo automatico e monitorandone l’avanzamento in tempo reale. Al termine, è possibile verificare che tutte le email, comprese quelle presenti nelle cartelle come Posta inviata e Bozze, siano state trasferite correttamente. È importante considerare che lo strumento trasferisce esclusivamente i messaggi email e non include contatti o calendari, e che la durata dell’operazione dipende dal volume dei dati.', 'La migrazione delle email tra provider diversi, come nel passaggio da Aruba a Microsoft 365, richiede uno strumento che assicuri continuità e integrità dei dati. OVH Mail Migrator è una piattaforma online gratuita progettata per semplificare questo processo, permettendo il trasferimento delle email senza necessità di configurazioni complesse. Supporta diversi servizi di posta, inclusi Exchange, Gmail, Yahoo e server IMAP, e consente di copiare i messaggi mantenendo attivo l’accesso alle caselle durante tutta la procedura. Per eseguire la migrazione è sufficiente accedere allo strumento, inserire le credenziali dell’account di origine e di destinazione e avviare il trasferimento, che può essere monitorato tramite un pannello dedicato. Al termine, è consigliabile verificare che tutte le email siano state migrate correttamente. Va tenuto presente che il servizio non include la migrazione di contatti e calendari e che i tempi di completamento possono variare in base alla quantità di dati da trasferire.', 'Per trasferire il contenuto della posta elettronica tra sistemi diversi, ad esempio da Aruba a Microsoft 365, è possibile utilizzare OVH Mail Migrator, uno strumento gratuito che consente di effettuare la migrazione in modo semplice e sicuro. Questo servizio supporta diversi provider, tra cui OVH Mail, Microsoft Exchange, Gmail, Yahoo e qualsiasi server basato su IMAP, e permette di copiare le email senza interrompere il normale utilizzo delle caselle. Il processo consiste nell’inserire i dati dell’account di origine e di quello di destinazione, avviare la migrazione e monitorarne lo stato tramite un’interfaccia web intuitiva. Una volta completato, è possibile verificare la corretta importazione delle email, incluse le cartelle principali. È importante sapere che lo strumento trasferisce solo i messaggi email e non include altri dati come contatti o calendari, e che la durata della procedura dipende dalla quantità di email presenti nelle caselle.', '2026-03-20 12:34:08' ),
(313, 'Posta Elettronica', 'Come proteggersi da spammers e tentativi di spoofing?', 'Per proteggersi dagli attacchi di spoofing è fondamentale utilizzare strumenti affidabili come il Sender Policy Framework (SPF), un sistema di autenticazione che permette ai server di posta di verificare se un’email proviene da un host autorizzato dal dominio del mittente. Il funzionamento si basa sul controllo dell’indirizzo IP del server che invia il messaggio, confrontandolo con l’elenco degli host autorizzati configurati nel DNS del dominio. Se l’IP non risulta tra quelli autorizzati, l’email viene generalmente segnalata come spam o rifiutata. Per garantire un corretto utilizzo di SPF è necessario configurare nel DNS tutti gli IP e gli hostname legittimi che inviano posta per conto del dominio. Questo meccanismo rappresenta una prima barriera contro phishing e spam, e può essere ulteriormente rafforzato integrandolo con altri sistemi di sicurezza email. L’attivazione di SPF da cPanel avviene accedendo alla sezione Email e poi alla voce Autenticazione, dove è possibile abilitare il record SPF. È importante ricordare di includere manualmente eventuali server esterni o servizi SMTP utilizzati, per evitare problemi di recapito.', 'Il Sender Policy Framework (SPF) è uno strumento essenziale per difendersi da tentativi di spoofing e garantire l’autenticità delle email inviate dal proprio dominio. Questo sistema consente ai server di posta destinatari di verificare che l’indirizzo IP del mittente sia autorizzato, confrontandolo con i record DNS del dominio. Se il server di invio non è presente tra quelli autorizzati, il messaggio viene spesso classificato come spam. Per un funzionamento corretto è necessario configurare nel DNS tutti gli indirizzi IP e i server che inviano email per conto del dominio. SPF costituisce il primo livello di protezione contro spam e phishing, e può essere integrato con ulteriori sistemi di sicurezza per una protezione più completa. L’attivazione tramite cPanel è semplice e avviene dalla sezione Email, accedendo alla voce Autenticazione, dove è possibile abilitare il record SPF. È fondamentale includere anche eventuali servizi esterni di invio per evitare problemi nella consegna delle email.', 'Per prevenire attacchi di spoofing e migliorare la sicurezza delle email, è consigliabile implementare il Sender Policy Framework (SPF), un meccanismo che verifica se il server che invia un messaggio è autorizzato dal dominio del mittente. Il controllo avviene confrontando l’indirizzo IP del server di invio con quelli indicati nei record DNS del dominio; se non corrisponde, il messaggio può essere classificato come spam o rifiutato. Una corretta configurazione SPF richiede l’inserimento nel DNS di tutti gli IP e gli hostname autorizzati a inviare email per il dominio. Questo sistema rappresenta una difesa base contro phishing e spam, e può essere potenziato con ulteriori tecnologie di autenticazione email. Per attivare SPF da cPanel è sufficiente accedere alla sezione Email e selezionare Autenticazione, dove è disponibile l’opzione di attivazione. È importante includere anche eventuali server SMTP esterni per evitare problemi di recapito e garantire la corretta consegna delle email.', '2026-03-20 12:36:29'),
(314, 'Posta Elettronica', 'IMAP o POP3?', 'Quando configuri un account email in cPanel, puoi scegliere tra i protocolli IMAP e POP3, che rappresentano due modalità differenti di gestione della posta. Con IMAP, i messaggi rimangono archiviati sul server e tutte le modifiche effettuate dal client vengono sincronizzate, permettendo di accedere alla stessa casella da più dispositivi mantenendo sempre aggiornate cartelle e contenuti. Con POP3, invece, i messaggi vengono scaricati sul computer e, nella configurazione standard, rimossi dal server, rendendo la posta disponibile solo localmente. La scelta dipende dalle esigenze: IMAP è consigliato se utilizzi più dispositivi o la webmail, mentre POP3 può essere preferibile in caso di spazio limitato sul server o connessioni lente, poiché consente di conservare i messaggi direttamente sul proprio dispositivo.', 'In fase di creazione di un account email su cPanel, è possibile scegliere tra IMAP e POP3, due protocolli che gestiscono la posta in modo diverso. IMAP mantiene email e cartelle sul server e sincronizza automaticamente ogni operazione tra client e server, risultando ideale per chi consulta la posta da più dispositivi o utilizza frequentemente la webmail. POP3, al contrario, scarica i messaggi sul computer e li elimina dal server, salvo configurazioni specifiche, rendendo l’accesso locale l’unica modalità di consultazione. La scelta dipende dall’utilizzo: IMAP è indicato per flessibilità e sincronizzazione, mentre POP3 è più adatto a chi ha spazio limitato sulla casella o utilizza connessioni poco stabili e preferisce archiviare i messaggi in locale.', 'Durante la configurazione di un account email in cPanel è necessario scegliere tra IMAP e POP3, due protocolli che differiscono nel modo in cui gestiscono i messaggi. IMAP conserva le email sul server e sincronizza ogni modifica tra tutti i dispositivi utilizzati, consentendo un accesso sempre aggiornato da qualsiasi client o webmail. POP3, invece, scarica i messaggi sul dispositivo locale e generalmente li rimuove dal server, limitando l’accesso a un solo dispositivo. Per questo motivo, IMAP è la soluzione migliore per chi utilizza più dispositivi o vuole mantenere la posta sincronizzata, mentre POP3 può risultare utile in presenza di limiti di spazio sulla casella o in situazioni con connessioni lente o intermittenti, dove è preferibile salvare i messaggi direttamente sul computer.', '2026-03-20 12:37:51'),
(315, 'Posta Elettronica', 'Come sincronizzare la posta Gmail?', 'Se la posta elettronica non si sincronizza sul tuo smartphone, il problema può dipendere da diversi fattori comuni. Per prima cosa verifica la connessione a Internet, assicurandoti che il dispositivo sia collegato a una rete Wi-Fi stabile o a una rete mobile attiva, poiché una connessione assente o instabile impedisce l’aggiornamento delle email. Un’altra causa frequente è una password errata: prova ad accedere alla webmail tramite browser, ad esempio su cPanel o Microsoft 365, per verificare che le credenziali siano corrette, e in caso contrario aggiornale anche nell’app del telefono. Dopo aver confermato la password, assicurati che sia inserita correttamente nell’app email, modificandola dalle impostazioni dell’account su iPhone o Android. È inoltre importante controllare lo spazio disponibile nella casella, perché una casella piena non può ricevere nuovi messaggi; in tal caso, elimina email inutili o valuta un aumento dello spazio. Se il problema persiste, prova a riavviare il dispositivo oppure rimuovere e riconfigurare l’account email, operazione che non cancella i messaggi dal server ma solo dal telefono. Se anche dopo questi passaggi la sincronizzazione non funziona, potrebbe trattarsi di un problema di configurazione, firewall o servizio, ed è consigliabile contattare il supporto fornendo dettagli su dispositivo, app utilizzata ed eventuali errori riscontrati.', 'La mancata sincronizzazione della posta sul telefono può essere causata da diversi fattori, ma spesso si tratta di problemi semplici da risolvere. Innanzitutto è importante verificare la connessione a Internet, controllando che il dispositivo sia connesso a una rete Wi-Fi o dati mobile funzionante. Un’altra causa comune è la password non aggiornata: è consigliabile testarla accedendo alla webmail e, se necessario, aggiornarla anche nell’app di posta del dispositivo. Una volta verificata la correttezza delle credenziali, assicurati che siano configurate correttamente nelle impostazioni dell’account sul telefono. Controlla anche lo spazio disponibile nella casella email, perché una casella piena blocca la ricezione di nuovi messaggi. In molti casi, un semplice riavvio del dispositivo può risolvere problemi temporanei; in alternativa, è possibile rimuovere e aggiungere nuovamente l’account per ristabilire la sincronizzazione. Se il problema continua, potrebbe essere legato a configurazioni errate, porte bloccate, firewall o problemi del servizio, e in tal caso è consigliato contattare il supporto tecnico fornendo tutte le informazioni utili per la diagnosi.', 'Se le email non si aggiornano sullo smartphone, è necessario verificare alcuni aspetti fondamentali. Inizia controllando la connessione a Internet, assicurandoti che sia attiva e stabile, poiché senza rete la sincronizzazione non può avvenire. Successivamente verifica la password dell’account provando l’accesso via webmail: se non funziona, dovrai aggiornarla anche nell’app del telefono. Dopo aver confermato le credenziali, assicurati che siano inserite correttamente nelle impostazioni dell’account sul dispositivo. È importante anche controllare lo spazio disponibile nella casella, perché una casella piena impedisce la ricezione di nuovi messaggi. Se il problema persiste, prova a riavviare il telefono o a rimuovere e riconfigurare completamente l’account email. Questa operazione non comporta la perdita delle email, che restano salvate sul server. Qualora la sincronizzazione continui a non funzionare, le cause potrebbero essere più tecniche, come errori di configurazione, blocchi firewall o problemi lato servizio, e sarà quindi necessario contattare il supporto fornendo dettagli sul dispositivo, sull’app utilizzata e sugli eventuali messaggi di errore.', '2026-03-20 12:39:43'),
(316, 'Posta Elettronica', 'Non ricevo nuova posta', 'Se non ricevi nuove email nonostante il servizio di posta in entrata sembri funzionare correttamente, è importante verificare innanzitutto lo spazio disponibile sul tuo account. Accedi al pannello di controllo e controlla il valore relativo allo spazio disco disponibile, poiché se questo è esaurito il sistema può bloccare la ricezione di nuovi messaggi. Se lo spazio generale è sufficiente, verifica anche lo spazio assegnato al singolo account email, perché una casella piena può impedire la ricezione anche se il server ha ancora spazio disponibile. Nel caso in cui entrambe le verifiche risultino corrette ma il problema persista, è consigliabile contattare il supporto per ulteriori controlli e assistenza.', 'Quando non ricevi nuove email, pur sapendo che ti sono state inviate, la causa più comune è la mancanza di spazio disponibile. È quindi necessario controllare lo spazio disco dell’account accedendo al pannello di gestione e verificando la voce relativa allo storage disponibile, perché un disco pieno impedisce la ricezione dei messaggi. Successivamente, è utile verificare anche lo spazio della singola casella email, in quanto un account pieno può bloccare l’arrivo di nuove email anche se lo spazio generale è ancora disponibile. Se dopo questi controlli il problema non è risolto, è opportuno contattare l’assistenza per un’analisi più approfondita.', 'Se la posta in arrivo non mostra nuovi messaggi anche se il sistema sembra funzionare, è probabile che lo spazio disponibile sia esaurito. Il primo controllo da effettuare è quello dello spazio disco complessivo tramite il pannello di controllo, verificando che sia ancora disponibile capacità per ricevere nuovi dati. In seguito, è importante controllare anche lo spazio assegnato alla specifica casella email, poiché una casella piena blocca automaticamente la ricezione. Qualora entrambe le condizioni risultino nella norma ma il problema continui, è consigliato rivolgersi al supporto tecnico per ulteriori verifiche e risoluzione del problema.', '2026-03-20 12:41:38'),
(317, 'Posta Elettronica', 'Non riesco ad accedere alla posta', 'Se non riesci ad accedere alla posta elettronica, è importante verificare alcuni aspetti di base. Innanzitutto assicurati di aver aperto il programma corretto per la gestione delle email, come Outlook, Webmail o Gmail, utilizzando eventualmente la funzione di ricerca del dispositivo. Successivamente controlla di aver inserito correttamente l’indirizzo email, verificando la presenza della chiocciola e del punto e assicurandoti che non ci siano spazi indesiderati. Un’altra causa molto comune è la password: inseriscila con attenzione, controllando maiuscole e minuscole e verificando che il tasto BLOC MAIUSC non sia attivo; se non la ricordi, utilizza la funzione di recupero password. È utile anche prestare attenzione a eventuali messaggi di errore, come “password errata”, “account bloccato” o “impossibile raggiungere il server”, e, se possibile, fare uno screenshot da fornire all’assistenza. Infine, verifica la connessione a Internet provando ad aprire un sito web: se non funziona, il problema potrebbe non essere legato alla posta ma alla rete.', 'Quando non riesci ad accedere alla posta, il problema può dipendere da diversi fattori comuni. Per prima cosa verifica di utilizzare l’applicazione corretta per la gestione delle email, come Outlook o Webmail, cercandola nel dispositivo se necessario. Controlla poi che l’indirizzo email sia scritto correttamente, senza errori di digitazione o spazi, e che contenga tutti gli elementi necessari come la chiocciola e il dominio. La password rappresenta spesso la causa principale: assicurati di inserirla correttamente, rispettando maiuscole e minuscole, e verifica che il tasto BLOC MAIUSC non sia attivo; in caso di dimenticanza, procedi con il recupero. Se compare un messaggio di errore, anche se non chiaro, è importante segnalarlo all’assistenza, possibilmente con uno screenshot. Infine, controlla la connessione Internet provando ad accedere a un sito web, per escludere problemi di rete.', 'Se l’accesso alla posta elettronica non funziona, è consigliabile eseguire alcune verifiche di base. Assicurati innanzitutto di aver aperto il programma corretto per la posta, come Outlook, Gmail o Webmail, utilizzando la ricerca del dispositivo se necessario. Verifica poi che l’indirizzo email sia stato inserito senza errori, controllando la presenza di chiocciola e dominio e l’assenza di spazi indesiderati. La password è un altro elemento critico: inseriscila con attenzione, rispettando maiuscole e minuscole e verificando che il BLOC MAIUSC non sia attivo; se non la ricordi, utilizza la funzione di recupero. Presta attenzione anche ai messaggi di errore che possono comparire, come problemi di connessione o credenziali errate, e conserva uno screenshot per eventuale assistenza. Infine, verifica che la connessione a Internet sia attiva provando a navigare su un sito web, così da escludere problemi legati alla rete.', '2026-03-20 12:43:25'),
(318, 'Posta Elettronica', 'Posso aggiungere cartelle al mio account IMAP?', 'Per rendere visibili nel proprio client di posta le cartelle create tramite protocollo IMAP, è necessario sottoscriverle manualmente. La creazione di una nuova cartella avviene generalmente cliccando con il tasto destro sull’account o sulla cartella principale e selezionando l’opzione “Crea cartella”, facendo attenzione a non utilizzare caratteri speciali non consentiti, ad eccezione del trattino e del trattino basso. Nei client come Outlook Express, dopo aver configurato l’account IMAP, è necessario accedere al menu “Strumenti”, selezionare “Cartelle IMAP” e utilizzare la funzione “Reimposta” per visualizzare tutte le cartelle disponibili, quindi scegliere quelle da sottoscrivere. In Outlook XP, 2003 e 2000, la procedura è simile ma prevede l’utilizzo dell’opzione “Visualizza dati” per visualizzare l’elenco delle cartelle e selezionare quelle desiderate. In Thunderbird, invece, è possibile accedere al menu “File”, selezionare “Ordina”, scegliere l’account e aggiornare l’elenco delle cartelle per poi sottoscrivere quelle di interesse.', 'Quando si utilizzano account IMAP, le cartelle create sul server non sempre vengono visualizzate automaticamente nel client di posta, rendendo necessaria la loro sottoscrizione manuale. È possibile creare una nuova cartella cliccando con il tasto destro sull’account e selezionando “Crea cartella”, evitando l’uso di caratteri speciali non supportati. Per visualizzare e sottoscrivere le cartelle, nei client come Outlook Express è necessario accedere al menu “Strumenti”, aprire “Cartelle IMAP” e utilizzare la funzione “Reimposta”, selezionando poi le cartelle da aggiungere. In Outlook 2000, XP e 2003, la procedura prevede l’uso dell’opzione “Visualizza dati” per ottenere l’elenco delle cartelle disponibili e selezionarle. In Thunderbird, invece, è sufficiente accedere alle impostazioni dell’account tramite il menu “File”, aggiornare l’elenco delle cartelle e sottoscrivere quelle desiderate per renderle visibili.', 'Le cartelle create con protocollo IMAP devono essere sottoscritte manualmente per essere visibili all’interno dei client di posta elettronica. La creazione di una nuova cartella avviene tramite il menu contestuale dell’account, facendo clic con il tasto destro e scegliendo “Crea cartella”, tenendo presente che alcuni caratteri speciali non sono supportati. Nei diversi client di posta la procedura di sottoscrizione varia: in Outlook Express si utilizza il menu “Strumenti” e la sezione “Cartelle IMAP” con l’opzione “Reimposta” per visualizzare e selezionare le cartelle; in Outlook 2000, XP e 2003 si accede sempre a “Cartelle IMAP” ma si utilizza “Visualizza dati” per selezionare le cartelle disponibili; in Thunderbird è invece necessario aggiornare l’elenco delle cartelle dall’interfaccia dell’account e sottoscrivere quelle desiderate. Questa operazione consente di sincronizzare correttamente le cartelle tra server e client.', '2026-03-20 12:45:52'),
(319, 'Posta Elettronica', 'Posta in Uscita SMTP', 'Per configurare correttamente la posta in uscita è necessario verificare le impostazioni SMTP all’interno del proprio client di posta. Se utilizzi il servizio, il server di posta in uscita deve essere impostato nel formato mail.nomedeldominio.xx, ad esempio mail.pippo.it, assicurandoti che sia attiva l’autenticazione utilizzando le stesse credenziali della posta in entrata, mentre la connessione SSL non deve essere abilitata. È inoltre importante tenere conto delle limitazioni sugli invii, pensate per prevenire blocchi automatici: nei client come Outlook è possibile inviare fino a 30 destinatari in CC o CCN per i piani Low Cost e Business base, mentre i piani Business avanzati consentono fino a 150 destinatari per singolo invio. Per quanto riguarda le mailing list inviate via web, i limiti sono di 200 invii all’ora per i piani base e fino a 1.500 invii orari per i piani Business.', 'Una corretta configurazione della posta in uscita richiede il controllo dei parametri SMTP nel proprio client email. Il server da utilizzare è generalmente mail.nomedeldominio.xx, come ad esempio mail.pippo.it, con autenticazione attiva tramite le stesse credenziali della posta in arrivo e senza abilitare la connessione SSL. Oltre alla configurazione tecnica, è fondamentale considerare i limiti di invio impostati per evitare blocchi: nei client come Outlook, i piani Low Cost e Business standard permettono fino a 30 destinatari in CC o CCN per singola email, mentre i piani Business avanzati arrivano fino a 150 destinatari. Le campagne inviate tramite webmail o sistemi online sono invece soggette a limiti orari pari a 200 invii per i piani base e fino a 1.500 per quelli Business.', 'Per garantire il corretto funzionamento della posta in uscita è necessario configurare in modo adeguato il server SMTP nel client di posta. Il server deve essere impostato nel formato mail.nomedeldominio.xx, ad esempio mail.pippo.it, con autenticazione attiva utilizzando le stesse credenziali della posta in entrata e senza attivare la connessione SSL. È importante anche rispettare le limitazioni sugli invii per evitare blocchi automatici del servizio: nei piani Low Cost e Business base è possibile inviare fino a 30 destinatari in CC o CCN per email, mentre nei piani Business avanzati il limite sale a 150 destinatari. Per le mailing list gestite via web, sono previsti limiti di 200 invii all’ora per i piani base e fino a 1.500 invii orari per i piani Business.', '2026-03-20 12:48'),
(320, 'Posta Elettronica', 'Procedura di Accesso alla webmail di cPanel', 'Per leggere la posta elettronica aziendale direttamente dal browser senza utilizzare un client di posta, è possibile accedere alla webmail di cPanel tramite un semplice URL. Apri il browser e digita nella barra degli indirizzi mail.tuodominio.it/webmail, sostituendo "tuodominio.it" con il nome effettivo del tuo dominio. Una volta confermato l’indirizzo, verrai reindirizzato alla schermata di login della webmail, che può apparire simile a https://srv3.network-utixo.it:2096/. Nella schermata di autenticazione, inserisci il tuo indirizzo email completo, ad esempio nome.cognome@tuodominio.it, e la password associata alla casella di posta. Assicurati di digitare correttamente maiuscole, minuscole e simboli. Dopo aver confermato l’accesso, potrai visualizzare la posta in arrivo, inviare messaggi, gestire bozze e organizzare le cartelle della casella. La webmail offre un’interfaccia completa che ti permette di lavorare con le email come se fossi in un client desktop, con la comodità di non dover installare alcun software aggiuntivo. Potrai inoltre utilizzare funzionalità avanzate come filtri automatici, firme personalizzate e regole di gestione dei messaggi, rendendo l’esperienza d’uso completa e sicura.', 'Se desideri consultare la posta elettronica direttamente dal browser, puoi utilizzare la webmail fornita dal tuo servizio cPanel. Per accedere, apri il browser e digita mail.tuodominio.it/webmail. Dopo aver premuto Invio, il sistema ti reindirizzerà alla pagina di login della webmail, ad esempio https://srv3.network-utixo.it:2096/. Qui dovrai inserire l’indirizzo email completo della casella, come info@tuodominio.it, e la password corrispondente. È importante verificare che la password sia corretta e che non siano attivi eventuali tasti BLOC MAIUSC o errori di digitazione. Una volta effettuato l’accesso, potrai leggere i messaggi in arrivo, inviare nuove email, gestire le bozze, spostare messaggi tra cartelle e creare nuove cartelle se necessario. La webmail supporta anche la gestione di filtri, firme e regole per l’organizzazione automatica dei messaggi. Questo ti permette di avere un’esperienza completa simile a quella di un client desktop, ma accessibile ovunque tramite browser, garantendo continuità di lavoro senza installare software aggiuntivo.', 'Per consultare la posta elettronica tramite browser, la webmail di cPanel rappresenta la soluzione più immediata e completa. Apri il browser e digita mail.tuodominio.it/webmail, sostituendo "tuodominio.it" con il nome del tuo dominio. Ad esempio, se il dominio è utixo.net, l’URL da inserire sarà mail.utixo.net/webmail. Premendo Invio, verrai indirizzato alla pagina di login, che potrebbe apparire come https://srv3.network-utixo.it:2096/. Nella schermata di autenticazione, inserisci l’indirizzo email completo, ad esempio nome@utixo.net, e la password della casella. Controlla che i caratteri siano corretti, evitando spazi o errori di maiuscole/minuscole. Dopo aver confermato, avrai accesso a tutte le funzionalità della webmail: consultare la posta in arrivo, inviare nuovi messaggi, gestire bozze, cestino e cartelle personalizzate. Inoltre, la webmail consente di impostare filtri automatici, risposte predefinite, firme personalizzate e notifiche, permettendo di gestire completamente la tua casella email direttamente dal browser senza installare alcun client. Potrai organizzare le cartelle secondo le tue esigenze, archiviare messaggi importanti e monitorare lo spazio disponibile della casella, garantendo sempre un’esperienza di utilizzo fluida e sicura.', '2026-03-20 12:54:18'),
(321, 'Posta Elettronica', 'Quota (spazio disponibile) Email', 'Nei piani non Exchange, tutte le caselle email personali non hanno limiti di spazio specifici, fatta eccezione per le caselle Exchange che seguono regole dedicate. In pratica, lo spazio disponibile per ciascuna casella dipende dalla quota complessiva dell’account principale del tuo piano hosting. È quindi consigliabile gestire con attenzione le quote per evitare che una singola casella assorba tutto lo spazio disponibile, creando problemi agli altri account o impedendo la ricezione di nuove email. Dal pannello di controllo puoi impostare manualmente la quota per ciascuna casella email, definendo così la quantità massima di spazio consentita. Ad esempio, se assegni 50 MB a una casella, questa potrà ricevere messaggi fino a 50 MB solo se lo spazio residuo dell’account principale è maggiore di tale valore. Questa regola impedisce errori di invio quando lo spazio complessivo è limitato. Una volta che l’email viene scaricata o eliminata, lo spazio occupato torna disponibile per nuovi messaggi. Impostare le quote è quindi un’ottima pratica per mantenere ordine, prevenire blocchi di invio e assicurare che tutti gli utenti possano utilizzare la posta senza interruzioni.', 'Per le caselle email dei piani non Exchange, non esistono limiti di spazio impostati per singola casella, salvo quelli derivanti dalla quota totale dell’account principale. Questo significa che puoi ricevere email fino al completamento dello spazio disponibile sull’account, senza restrizioni aggiuntive. Tuttavia, è buona prassi assegnare una quota a ciascuna casella tramite il pannello di gestione, in modo da evitare che messaggi di grandi dimensioni saturino lo spazio complessivo, bloccando la ricezione di nuove email. Ad esempio, se imposti una quota di 50 MB per una casella ma lo spazio totale dell’account principale è già quasi esaurito, il messaggio di 50 MB potrebbe non essere ricevuto correttamente. Dopo il download della mail, lo spazio liberato torna disponibile per altre comunicazioni. Questo sistema permette di mantenere un equilibrio tra le varie caselle e di gestire in maniera sicura allegati di grandi dimensioni, riducendo il rischio di blocchi o errori di consegna. Impostare correttamente le quote è particolarmente utile per ambienti condivisi, dove più utenti devono utilizzare la posta senza interferenze.', 'Nei piani hosting non Exchange, le caselle email personali non presentano limiti di spazio predefiniti, a differenza delle caselle Exchange che hanno regole specifiche. Lo spazio utilizzabile è quindi limitato unicamente dalla quota complessiva dell’account principale. Per evitare problemi di ricezione o saturazione dello spazio, è consigliabile definire una quota per ciascuna casella email direttamente dal pannello di controllo. Ad esempio, se assegni 50 MB a una casella email, questa sarà in grado di ricevere un messaggio di tale dimensione solo se lo spazio libero sull’account principale supera i 50 MB, ad esempio 50,1 MB. Questo garantisce che i messaggi non vengano rifiutati a causa della mancanza di spazio. Una volta scaricata o eliminata l’email, lo spazio occupato viene liberato automaticamente e torna disponibile per nuovi messaggi. Impostare quote regolari consente di prevenire problemi legati a email con allegati di grandi dimensioni, migliorando la gestione complessiva delle caselle e assicurando che tutti gli utenti possano usufruire del servizio senza interruzioni o blocchi. Questa pratica è particolarmente utile in contesti aziendali o quando più utenti condividono lo stesso account hosting.', '2026-03-20 12:56:37'),
(322, 'Posta Elettronica', 'Cosa sono SPF, DKIM e DMARC?', 'La posta elettronica ha una storia più lunga di quanto molti immaginino: nasce prima ancora di Internet. Il primo sistema sperimentale risale al 1965, sviluppato presso il MIT, dove la comunicazione avveniva all’interno di un singolo mainframe, enormi computer multiutente che richiedevano ambienti climatizzati e una supervisione continua. Solo nel 1971 si ha il primo scambio di email tra due computer connessi: un piccolo passo tecnologico, ma un grande balzo per la comunicazione digitale. Nel 1982 nasce SMTP, il protocollo tuttora alla base dello scambio di email su Internet. Tuttavia, le origini dell’email erano insicure: non esistevano autenticazione del mittente, riservatezza, controllo di integrità o protezione contro lo spam. Con il crescere dell’utilizzo, queste lacune sono diventate evidenti, e oggi la sicurezza deve essere implementata by design, come richiesto dal GDPR. Per proteggere la posta elettronica, gli strumenti fondamentali sono SPF, DKIM e DMARC: SPF dichiara quali IP possono inviare email per conto del dominio; DKIM garantisce l’integrità dei messaggi; DMARC verifica la coerenza tra mittente visualizzato e controlli SPF/DKIM. Oltre a questi, TLS, S/MIME e PGP offrono ulteriori livelli di protezione, ma richiedono conoscenze avanzate. Per una protezione efficace e completa, è consigliabile affidarsi a esperti per la configurazione.', 'Le email sono nate come strumenti collaborativi interni a grandi computer multiutente (mainframe) negli anni ’60, senza alcuna attenzione alla sicurezza. Solo nel 1971 avviene il primo scambio di messaggi tra due computer connessi e, con l’introduzione di SMTP nel 1982, le email diventano il metodo standard di comunicazione su reti digitali. Ma SMTP non prevedeva alcuna autenticazione, crittografia o protezione contro lo spam. Oggi, proteggere le email è fondamentale: SPF, DKIM e DMARC rappresentano la prima linea di difesa. SPF permette di dichiarare quali IP sono autorizzati a inviare posta per il tuo dominio, riducendo il rischio di spoofing. DKIM assicura che i messaggi non siano stati alterati durante il trasporto, grazie a una firma digitale automatica. DMARC integra i due sistemi precedenti e definisce le azioni da intraprendere se un’email non supera i controlli di autenticazione. Per aumentare ulteriormente la sicurezza, si possono utilizzare TLS per crittografia in transito e strumenti come S/MIME o PGP per la cifratura end-to-end. La combinazione di questi sistemi aumenta notevolmente la protezione della posta elettronica e contribuisce a ridurre rischi come phishing e spoofing, garantendo maggiore affidabilità nella comunicazione digitale.', 'La posta elettronica è nata molto prima di Internet, con i primi esperimenti al MIT nel 1965, all’interno di mainframe multiutente. Nel 1971 si ha il primo scambio di email tra due computer, e nel 1982 viene definito SMTP, il protocollo alla base di tutte le comunicazioni email. Inizialmente, le email non erano sicure: chiunque poteva inviare messaggi falsificando il mittente, i contenuti viaggiavano in chiaro e non esistevano controlli per verificare modifiche o prevenire lo spam. Con il tempo, la sicurezza è diventata essenziale, e oggi strumenti come SPF, DKIM e DMARC rappresentano il primo livello di protezione. SPF specifica gli IP autorizzati a inviare email per un dominio, DKIM verifica che i messaggi non siano stati alterati e DMARC definisce come trattare i messaggi non conformi. Altri strumenti, come TLS per la crittografia in transito e S/MIME o PGP per la cifratura end-to-end, completano il quadro della sicurezza. Per un’azienda, la strategia migliore consiste nell’implementare prima SPF, poi DKIM e infine DMARC, assicurandosi che siano configurati correttamente per evitare disservizi. La gestione avanzata della sicurezza email richiede competenze tecniche: per garantire affidabilità, integrità e protezione contro attacchi informatici, è consigliabile rivolgersi a professionisti esperti.', '2026-03-20 12:59:43'),
(323, 'Posta Elettronica', 'Configurazione del record SPF con Google g-suite(WorkSpace)', 'Un record SPF permette di indicare quali server possono inviare email per conto del tuo dominio, riducendo il rischio di spoofing. Per Google Workspace, il record SPF deve includere i server di Google e gli eventuali IP del tuo server web: v=spf1 ip4:<TUO_IP> include:_spf.google.com ~all. Questo aiuta i destinatari a riconoscere le email legittime e migliora la consegna.','Per configurare SPF in cPanel: Accedi a cPanel → Email → Autenticazione. Attiva SPF. Aggiungi _spf.google.com e eventuali IP del server web. Salva il record. Esempio: v=spf1 ip4:172.16.254.1 include:_spf.google.com ~all Così le email inviate da Gmail e dal tuo sito saranno riconosciute come sicure.', 'SPF autorizza solo i server indicati a inviare email per il dominio. Includi sempre Google Workspace (_spf.google.com) e eventuali IP aggiuntivi. Dopo la configurazione, verifica il record con strumenti online per assicurarti che le email arrivino correttamente senza finire nello spam.', '2026-04-01 09:33:34');
